      (cnt forall (_ % 2 == 0)) && ((cnt count (_ % 4 != 0)) <= even(H, W) / 2)
    } else {
      val odd = cnt count (_ % 2 == 1) // １こだけ配置する場所があるので奇数が一つだけ必要
      // ４の倍数ではない偶数の数が２こずつ配置する箇所よりちいさくないといけない
      odd == 1 && ((cnt count (_ % 4 != 0)) - 1 <= (H - 1) / 2 + (W - 1) / 2)
    }
    val ans = if (ok) "Yes" else "No"

    out.println(ans)
  }

  def main(args: Array[String]): Unit = {
