		oneWord = 1;
		twoWord = H + W - 2;
		fourWord = H * W - oneWord - twoWord;
	}
	else if (H % 2 == 1) {
		twoWord = W;
		fourWord = H * W - twoWord;
	}
	else if (W % 2 == 1) {
		twoWord = H;
		fourWord = H * W - twoWord;
	}
	else {
		fourWord = H * W;
	}


	map<char, int> mp;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
