		for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
			if (itr->second == 1) {
				--oneWord;
				--itr->second;
				check = false;
			}
			else if (itr->second >= 4 && fourWord != 0) {
				fourWord -= 4;
				itr->second -= 4;
				check = false;
			}
			else if (itr->second >= 2 && twoWord != 0) {
				twoWord -= 2;
				itr->second -= 2;
