void err() {
  cout << "No" << endl;
  exit(0);
}

int main()
{
  cin>>h>>w;
  int a=h*w;
  bool ht = h%2==0;
  bool wt = w%2==0;
  REP(i,h)
  {
    string s; cin>>s;
    for (char c : s) mp[c-'a']++;
  }

  if (ht&&wt)
  {
    REP(i,26) if (mp[i]%4!=0) err();
    cout << "Yes" << endl;
    return 0;
  }
  else if (ht||wt)
  {
    int left = a - (ht ? h : w);
    REP(i,26)
    {
      int s = mp[i];
      if (s/4!=0)
      {
        mp[i] -= min(left/4, s/4) * 4;
        left -= min(left/4, s/4) * 4;
      }
      if (left==0) break;
    }
    if (left!=0) err();
    REP(i,26)
    {
      if(mp[i]%2!=0) err();
    }
    cout << "Yes" << endl;
    return 0;
  }
  else if (!ht&&!wt)
  {
