    int left = (a - ((h-1) + (w-1) + 1)) / 4;
    REP(i,26)
    {
      int s = mp[i];
      if (s/4!=0)
      {
        mp[i] = s - min(s/4, left) * 4;
        left -= min(s/4, left);
      }
      if (left == 0) break;
    }
    if (left != 0) err();
    REP(i,26)
    {
      if (mp[i]%2!=0) err();
    }

    cout << "Yes" << endl;
    return 0;
  }
