bool is_all_mod2(map<char, int> &mp) {
  for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
    if (itr->second % 2 != 0) return false;
  }
  return true;
}

bool is_all_mod4(map<char, int> &mp) {
  for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
    if (itr->second % 4 != 0) return false;
  }
  return true;
}

int cnt_mod4_eq_2(map<char, int> &mp) {
  int ret = 0;
  for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
    if (itr->second % 4 == 2) ret += itr->second;
  }
  return ret;
}

int kind_mod4_eq_2(map<char, int> &mp) {
  int ret = 0;
  for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
    if (itr->second % 4 == 2) ret++;
  }
  return ret;
}

pair<char, int> mod4_eq_1_or_3(map<char, int> &mp) {
  int cnt = 0;
  char c;
  for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
    if (itr->second % 4 == 1 || itr->second % 4 == 3) {
      cnt++;
      c = itr->first;
    }
  }
  return make_pair(c, cnt);
}

