    if (!is_all_mod4(mp)) ans = "No";
  } else if ((h + w) % 2 != 0) {
    // (h,w) = (odd,even) or (even,odd)
    int odd_num = (h % 2 != 0) ? h : w;
    int even_num = (h % 2 != 0) ? w : h;
    bool mod4_flag = is_all_mod4(mp);
    bool mod2_flag = is_all_mod2(mp) && (kind_mod4_eq_2(mp) == even_num / 2);
    if (!mod4_flag && !mod2_flag) ans = "No";
