int H, W;
char s[10000];
int num[10000];
void solve(int count) {
  bool H_div2 = H % 2 == 0;
  bool W_div2 = W % 2 == 0;
  if (H_div2 && W_div2) {
    for (int i = 0; i < count; i++) {
      if (num[i] % 4 != 0) {
        cout << "No" << endl;
        return;
      }
    }
    cout << "Yes" << endl;
  } else if (!H_div2 && !W_div2) {
    int div4[4] = {0, 0, 0, 0};
    for (int i = 0; i < count; i++) {
      div4[num[i] % 4]++;
    }
    if (div4[1] + div4[3] <= 1 && (div4[2] + div4[3]) * 2 <= H + W - 1) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  } else {
    int div4[4] = {0, 0, 0, 0};
    int even;
    if (H_div2) {
      even = H;
    } else {
      even = W;
    }
    for (int i = 0; i < count; i++) {
      div4[num[i] % 4]++;
    }
    if (div4[1] == 0 && div4[3] == 0 && div4[2] * 2 <= even) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }
}

int main() {
  cin >> H >> W;
  for (int h = 0; h < H; h++) {
    string input;
    cin >> input;
    for (int w = 0; w < W; w++) {
      s[W * h + w] = input[w];
    }
  }
  int size = H * W;
  sort(s, s + size);
  char before = s[0];
  int count = 0;
  for (int i = 0; i < size; i++) {
    if (s[i] != before) {
      count++;
      before = s[i];
    }
    num[count]++;
  }
  count++;
  solve(count);

  return 0;
}

