int H;
int W;
char as[114][514];
map<char, int> cnt;
int permit;
bool special;

int main() {
  scanf("%d%d", &H, &W);
  for (int i=0; i<H; i++) {
    for (int j=0; j<W; j++) {
      scanf(" %c", &as[i][j]);
      cnt[as[i][j]]++;
    }
  }


  if (H%2 == 1) permit += W/2;
  if (W%2 == 1) permit += H/2;
  if (permit == H+W) {
    special = true;
  }

  for (auto itr : cnt) {
    if (itr.second%2 == 1) {
      if (!special) {
        puts("No");
        return 0;
      }
      special = false;
      itr.second--;
    }

    if (itr.second%4 != 0) {
      assert(itr.second%2 == 0);
      if (permit <= 0) {
        puts("No");
        return 0;
      }
      permit--;
    }
  }
  puts("Yes");

  return 0;
}

