main(){
    int N,M;
    int cnt[26] = {};
    cin >> N >> M;
    string S;
    for(int i = 0;i < N;i++){
        cin >> S;
        for(char c:S)cnt[c-'a']++;
    }
    sort(cnt,cnt+26,greater<int>());
//    vector<int> num((N+1)/2*(M+1)/2,4);
    int num[3] = {};//1 2 4
    if(N == 1 ^ M == 1){
        num[1] = max(N,M)/2;
        num[0] = max(N,M)&1;
    }else if(N == 1 && M == 1){
        num[0] = 1;
    }else if((N&1) && (M&1)){
        num[0] = 1;
        num[1] = (N/2)+(M/2);
        num[2] = (N+1)/2*(M+1)/2;
    }else if((N&1) ^ (M&1)){
        int even = N&1?M:N;
        int odd = N+M - even;
        num[1] = even/2;
        num[2] = odd/2 * (even/2);
    }else{
        num[2] = (N/2)*(M/2);
    }
    for(int i = 0;i < 26;i++){
        for(int j = 2;j >= 0;j--){
            if(num[j] == 0)continue;
            int d = 1 << j;
            int dif = cnt[i] / d;
            if(num[j] < dif){
                cnt[i] -= d*num[j];
                num[j] = 0;
            }else{
                num[j] -= dif;
                cnt[i] -= dif*d;
            }
        }
    }
    if(num[0] | num[1] | num[2]){
        cout << "No" << endl;
    }else{
        cout << "Yes" << endl;
    }
