const int Maxl = 26;
const int Maxd = 5;

int n, m;
int freq[Maxl];
int all[Maxd];

int main()
{
	scanf("%d %d", &n, &m);
	for (int i = 0; i < n; i++)
		for (int j = 0; j < m; j++) {
			char ch; scanf(" %c", &ch);
			freq[ch - 'a']++;
		}
	for (int i = 0; i <= n - i - 1; i++)
		for (int j = 0; j <= m - j - 1; j++)
			if (i == n - i - 1 && j == m - j - 1) all[1]++;
			else if (i == n - i - 1 || j == m - j - 1) all[2]++;
				 else all[4]++;
	for (int i = 0; i < Maxl; i++) {
		if (freq[i] % 2) {
			if (all[1] == 0) { printf("No\n"); return 0; }
			freq[i]--; all[1]--;
		}
		if (freq[i] % 4 == 2) {
			if (all[2] == 0) { printf("No\n"); return 0; }
			freq[i] -= 2; all[2]--;
		}
	}
	for (int i = 0; i < Maxl; i++)
		for (int j = 1; j < Maxd; j++) if (all[j] > 0 && freq[i] >= j) {
			all[j]--; freq[i] -= j;
		}
	for (int i = 1; i < Maxd; i++) if (all[i] > 0) { printf("No\n"); return 0; }
	printf("Yes\n");
	return 0;
}

