    int h, w;
    cin >> h >> w;
    vector<int> cnt(26, 0);
    rep(i, h) rep(j, w) {
        char c;
        cin >> c;
        ++cnt[c-'a'];
    }
    if (h % 2 == 0 && w % 2 == 0) {
        rep(i, 26) {
            if (cnt[i] % 4 != 0) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    else {
        bool odd_odd = (h % 2 != 0 && w % 2 != 0) ? true : false;
        int lim_num = h * w - (h + w - 1);
        int tmp_cnt = 0;
        bool ok = false;
        rep(i, 26) {
            if (cnt[i] >= 4) {
                tmp_cnt += cnt[i] / 4 * 4;
                cnt[i] -= cnt[i] / 4 * 4;
            }
            if (tmp_cnt >= lim_num) {
                cnt[i] += tmp_cnt - lim_num;
                ok = true;
                break;
            }
        }
        if (!ok) {
            cout << "No" << endl;
            return 0;
        }
        bool odd = false;
        rep(i, 26) {
            if (cnt[i]&1) {
                if (!odd_odd) {
                    cout << "No" << endl;
                    return 0;
                }
                else if (!odd) {
                    odd = true;
                }
                else {
                    cout << "No" << endl;
                    return 0;
                }
            } 
        }
    }
    cout << "Yes" << endl;

    return 0;
}

