    vector<string> a(h);
    for(int i=0;i<h;i++){
        cin>>a[i];
        for(int j=0;j<w;j++){
            cnt[a[i][j]-'a']++;
        }
    }

    int oddcnt=0;
    int twocnt=0;
    for(int i=0;i<cnt.size();i++){
        if(cnt[i]%2==1){
            oddcnt++;
        }
        if((cnt[i]-cnt[i]%2)%4!=0){
            twocnt+=2;
        }
    }
    bool isyes=true;
    if(h%2==0 && w%2==0){
        isyes=(oddcnt==0 && twocnt==0);
    }
    else if(h%2==1 && w%2==0){
        isyes=(twocnt<=w && oddcnt==0);
    }
    else if(h%2==0 && w%2==1){
        isyes=(twocnt<=h && oddcnt==0);
    }
    else{
        isyes=(twocnt<=w+h-2 && oddcnt==1);
    }
    cout<<(isyes ? "Yes" : "No")<<endl;
    return 0;
