    }
    if (h % 2 == 1 && w % 2 == 1) {
        int c2 = h + w - 2;
        int c[4] = {};
        REP(i,0,26) {
            if (cnt[i] >= 4) {
                c[2] += cnt[i] / 4;
                cnt[i] %= 4;
            }
            if (cnt[i] == 0) ++c[3];
            else if (cnt[i] % 2 == 0) ++c[1];
            else if (cnt[i] == 1) ++c[0];
        }
        if (c[1] < c2/2) {
            c[1] == c2 / 2;
            c[2] -= (c2 / 2 - c[1] + 1) / 2;
        }
        if (c[0] == 1 && c[2] == (h * w - c2 - 1) / 4) cout << "Yes" << endl;
