struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int n, m; scan(n, m);
      std::string field[112];
      for(Int i = 0; i < n; ++i) {
         scan(field[i]);
      }
      Int count[128] = {};
      for(Int i = 0; i < n; ++i) {
         for(Int k = 0; k < m; ++k) {
            count[field[i][k]] += 1;
         }
      }
      Int p4 = 0, p2 = 0, p1 = 0;
      for(Int i = 0; i < 128; ++i) {
         while( count[i] >= 4 ) {
            p4 += 1;
            count[i] -= 4;
         }
         while( count[i] >= 2 ) {
            p2 += 1;
            count[i] -= 2;
         }
         p1 += count[i] % 2;
      }
      Int ts[4] = {(n/2) * (m/2),(n/2) * (m%2),(n%2) * (m/2),(n%2) * (m%2)};
      bool res = p4 >= ts[0] and p4 + p2 >= ts[0] + ts[1] + ts[2] and p4 + p2 + p1 >= ts[0] + ts[1] + ts[2] + ts[3];
      puts(res ? "Yes" : "No");
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

