            if(!tmp_cnt) tmp_cnt = 1;
            hp.push(tmp_cnt);
//            // DEBUG
//            for(auto p : mp) cout << p.second << ' ';
//            cout << '\n';
        }
    }

    while(hp.size()) {
        tmp = hp.top(); hp.pop();
        for(auto iter = mp.begin(); iter != mp.end(); ++iter) {
            if(iter->second >= tmp) {
                iter->second -= tmp;
                tmp = -1;
                break;
            }
        }
        if(tmp != -1) can = false;
    }

    if(can) cout << "Yes" << '\n';
    else cout << "No" << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

