    for (char c : s) mp[c-'a']++;
  }

  if (ht&&wt)
  {
    REP(i,26)
    {
      if (mp[i]%4!=0)
      {
        cout << "No" << endl;
        return 0;
      }
    }
    cout << "Yes" << endl;
    return 0;
  }

  else if (ht||wt)
  {
    REP(i,26)
    {
