      if (mp[i]%2!=0)
      {
        cout << "No" << endl;
        return 0;
      }
    }
    cout << "Yes" << endl;
    return 0;
  }

  else if (!ht&&!wt)
  {
    REP(i,26)
    {
      int s = mp[i];
