	int H, W;
	cin >> H >> W;
	VS s(H);
	FOR(i, 0, H) {
		cin >> s[i];
	}
	VI a(26, 0);
	FOR(i, 0, H) {
		FOR(j, 0, W) {
			a[s[i][j] - 'a']++;
		}
	}
	ans = 1;
	int c1 = 0, c2 = 0;
	FOR(i, 0, 26) {
		if (a[i] % 4 == 2)c2++;
		if (a[i] % 2 == 1)c1++;
	}
	if (c1 > 1)ans = 0;
	if (c1 && ((H % 2 == 0) || (W % 2 == 0)))ans = 0;
	if (H % 2 == 1)c2 -= W / 2;
	if (W % 2 == 1)c2 -= H / 2;
	if (c2 > 0)ans = 0;

	cout << (ans ? "Yes" : "No") << "\n";

	return 0;
}

