        n4 += occ[i] / 4;
    }
    bool ok = true;
    bool hh = h % 2, ww = w % 2;
    if(!hh && !ww) {
        if(n2 || n1) {
            ok = false;
        }
    } else if(hh && ww) {
        if(n1 != 1) {
            ok = false;
        }
        int needed = h / 2 + w / 2;
        while(n4 && n2 < needed) {
            n4--;
            n2 += 2;
        }
        if(n2 != needed) {
            ok = false;
        }
    } else {
        if(ww) {
            swap(w, h);
        }
        int needed = w / 2;
        while(n4 && n2 < needed) {
            n4--;
            n2 += 2;
        }
        if(n2 != needed) {
            ok = false;
        }
    }
    cout << (ok ? "Yes" : "No") << endl;
    return 0;
}

