void solve()
{
	int cnt[26];
	CLR(cnt);
	int n, m;
	cin >> n >> m;
	for (int i(1); i <= n; ++i)
		for (int j(1); j <= m; ++j)\
		{
			char c;
			cin >> c;
			++cnt[c - 'a'];
		}
	int p4(0), p2(0), p1(0);
	if ((n & 1) && (m & 1))
	{
		p1 = 2;
		p4 = n * m - n - m + 1;
		p2 = m + n - 2;
	}
	else if (n & 1)
	{
		p1 = 0;
		p4 = n * m - m;
		p2 = m;
	}
	else if (m & 1)
	{
		p1 = 0;
		p4 = n * m - n;
		p2 = n;
	}
	else
	{
		p1 = p2 = 0;
		p4 = n * m;
	}
	for (int i(0); i < 26; ++i)
		while (cnt[i] >= 4 && p4)
		{
			cnt[i] -= 4;
			p4 -= 4;
		}
	for (int i(0); i < 26; ++i)
		while (cnt[i] >= 2 && p2)
		{
			cnt[i] -= 2;
			p2 -= 2;
		}
	for (int i(0); i < 26; ++i)
		while (cnt[i] >= 1 && p1)
		{
			p1 -= 1;
			cnt[i] -= 1;
		}
	for (int i(0); i < 26; ++i)
		if (cnt[i]){
			cout << "No\n";
			return;
		}
	cout << "Yes\n";
}

