        REP(j, W) {
            C[A[i][j] - 'a']++;
        }
    }

    bool success = true;
    REP(h, (H + 1) / 2) {
        REP(w, (W + 1) / 2) {
            ll s = 1;
            if (H - h - 1 != h)
                s *= 2;
            if (W - w - 1 != w)
                s *= 2;

            bool f = false;
            REP(n, 27) {
                if (C[n] >= s) {
                    f = true;
                    C[n] -= s;
                    break;
                }
            }

            if (!f)
                success = false;
        }
    }

    if (success)
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
    return 0;
}

