    if (isOdd > 1) {
        cout << "No" << endl;
        return;
    }

    if (isOdd == 1 && (H % 2 == 0 || W % 2 == 0)) {
        cout << "No" << endl;
        return;
    }

    if (isOdd == 0 && H % 2 == 1 && W % 2 == 1) {
        cout << "No" << endl;
        return;
    }

    int mincnt = min(H/2, W/2);
