int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);
  int H, W;
  cin >> H >> W;
  map<char, int> cnt;
  int g1, g2, g4;
  if (H % 2 && W % 2) {g1 = 1; g2 = H/2 + W/2; g4 = (H/2)*(W/2);}
  else if (H % 2 == 0 && W % 2 == 0) {g1 = 0; g2 = 0; g4 = (H*W)/4;}
  else if (H % 2 && W % 2 == 0) {g1 = 0; g2 = W/2; g4 = W/2 * H/2;}
  else if (H % 2 == 0 && W % 2) {g1 = 0; g2 = H/2; g4 = H/2 * W/2;}
  VC alp;
  REP(i, H) REP(j, W)
  {
    char a;
    cin >> a;
    cnt[a]++;
    alp.push_back(a);
  }
  UNIQUE(alp);

  priority_queue<int> que;
  REPx(x, alp) que.push(cnt.at(x));

  while(que.size())
  {
    int x = que.top(); que.pop();
    if (g4 > 0 && x >= 4)
    {
      x -= 4;
      g4--;
    }
    else if (g2 > 0 && x >= 2)
    {
      x -= 2;
      g2--;
    }
    else if (g1 > 0 && x >= 1)
    {
      x--;
      g1--;
    }
    else
    {
      que.push(x);
      break;
    }
    if (x != 0) que.push(x);
  }

  if (que.size()) cout << "No" << endl;
  else cout << "Yes" << endl;

  return 0;
}

