    int h, w;
    cin >> h >> w;
    map<char, int> m;
    rep(i, h) {
        rep(j, w) {
            char a;
            cin >> a;
            ++m[a];
        }
    }

    if (h % 2 == 0 && w % 2 == 0) {
        bool flag = true;
        stl_rep(itr, m) {
            if (itr->second % 4) {
                flag = false;
                break;
            }
        }

        if (flag) cout << "Yes" << endl;
        else cout << "No" << endl;
    } else {
        bool e_flag = true;
        if (h % 2 == 0 || w % 2 == 0) {
            if (h % 2 == 1) swap(h, w);
            e_flag = false;
        }
        int g1 = e_flag ? 1 : 0;
        int g2 = e_flag ? floor((double)h / 2) + floor((double)w / 2) : h / 2;
        int g4 = floor((double)h / 2) * floor((double)w / 2);
        rep(i, g1) {
            stl_rep(itr, m) {
                if (itr->second % 4 == 1 || itr->second % 4 == 3) {
                    itr->second = max(itr->second - 1, 0);
                    break;
                }
            }
        }
        rep(i, g2) {
            stl_rep(itr, m) {
                if (itr->second % 4 == 2) {
                    itr->second = max(0, itr->second - 2);
                    break;
                }
            }
        }
        rep(i, g4) {
            stl_rep(itr, m) {
                if (itr->second == 0) continue;
                if (itr->second % 4 == 0) {
                    itr->second = max(0, itr->second - 4);
                    break;
                }
            }
        }

        bool flag = true;
        stl_rep(itr, m) {
            if (itr->second != 0) {
                flag = false;
                break;
            }
        }
        if (flag) cout << "Yes" << endl;
        else cout << "No" << endl; 
    }
}

