    for (auto p : cnt) {
        if (fill == 0) break;
        while (p.second >= 4 && fill > 0) {
            p.second -= 4;
            fill -= 4;
        }
        cnt[p.first] = p.second;
    }

    if (fill > 0) {
        cout << "No" << endl;
        return 0;
    }

    int odd = 0;
    for (auto p : cnt) {
        if (p.second % 2) {
            odd++;
            p.second--;
            cnt[p.first] = p.second;
        }
    }

    bool haveOdd = (h&w&1);

    if (odd != haveOdd) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;

    return 0;
}

