// 問題考察
// 条件を満たすためには、特定のマスに同じ文字を書かなければならない。
// h,wを変えて小さいh,wでシミュレーションをしたところ、同じ文字でなければならないマスが何個あるかわかった。

// h,wが偶数のとき
// 同じ文字が書かれた4マス h*w/4個

// hが偶数、wが奇数（逆なら転置して）
// 同じ文字が書かれた4マス h*(w-1)/4個
// 同じ文字が書かれた2マス h*1/2個

// h,wが奇数
// 同じ文字が書かれた4マス (h-1)*(w-1)/4個
// 同じ文字が書かれた2マス (h-1+w-1)/2個
// 同じ文字が書かれた1マス 1個

// 式を簡潔に書き表す
// hh = h-h%2, ww = w-w%2
// 4 hh*ww/4
// 2 (h%2*ww+w%2*hh)/2
// 1 (h%2)*(w%2)

// 後はAの文字を数えて↑に割り当てて行けばいい
// 4マス→2マス、1マスの順で割り当てていく

#include <algorithm>
