signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int h, w;
    cin >> h >> w;

    array<int, 'z' - 'a' + 1> chars = {};

    for (int i = 0; i < h * w; i++) {
        char a;
        cin >> a;
        chars[a - 'a']++;
    }

    const int hh = h - h % 2, ww = w - w % 2;

    int s4 = hh * ww / 4;
    int s2 = (h % 2 * ww + w % 2 * hh) / 2;
    int s1 = (h % 2) * (w % 2);

    array<int, 3> a{4, 2, 1};
    array<int, 3> sqs{s4, s2, s1};

    priority_queue<int> pq;
    for (auto &&i : chars) {
        if (i > 0) pq.emplace(i);
    }

    for (int i = 0; i < 3; i++) {
        while (sqs[i] > 0) {
            if (pq.top() >= a[i]) {
                const int top = pq.top();
                pq.pop();
                if (top - a[i] > 0) pq.emplace(top - a[i]);
                sqs[i]--;
            } else
                break;
        }
    }

    cout << (pq.empty() ? "Yes" : "No") << endl;
}

