    vector<ll> cnt(26, 0);
    Rep (i, H*W) {
        char a;
        cin >> a;
        cnt[a-'a']++;
    }

    priority_queue<ll> q;
    for (ll e : cnt) {
        if (e != 0) {
            q.push(e);
        }
    }

    ll n4 = 0, n2 = 0, n1 = 0;

    if (H*W % 2 == 1) {
        n1 = 1;
        n2 = (H-1)/2 + (W-1)/2;
        n4 = (H-1/2) * (W-1)/2;
    } else if (H % 2 == 1 || W % 2 == 1) {
        if (W % 2 == 1) swap(H, W);
        n2 = W/2;
        n4 = W/2 * (H-1)/2;
    } else {
        n4 = W*H/4;
    }

    while (q.size()) {
        ll target = q.top();
        q.pop();
        if (n4 > 0 && target >= 4) {
            target -= 4;
            n4--;
        } else if (n2 > 0 && target >= 2) {
            target -= 2;
            n2--;
        } else if (n1 > 0 && target >= 1) {
            target--;
            n1--;
        } else {
            q.push(target);
            break;
        }

        if (target != 0) q.push(target);
    }

    if (q.size()) cout << "No\n";
    else cout << "Yes\n";
}

