{
	int H, W; cin >> H >> W;
	map<char, int> ch2NumMap;
	REP(i, H * W) {
		char ch; cin >> ch; ++ch2NumMap[ch];
	}
	int fourPairNum = (H / 2) * (W / 2);
	int twoPairNum = (H % 2) * (W / 2) + (H / 2) * (W % 2);
	int singleNum = (H % 2 == 1 && W % 2 == 1) ? 1 : 0;
	if (singleNum == 1)
	{
		for (auto &kvp : ch2NumMap)
		{
			if (kvp.second % 4 == 1 || kvp.second % 4 == 3)
			{
				--singleNum;
				--kvp.second;
				break;
			}
		}
	}
	for (auto &kvp : ch2NumMap)
	{
		for (;;)
		{
			if (kvp.second >= 4)
			{
				--fourPairNum;
				kvp.second -= 4;
				if (fourPairNum == 0) break;
			}
			else
			{
				break;
			}
		}
		if (fourPairNum == 0) break;
	}
	for (auto &kvp : ch2NumMap)
	{
		if (kvp.second % 4 == 2)
		{
			--twoPairNum;
			kvp.second -= 2;
		}
		if (twoPairNum == 0) break;
	}
	bool isYes = true;
	for (const auto &kvp : ch2NumMap)
	{
		if (kvp.second != 0)
		{
			isYes = false;
			break;
		}
	}
	cout << (isYes ? "Yes" : "No") << endl;
}

