template<class T>
T binary(T key,const vector<T> &g){
    T ng = -1;
    T ok = (T)g.size();
    while(abs(ok-ng)>1){
        T mid = (ok+ng)/2;
        if(gcd(g[mid],key)==1){
            ok = mid;
        }
        else{
            ng = mid;
        }
    }
    return ok;
}

