    string res(W,'x');
    assert(W % 2 == odd.size());
    if(W % 2 == 1){
        res[W / 2] = odd.front();
    }
    for(int i = 0; i < even.size(); ++i)
        res[i] = res[W - 1 - i] = even[i];
    return res;
}
