int count[42];
int d[42];

int main() {
  int n, m;
  scanf("%d%d", &n, &m);
  for (int i = 0; i < n * m; i++) {
    int c = getchar();
    while (c <= 32) c = getchar();
    count[c - 'a']++;
  }
  if (n % 2 == 1 && m % 2 == 1) {
    d[0] = 1;
    d[1] = n / 2 + m / 2;
  } else if (n % 2 == 1) {
    d[0] = 0;
    d[1] = m / 2;
  } else if (m % 2 == 1) {
    d[0] = 0;
    d[1] = n / 2;
  } else {
    d[0] = 0;
    d[1] = 0;
  }
  for (int i = 0; i < 26; i++) {
    if (count[i] % 2 == 1) {
      --d[0];
      count[i]--;
    }
    if (count[i] % 4 == 2) {
      --d[1];
    }
  }
  puts(d[0] == 0 && d[1] >= 0 && d[1] % 2 == 0 ? "Yes" : "No");
}

