	int p4(n * m), p2(0), p1(0);
	if (n & 1)
	{
		p4 -= m;
		p2 += m;
	}
	if (m & 1)
	{
		p4 -= n;
		p2 += n;
	}
	if ((n & 1) && (m & 1))
	{
		--p2;
		++p1;
	}
	for (pair <char, int> t : cnt)
		while (t.second)
		{
			if (t.second >= 4 && p4)
