bool solve(lli h, lli w, vector<lli> cnt) {
    lli r1 = (h%2)*(w%2);
    lli r2 = (h%2)*(w/2)+(w%2)*(h/2);
    assert  ((h * w - 2 * r2 - r1) % 4 == 0);
    lli r4 = (h*w-2*r2-r1) / 4;
    rep(i, 26){
