        while(r4 > 0 && cnt[i] >= 4) cnt[i]-=4, r4--;
    }
    if(r4 > 0) return false;
    for (int c = 0; r2--; ) {
        while (c < 26 && cnt[c] < 2) c++;
        if (c == 26) return false;
        cnt[c] -= 2;
    }
    return true;
}

