  rep(i,h) {
    string s;
    cin >> s;
    tmp += s;
    rep(j,w) ++vec[s[j]-'a'];
  }

  if( h == 1 || w == 1 ) {
    if( check(tmp,((h==1)?w:h)) ) {
      puts("Yes");
    } else {
      puts("No");
    }
    return 0;
  }
  puts(compute(vec,h,w)?"Yes":"No");
  return 0;
}

