    while(!pq.empty()) {
        auto top = pq.top();
        pq.pop();

        auto exec = [&](auto num) {
                        auto div = top / num;
                        auto rm  = top % num;
                        rm += max(div - pair_table[log2(num)], 0) * num;
                        pair_table[log2(num)] = max(pair_table[log2(num)] - div, 0);
                        if(rm != 0) pq.push(rm);
                    };

        auto prev_pair_table = pair_table;
        if(4 <= top) {
            exec(4);
        }
        else if(2 <= top) {
            exec(2);
        }
        else if(1 <= top) {
            exec(1);
        }

        if(pair_table == prev_pair_table) {
            ans = "No";
            break;
        }
    }

    std::cout << ans << std::endl;

    return 0;
