int h, w;
string s[100];
int cnt[26];

int main() {
	int i, j;

	cin >> h >> w;
	for (i = 0; i < h; i++) cin >> s[i];

	for (i = 0; i < h; i++) {
		for (j = 0; j < w; j++) {
			cnt[s[i][j] - 'a']++;
		}
	}

	int rCnt4 = ((h / 2) * 2) * ((w / 2) * 2) / 4;
	int rCnt2 = (h % 2) * (w / 2) + (w % 2) * (h / 2);
	int rCnt1 = (h % 2 == 1 && w % 2 == 1);

	for (i = 0; i < 26; i++) {
		int x = cnt[i];
		int useNum;

		useNum = min(rCnt4, x / 4);
		rCnt4 -= useNum;
		x -= useNum * 4;

		useNum = min(rCnt2, x / 2);
		rCnt2 -= useNum;
		x -= useNum * 2;

		useNum = min(rCnt1, x);
		rCnt1 -= useNum;
		x -= useNum;

		if (x > 0) { cout << "No" << endl; return 0; }
	}

	if (rCnt4 > 0 || rCnt2 > 0 || rCnt1 > 0) { cout << "No" << endl; }
	else { cout << "Yes" << endl; }
	return 0;
}

