            while(mp[m.first] > 0){
                mp[m.first] -= 4;
                g4--;
                if (g4 == 0) break;
            }
        }
        if (g4 == 0) break;
    }

    for(auto m: mp){
        if (m.second != 0){
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
    return 0;
}

