void solve(){
	int H,W;
	cin >> H >> W;
	vector< vector<int> > fld(H,vector<int>(W) );
	vector<int> hist(26,0);
	for(int h=0;h<H;++h){
		string str;
		cin >> str;
		for(int w=0;w<W;++w){
			fld[h][w] = str[w]-'a';
			hist[ fld[h][w] ]++;
		}
	}
	//////////////
	int P1=0;
	int P2=0;
	int P4=0;
	for(int i=0;i<26;++i){
		int res = hist[i];
		P4 += res/4;
		res %= 4;
		P2 += res/2;
		res %= 2;
		P1 += res;
	}
	bool flag = false;
	if( H%2 == 0 && W%2 == 0 ){
		if( P1 == 0 && P2 == 0 ){
			flag = true;
		}
	}else if( H%2 == 1 && W%2 == 1 ){
		if( P1 == 1 && P2 <= (H/2)+(W/2) ){
			flag = true;
		}
	}else{
		int res;
		if( H%2 == 0 ){//Hが偶数
			res = H/2;
		}else{
			res = W/2;
		}
		if(P1 == 0 && P2 <= res ){
			flag = true;
		}
	}

	if(flag ){
		cout << "Yes" << endl;
	}else{
		cout << "No" << endl;
	}
}

