void solve() {
	ll H;
	cin >> H;
	ll W;
	cin >> W;
	map<ll, ll> mp;
	rep(i, H) {
		string S;
		cin >> S;
		ll N = S.size();
		rep(j, W) {
			mp[(ll)(S[j] - 'a')]++;
		}
	}

	vll odd(0);
	vll four(0);
	vll two(0);
	auto begin = mp.begin(), end = mp.end();
	for (auto iter = begin; iter != end; iter++) {
		// iter->first: key, iter->second: value
		if (iter->second % 2 > 0) {
			odd.push_back(iter->second);
		}
		else if (iter->second % 4 == 0) {
			four.push_back(iter->second);
		}
		else {
			two.push_back(iter->second);
		}
	}

	bool result = true;

	if (H % 2 == 0 && W % 2 == 0) {
		//すべて4の倍数のときだけOK
		if (odd.size() > 0 || two.size() > 0) {
			result = false;
		}
	}
	else if (H % 2 != 0 && W % 2 != 0) {
		//奇数はひとつだけか
		if (odd.size() != 1) {
			result = false;
		}
		else {
			//ひとつだけ中心に固定する
			ll last = odd[0] - 1;
			if (last > 0) {
				if (last % 4 == 0) {
					four.push_back(last);
				}
				else {
					two.push_back(last);
				}
			}

			//中心十字に入る2ペア数
			ll centerSet = (H + W - 2) / 2;
			if (two.size() > centerSet) {
				result = false;
			}
			else {
				//centerSet - two.size() だけ4の倍数セットを切り崩す
				if ((centerSet - two.size()) % 2 == 0) { //奇数セット崩す場合は2個セットが生じるのでNG
					result = true;
				}
				else {
					result = false;
				}
			}
		}
	}
	else {
		//奇数があればNG
		if (odd.size() > 0) {
			result = false;
		}
		else {
			//中心線に入る2ペア数
			ll evenHW = H % 2 == 0 ? H : W;
			ll centerSet = evenHW / 2;
			if (two.size() > centerSet) {
				result = false;
			}
			else {
				//centerSet - two.size() だけ4の倍数セットを切り崩す
				if ((centerSet - two.size()) % 2 == 0) { //奇数セット崩す場合は2個セットが生じるのでNG
					result = true;
				}
				else {
					result = false;
				}
			}
		}
	}

	if (result == true) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}
}

