typedef int64_t ll;
typedef vector<int8_t> vcc;
typedef vector<vcc> vvcc;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll h, w;
        in >> h >> w;
        vvcc a(h, vcc(w));
        ll alpha[26] = {};
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                in >> a[i][j];
                alpha[a[i][j] - 'a']++;
            }
        }
        ll g1 = 1;
        ll g2 = h / 2 + w / 2;
        ll g4 = (h / 2)*(w / 2);
        while (g1-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (alpha[i] % 4 == 1 || alpha[i] % 4 == 3) {
                    alpha[i]--;
                    break;
                }
            }
        }
        while (g2-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (alpha[i] % 4 == 2) {
                    alpha[i] -= 2;
                    break;
                }
            }
        }
        while (g4-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (alpha[i] % 4 == 0) {
                    alpha[i] -= 4;
                    break;
                }
            }
        }
        ll sum = 0;
        for (int i = 0; i < 26; ++i) {
            sum += alpha[i];
        }
        out << (sum == 0 ? "Yes" : "No") << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
