using namespace std;
typedef int64_t ll;
typedef vector<int8_t> vcc;
typedef vector<vcc> vvcc;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll h, w;
        in >> h >> w;
        vvcc a(h, vcc(w));
        ll alpha[26] = {};
        rep(i, h) {
            rep(j, w) {
                in >> a[i][j];
                alpha[a[i][j] - 'a']++;
            }
        }
        ll sum = h * w;
        for (int _ = 0; _ < 100000; _++) {
            for (size_t i = 0; i < 26; i++) {
                if (sum >= 4 && alpha[i] >= 4) {
                    alpha[i] -= 4;
                    sum -= 4;
                }
                else if (!(h == 2 && w == 2) && sum >= 2 && alpha[i] >= 2) {
                    alpha[i] -= 2;
                    sum -= 2;
                }
                else if (sum == 1 && alpha[i] == 1) {
                    sum -= 1;
                    alpha[i] -= 1;
                }
            }
        }
        out << (sum == 0 ? "Yes" : "No") << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
