void solve(void){

	int H, W;
	cin >> H >> W;

	vector <string> maze(H);
	map <int, int> mp;

	rep(H, i)
	{
		cin >> maze[i];
		rep(W, j)
		{
			mp[maze[i][j]-'a']++;
		}
	}

	int h = (H+1)/2, w = (W+1)/2;

	rep(h, i) rep(w, j)
	{

		if (i == h-1 && j == w-1 && h*2 != H && w*2 != W)
		{
			rep(26, c)
			{
				if (mp[c] == 1)
				{
					mp[c] = 0;
					break;
				}
			}
		}
		else if ((i == h-1 && h*2 != H) || (j == w-1 && w*2 != W))
