				char c;
				scanf(" %c", &c);
				cnt[c - 'a']++;
			}
		}
		int num1 = 0, num2 = 0, num4 = 0;
		for(int i = 0; i < 26; i++){
			int temp = cnt[i] / 4;
			num4 += temp;
			cnt[i] -= 4 * temp;
			temp = cnt[i] / 2;
			num2 += temp;
			cnt[i] -= 2 * temp;
			temp = cnt[i];
			num1 += temp;
