			int ned4 = (n * m - ned2 - 1) / 4;
			num4 -= ned4;
			num2 += max(0, num4) * 2;
			num4 -= max(0, num4);
			num2 -= ned2;
			if(num2  != 0 || num4 != 0 || num1 != 1) flag = false;
		}
		else if(ok1 + ok2 == 1){
			if(n & 1) swap(n, m);
			int ned2 = n / 2;
			int ned4 = (n * m - n) / 4;
			num4 -= ned4;
			num2 += max(0, num4) * 2;
			num4 -= max(0, num4);
			num2 -= ned2;
			if(num2 != 0 || num4 != 0 || num1 != 0) flag = false;
		}
