			if (alpha[(char)i]%4 != 0) {
				pali = false;
			}
		}
	}
	else if (H%2 == 0 || W%2 == 0) {
		int lim;
		if (H%2 == 0) {
			lim = H/2;
		}
		else {
			lim = W/2;
		}
		int noft = 0;
		for (int i = 'a'; pali && i <= 'z'; ++i) {
			if (alpha[(char)i]%2 != 0) {
				pali = false;
			}
