int main(void) {
    int H,W;
    bool ans;
    int one,two,four;
    int tone=0,ttwo=0,tfour=0;
    string s;
    vector<int> ch(26, 0);
    cin >> H >> W;
    for (int i=0; i<H; i++) {
        cin >> s;
        for (int j=0; j<s.size(); j++) ch[(int)(s[j] - 'a')]++;
    }
    if (H % 2 == 0 && W % 2 == 0) {
        one = 0;
        two = 0;
        four = (H * W) / 4;
    } else if (H % 2 != 0 && W % 2 == 0) {
        one = 0;
        two = W / 2;
        four = ((H - 1) * W) / 4;
    } else if (H % 2 == 0 && W % 2 != 0) {
        one = 0;
        two = H / 2;
        four = (H * (W - 1)) / 4;
    } else {
        one = 1;
        two = (H + W - 2) / 2;
        four = ((H-1) * (W-1)) / 4;
    }
    for (int i=0; i<26; i++) {
        tfour += ch[i] / 4;
        ch[i] = ch[i] % 4;
        ttwo += ch[i] / 2;
        ch[i] = ch[i] % 2;
        tone += ch[i];
    }
    if (tfour < four) ans = false;
    else {
        ttwo += (tfour - four) * 2;
        ans = (ttwo == two && tone == one);
    }
    cout << (ans ? "Yes" : "No") << endl;
    return 0;
}

