      if (CNT[i] % 4 == 1) b++;
      else if (CNT[i] % 4 == 2) a++;
      else if (CNT[i] % 4 == 3) { a++; b++; }
    }
    if (b != 1) return false;
    return (2 * a <= H + W - 2);
