bool is_valid(int H, int W, vector<string> &A){
    vector<int> freq(26, 0);
    for (auto row : A){
        for (char a : row) ++freq[a - 'a'];
    }
    vector<int> type(4, 0);
    for (auto f : freq){
        ++type[f % 4];
    }
    int n1 = 0;
    int n2 = 0;
    if ((H & 1) and (W & 1)){
        n1 = 1;
        n2 = (H - 1) / 2 + (W - 1) / 2;
    }else if ((H & 1) and ((W % 2) == 0)){
        n1 = 0;
        n2 = W / 2;
    }else if (((H % 2) == 0) and (W & 1)){
        n1 = 0;
        n2 = H / 2;
    }else{
        n1 = 0;
        n2 = 0;
    }
    if (type[1] + type[3] > n1){
        return false;
    }else{
        n2 -= type[3];
    }
    if (type[2] > n2){
        return false;
    }
    return true;
}


