int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W;
    std::cin >> H >> W;

    vector<int> char_table(26, 0);
    REP(i, H) {
        REP(j, W) {
            char a;
            std::cin >> a;
            char_table[a - 'a']++;
        }
    }

    priority_queue<int> pq;
    REP(i, 26) {
        if(char_table[i] != 0) pq.push(char_table[i]);
    }

    vector<int> pair_table(3, 0);
    vector<vector<bool>> table(H, vector<bool>(W, false));
    REP(i, H) {
        REP(j, W) {
            auto check = [&](const auto& i, const auto& j) -> int {
                             return !table[i][j] ? table[i][j] = true : 0;
                         };
            if(check(i, j)) {
                auto cnt = 1;
                cnt += check(H - i - 1, j);
                cnt += check(i        , W - j - 1);
                cnt += check(H - i - 1, W - j - 1);
                pair_table[log2(cnt)]++;
            }
        }
    }

    auto ans = "Yes";
    while(!pq.empty()) {
        auto top = pq.top();
        pq.pop();

        auto exec = [&](auto num) {
                        auto div = top / num;
                        top  = top % num;
                        top += max(div - pair_table[log2(num)], 0) * num;

                        pair_table[log2(num)] = max(pair_table[log2(num)] - div, 0);
                    };

        auto prev_pair_table = pair_table;
        if(4 <= top) exec(4);
        if(2 <= top) exec(2);
        if(1 <= top) exec(1);
        if(top != 0) pq.push(top);

        if(pair_table == prev_pair_table) {
            ans = "No";
            break;
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

