  cin >> H >> W;

  int p4 = (W / 2) * (H / 2);
  int p2 = (H % 2) * (W / 2) + (W % 2) * (H / 2);
  int p1 = 0;

  if((H % 2) == 1 && (W % 2) == 1){
    p1 = 1;
  }

  char G[100][100];
  int cs[30];
  int cnt = 0;

  REP(i, 0, H){
    REP(j, 0, W){
      cin >> G[i][j];
    }
  }


  while(1){
    int piece = 0;
    char l = '.';
    REP(i, 0, H){
      REP(j, 0, W){
        if(l != G[i][j]){
          l = G[i][j];
          break;
        }
      }
      if(l != '.'){
        break;
      }
    }

    if(l == '.'){
      //all counted
      break;
    }

    REP(i, 0, H){
      REP(j, 0, W){
        if(G[i][j] == l){
          G[i][j] = '.';
          piece++;
        }
      }
    }
    cs[cnt] = piece;

    cnt++;
  }

  REP(i, 0, cnt){
    int tmp = cs[i] / 4;
    p4 -= tmp;
    cs[i] -= 4 * tmp;
  }

  REP(i, 0, cnt){
    int tmp = cs[i] / 2;
    p2 -= tmp;
    cs[i] -= 2 * tmp;
  }

  REP(i, 0, cnt){
    int tmp = cs[i];
    p1 -= cs[i];
    cs[i] -= tmp;
  }

  if(p4 == 0 && p2 == 0 && p1 == 0){
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }

  return 0;
}

