	VI v(26, 0);
	REP(i, h*w) {
		char c;
		cin >> c;
		v[c - 'a']++;
	}
	bool b = true;
	if (h == 1 || w == 1) {
		if ((h + w) % 2) {
			REP(i, 26) {
				if (v[i] % 2)b = false;
			}
		}
		else {
			bool c = true;
			REP(i, 26) {
				if (v[i] % 2) {
					if (c)c = false;
					else b = false;
				}
			}
		}
	}
	else if (h % 2 == 0 && w % 2 == 0) {
		REP(i, 26) {
			if (v[i] % 4)b = false;
		}
	}
	else if (h % 2 == 1 && w % 2 == 0) {
		int d = 0, e = 0;
		REP(i, 26) {
			if (v[i] % 2 == 0) {
				d += v[i] / 4;
				e += v[i] % 4 / 2;
			}
			else b = false;
		}
		if (d - w * (h - 1) / 4 < 0) b = false;
	}
	else if(h % 2 == 1 && w % 2 == 0) {
		int d = 0, e = 0;
		REP(i, 26) {
			if (v[i] % 2 == 0) {
				d += v[i] / 4;
				e += v[i] % 4 / 2;
			}
			else b = false;
		}
		if (d - h * (w - 1) / 4 < 0) b = false;
	}
	else {
