    cin >> H >> W;
    for (int i = 0; i < H; ++i) {
        cin >> s;
        for (int j = 0; j < W; ++j) {
            m[s[j]]++;
            //cout << s[j] << ", " << m[s[j]] << endl;
        }
    }

    int area1, area2, area3;
    area1 = (H / 2) * (W / 2);
    area2 = (H % 2) * (W / 2) + (H / 2) * (W % 2);
    area3 = (H % 2) * (W % 2);

    //cout << "area" << area1 << ", " << area2 << ", " << area3 << endl;
    // area1
    for (auto x: m) {
        //cout << x.first << ", " << x.second << endl;
        int p = x.second / 4;
        int q = x.second % 4;
        m[x.first] = q;
        area1 -= p;
    }
    // area2
    if (area1 < 0) {
        area2 += 2 * area1;
        area1 = 0;
    }
    for (auto x: m) {
        //cout << x.first << ", " << x.second << endl;
        int p = x.second / 2;
        int q = x.second % 2;
        m[x.first] = q;
        area2 -= p;
    }
    // area3
    for (auto x: m) {
        //cout << x.first << ", " << x.second << endl;
        int p = x.second;
        if (p == 1) {
            area3 -= 1;
            break;
        }
    }

    if (area1 == 0 & area2 == 0 & area3 == 0) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
