            mp[a[i][j]]++;
        }
    }

    for(int i=0;i<26;i++){
        if(one==0){
            break;
        }
        if(mp[alphas[i]]%4==1 || mp[alphas[i]]%4==3){
            mp[alphas[i]]--;
            one--;
        }
    }

    for(int i=0;i<26;i++){
        if(two==0){
            break;
        }
        if(mp[alphas[i]]%4==2){
            mp[alphas[i]]-=2;
            two--;
        }
    }

    for(int i=0;i<26;i++){
        if(four==0){
            break;
