map<int, int> n(int h, int w) {
    map<int, int> mp;
    if(h % 2 == 0 && w % 2 == 0) {
        mp[4] = h * w;
    } else if(h % 2 && w % 2) {
        mp[1] = 1;
        mp[2] = h + w - 2;
        mp[4] = h * w - mp[1] - mp[2];
    } else if(h % 2) {
        mp[2] = w;
        mp[4] = w * (h - 1);
    } else {
        mp[2] = h;
        mp[4] = h * (w - 1);
    }
    return mp;
}

