bool ok(const string &s) {
    auto n = s.size();
    auto s1 = s.substr(0, n / 2);
    auto s2 = s.substr(n / 2 + n % 2, n / 2);
    reverse(all(s2));
    return s1 == s2;
}

bool ok(const vector<char> &vec) {
    rep(i, H) {
        string s = "";
        rep(j, W) s += vec[i * W + j];
        if (!ok(s)) return false;
    }
    rep(i, W) {
        string s = "";
        rep(j, H) s += vec[i + j * W];
        if (!ok(s)) return false;
    }

