bool solve() {
  int H, W;
  cin >> H >> W;
  vector<int> cnt(26, 0);
  for (int i = 0; i < H * W; i++) {
    char c;
    cin >> c;
    ++cnt[c - 'a'];
  }
  vector<int> mod(4, 0);
  int odd = 0;
  for (int x : cnt) {
    if (x > 0) {
      int m = x % 4;
      if (m == 1 || m == 3) {
        ++odd;
        if (x - 1 > 0) {
          ++mod[m - 1];
        }
      } else {
        ++mod[m];
      }
    }
  }
  if (odd >= 2) {
    return false;
  }
  int K =
      (H % 2 == 1 ? W : 0) + (W % 2 == 1 ? H : 0) - ((H * W) % 2 == 1 ? 1 : 0);
  K /= 2;
  if (mod[2] > K || (K - mod[2]) % 2 != 0) {
    return false;
  }
  return mod[0] <= (K - mod[2]) / 2;
}

int main() {
  cout << (solve() ? "Yes" : "No") << endl;
  return 0;
}

