int need[10];

void calc(int n, int m) {
	if (n > m) swap(n, m);
	if (n == 0) return;
	if (n == 1) {
		need[2] += m / 2, need[1] += m & 1;
		return;
	}
	need[4] += n / 2;
	if (n & 1) need[2]++;
	need[4] += (m - 2) / 2;
	if (m & 1) need[2]++;
	calc(n - 2, m - 2);
	return;
}

