using namespace std;

int h, w, d;
char cmap[500][500] = { 0 };

bool check_color(int xx, int yy, char ch) {
  for (int x = 0; x < w; ++x) {
    for (int y = 0; y < h; ++y) {
      if (abs(xx - x) + abs(yy - y) == d && cmap[y][x] == ch) {
        return false;
      }
    }
  }
  return true;
}

bool check() {
  char col[] = { 'R','Y','G','B' };
  for (int x = 0; x < w; ++x) {
    for (int y = 0; y < h; ++y) {
      for (int i = 0; i < 4; ++i) {
        if (cmap[y][x] == 0 && check_color(x, y, col[i])) {
          cmap[y][x] = col[i];
          if (check()) {
            return true;
          }
          else {
            cmap[y][x] = 0;
          }
        }
      }
    }
  }
  return true;
}

pair<char,int> find(int ch[256]) {
  for (int i = 0; i < 256; ++i) {
    if (ch[i] != 0) {
      return make_pair(ch[i], i);
    }
  }
  return make_pair(-1, -1);
}

bool is_ok() {
  for (int x = 0; x < w; ++x) {
    for (int y = 0; y < h/2; ++y) {
      if (cmap[x][y] != cmap[x][h - 1 - y]) {
        return false;
      }
    }
  }

  for (int y = 0; y < h; ++y) {

    for (int x = 0; x < w/2; ++x) {
      if (cmap[x][y] != cmap[w-1-x][y]) {
        return false;
      }
    }
  }
  return true;
}

bool check(int ch[256]) {
  for (int x = 0; x < w; ++x) {
    for (int y = 0; y < h; ++y) {
      if (cmap[y][x] == 0) {
        for (int i = 0; i < 256; ++i) {
          if (ch[i] != 0) {
            cmap[y][x] = ch[i];
            --ch[i];
            if (check(ch)) {
              return true;
            }
            ++ch[i];
          }
        }
      }
    }
  }
  return is_ok();
}

int main(){
  cin >> h >> w;
  int ch[256] = { 0 };
  for (int i = 0; i < h; ++i) {
    string s;
    cin >> s;
    for (int j = 0; j < w; ++j) {
      ch[s[j]]++;
    }
  }
  int k = 0, g = 0;
  int max_ch = 0;
  for (int i = 0; i < 256; ++i) {
    if (ch[i] != 0) {
      if (ch[i] % 2 == 0) {
        g++;
      }
      else {
        ++k;
      }
      max_ch = max(max_ch, ch[i]);
    }
  }
  if (h == 2 && w == 2 && g != 0) {
    cout << "No" << endl;
  }
  else if (k <= 1 && max_ch <= min(h, w) * 2) {
    cout << "Yes" << endl;
  }
  else {
    if (check(ch)) {
      cout << "Yes" << endl;
    }
    else {
      cout << "No" << endl;
    }
  }
  return 0;
}

