using namespace std;
int cnt[30],s[10000];
int n,m,tot,waste;
bool dfs(int k,int now)
{
	if(!k) return 1;
	if(waste) return 0;
	for(int i=now;i<=26;i++)
	  if(cnt[i]>=s[k])
	  {
		cnt[i]-=s[k];
		if(cnt[i]<s[1]) waste+=cnt[i];
		if((cnt[i]==cnt[i-1]&&dfs(k-1,i))||(cnt[i]!=cnt[i-1]&&dfs(k-1,1)))
		{
			if(cnt[i]<s[1]) waste-=cnt[i];
			cnt[i]+=s[k];return 1;
		}
		if(cnt[i]<s[1]) waste-=cnt[i];
		cnt[i]+=s[k];
	  }
	return 0;
}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
	  for(int j=1;j<=m;j++)
	  {
	  	char c=getchar();
	  	while(c<'a'||c>'z') c=getchar();
	  	cnt[c-'a'+1]++;
	  }
	for(int i=1;i<=n>>1;i++)
	  for(int j=1;j<=m>>1;j++)
	    s[++tot]=4;
	if(n&1) for(int i=1;i<=m>>1;i++)
	  s[++tot]=2;
	if(m&1) for(int i=1;i<=n>>1;i++)
	  s[++tot]=2;
	if(n&1&&m&1) s[++tot]=1;
	sort(cnt+1,cnt+27);
	sort(s+1,s+tot+1);
	if(dfs(tot,1)) puts("Yes");
	else puts("No");
	return 0;
}

