int n,m;
int cnt[30];
void work(){
	memset(cnt,0,sizeof(cnt));
	scanf("%d%d",&n,&m);
  int N=n*m;
  char ch;
  for(int i=1;i<=N;++i){
    while(ch=getchar(),ch>'z'||ch<'a');
    cnt[ch-'a']++;
  }
  if(n%2==0&&m%2==0){
    bool flag=true;
    for(int i=0;i<26;++i)if(cnt[i]%4!=0)flag=false;
    printf("%s\n",flag?"Yes":"No");
  }else if(n%2==0||m%2==0){
    if(m%2==0)swap(n,m);
    //n even m odd
    //    4*((m-1)*n/4),2*(n/2)
    bool flag=true;
    for(int i=0;i<26;++i){
      if(cnt[i]&1)flag=false;
    }
    //    2*((m-1)*n/4),1*(n/2)
    for(int i=0;i<26;++i)cnt[i]/=2;
    int cnt2=0,cnt1=0;
    for(int i=0;i<26;++i)cnt2+=cnt[i]/2,cnt1+=cnt[i]&1;
    if(cnt1>n/2/*||(cnt1&1)!=((n/2)&1)*/)flag=false;
    printf("%s\n",flag?"Yes":"No");
  }else{
    //n odd m odd
    // 4*[(n-1)*(m-1)/4] 2*[(n-1)/2 +(m-1)/2] 1*1
    int cnt1=0;
    for(int i=0;i<26;++i){
      if(cnt[i]&1)cnt1++;
    }
    bool flag=true;
    if(cnt1!=1){
      flag=false;
    }else{
      for(int i=0;i<26;++i){
				cnt[i]/=2;
      }//2*[(n-1)*(m-1)/4] 1*[(n-1)/2 +(m-1)/2]
      cnt1=0;
      for(int i=0;i<26;++i){
				if(cnt[i]&1)cnt1++;
      }
      if(cnt1>(n-1)/2+(m-1)/2||((cnt1&1)!=(((n-1)/2 +(m-1)/2)&1)))flag=false;
    }
    printf("%s\n",flag?"Yes":"No");
  }
}
int main(){
	int T=1;
	while(T--){
  	work();
	}
  return 0;
}

