    if(odd_count > 0 || two_mod_count > W / 2){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  } else {
    if(odd_count > 1 || two_mod_count > W / 2 + H / 2){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  }

  return 0;
}

