	for (int i = 0;i < H;i ++) {
		cin >> s;
		W = s.length();
		for (int j = 0;j < W;j ++) {
			alpha[s[j] - 'a'] ++;
		}
	}
	int four, two = 0, one = 0;
	if (H % 2 == 1) {
		two += W / 2;
	}
	if (W % 2 == 1) {
		two += H / 2;
		if ((H + W) % 2 == 0) {
			one ++;
		}
	}
	four = (H * W - two * 2 - one) / 4;
	for (int i = 0;i < ALPHABET;i ++) {
		if (alpha[i] == 0) continue;
		four -= alpha[i] / 4;
		if (alpha[i] % 4 == 0);
		else if (alpha[i] % 2 == 0)	two --;
		else {
			if (alpha[i] % 4 == 3) two --;
			one --;
		};
		if (four < 0) two -= 2;
		if (two < 0 || one < 0) {
			cout << "No";
			return 0;
		}
	}
	cout << "Yes";
