int n,m,cnt[30],cc[10010];
int id[110][110],tot;
char s[110];
bool ans;
int main() {
	scanf("%d %d",&n,&m);
	for (int i=1;i<=n;i++) {
		scanf("%s",s);
		for (int j=1;j<=m;j++)
			cnt[s[j-1]-'a'+1]++;
	}
	ans=1;
	if (n==1||m==1) {
		int c=0;
		for (int i=1;i<=26;i++) {
			if (cnt[i]>2) {
				ans=0; break;
			}
			if (cnt[i]==1)
				c++;
		}
		if (c>1)
			ans=0;
	}
	else {
		for (int i=1;i<=n;i++)
			for (int j=1;j<=m;j++) {
				if (id[i][j]>0) continue;
				tot++;
				id[i][j]=id[i][m-j+1]
				=id[n-i+1][j]=id[n-i+1][m-j+1]=tot;
			}
		for (int i=1;i<=n;i++)
			for (int j=1;j<=m;j++)
				cc[id[i][j]]++;
		int c=0,d=0,e=0;
		for (int i=1;i<=tot;i++) {
			if (cc[i]==1)
				d++;
			else if (cc[i]==2)
				c++;
			else e++;
		}
		for (int i=1;i<=26;i++) {
			if (e-cnt[i]/4<0) {
				cnt[i]-=e*4;
				e=0;
				continue;
			}
			e-=cnt[i]/4;
			cnt[i]%=4;
		}
		if (e>0) ans=0;
		for (int i=1;i<=26;i++) {
			if (cnt[i]==4)
				c-=2;
			if (cnt[i]==3)
				c--,d--;
			if (cnt[i]==2)
				c--;
			if (cnt[i]==1)
				d--;
		}
		if (c!=0||d!=0) ans=0;
	}
	if (ans)
		printf("Yes\n");
	else printf("No\n");
	return 0;
}

