bool solve(ll g1,ll g2, ll g4, map<char,ll>& mp) {
  for(auto p:mp) {
    if(g1==0) break;
    if(p.second%2==1) {mp[p.first]-=1;g1--;}
  }
  for(auto p:mp) {
    if(g2==0) break;
    if(p.second%4==2) {mp[p.first]-=2;g2--;} 
  }
  for(auto p:mp) {
    if(g4==0) break;
    if(p.second>0&&p.second%4==0) {mp[p.first]-=4;g4--;} 
  }
  bool isok=true;
  for(auto p:mp) if(p.second!=0) isok=false;
  return isok;
}

