  rep (i, h) rep (j, w) {
    char c;
    cin >> c;
    a[c-'a']++;
  }

  int oddCnt = 0;
  int oddChar = -1;
  rep (i, 26) {
    if (a[i] % 2) {
      oddCnt++;
      oddChar = i;
    }
  }

  if ((h%2) && (w%2)) {
    if (oddCnt != 1) {
      cout << "No" << endl;
      return 0;
    }
  } else {
    if (oddCnt != 0) {
      cout << "No" << endl;
      return 0;
    }
  }

  if ((h%2) && (w%2)) { // 中央ががあるパターンは、奇数個のものを真ん中に入れる
    result[h/2][w/2] = oddChar;
    a[oddChar]--;
  }

  priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> man; // (num , char)
  rep (i, 26) { // 新しいデータ構造に乗り換え
    if (a[i] > 0) {
      man.push(make_pair(a[i], i));
    }
  }

  while (!man.empty()) {
    int num = man.top().first;
    int chara= man.top().second;
    if (num > 0) {
      bool isIn = false;
      rep (j, h) rep (k, w) {
        if (result[j][k] != -1) continue;
        set<pair<int, int>> zahyo;
        zahyo.insert(make_pair(j, k));
        zahyo.insert(make_pair(abs(j-(h-1)), k));
        zahyo.insert(make_pair(j, abs(k-(w-1))));
        zahyo.insert(make_pair(abs(j-(h-1)), abs(k-(w-1))));
        if (num >= zahyo.size()) {
          isIn = true;
          for (auto tmp : zahyo) {
            result[tmp.first][tmp.second] = chara;
          }

          //          rep (i, h) {
          //            rep (j, w) { 
          //              cout << result[i][j] << " ";
          //            }
          //            cout << endl;
          //          }
          //          cout << endl;

          man.pop();
          num -= zahyo.size();
        }
      }
      man.push(make_pair(num, chara));
      if (!isIn) {
        // rep (i, h) {
        //   rep (j, w) { 
        //     cout << result[i][j] << " ";
        //   }
        //   cout << endl;
        // }
        cout << "No" << endl;
        return 0;
      }
    } else {
      man.pop();
    }
  }
  cout << "Yes" << endl;
}

