		int sum1 = ( ( n & 1 ) & ( m & 1 ) ) ;
		int sum2 = ( m * ( n & 1 ) ) + ( n * ( m & 1 ) ) - ( sum1 << 1 ) ;
		scanf ( "%d%d", & n, & m ) ;
		for ( int i = 0 ; i < 26 ; ++ i )	cnt [i] = 0 ;
		for ( int i = 1 ; i <= n ; ++ i )
