				int c ;
				while ( ! isalpha ( c = getchar ( ) ) ) ;
				++ cnt [c - 'a'] ;
			}
		bool ans ( 1 ) ;
		for ( int i = 0 ; i < 26 ; ++ i )  {
			if ( cnt [i] & 1 )  -- sum1 ;
