	}
	for (auto &kvp : ch2NumMap)
	{
		if (fourPairNum == 0) break;
		if (kvp.second % 4 == 2)
		{
			--fourPairNum;
			kvp.second -= 4;
		}
	}
	if (fourPairNum > 0)
	{
		isYes = false;
	}
	for (auto &kvp : ch2NumMap)
	{
		if (twoPairNum == 0) break;
		if (kvp.second % 4 == 0)
