bool solve() {
	cnts.clear();
	REP(i, R) {
		for (char c : G[i]) {
			cnts[c]++;
		}
	}

	map<int, int> need;


	REP(len, R/2+1) {
		int top = len, bot = R-1-len;

		if (top == bot) {
			REP(clen, C/2+1) {
				int l = clen, r = C-1-clen;
				if (l == r) {
					need[1]++;
				} else if (l < r) {
					need[2]++;
				}
			}
		} else if (top < bot) {
			REP(clen, C/2+1) {
				int l = clen, r = C-1-clen;
				if (l == r) {
					need[2]++;
				} else if (l < r) {
					need[4]++;
				}
			}
		}

	}

	V<int> vals = {4, 2, 1};
	for (int v : vals) if (need[v]) {
		while (need[v]) {
			bool fnd = 0;
			for (auto &kv : cnts) if (kv.second >= v) {
				kv.second -= v;
				--need[v];
				fnd = 1;
				break;
			}
			if (!fnd) {
				return 0;
			}
		}
	}
	return 1;
}

