const int SIGMA = 26;
const int MAXN = 100;

int seen[SIGMA];
char s[1 + MAXN];

bool Get(int x, int y) {
    int letter = 0;
    for (int i = 1; i <= y; i++) {
        while (letter < SIGMA && seen[letter] < x)
            letter++;
        if (letter == SIGMA)
            return false;
        seen[letter] -= x;
    }
    return true;
}

bool Check(int n, int m) {
    int l1 = 1, l2 = n, one = 0, two = 0, four = 0;
    while (l1 <= l2) {
        int c1 = 1, c2 = m;
        while (c1 <= c2) {
            if (c1 == c2 && l1 == l2)
                one++;
            else
                if (c1 != c2 && l1 != l2)
                    four++;
                else
                    two++;
            c1++;
            c2--;
        }
        l1++;
        l2--;
    }
    if (!Get(4, four) || !Get(2, two) || !Get(1, one))
        return false;
    return true;
}

