using namespace std;
using ll = long long;
using vi = vector<int>;

#define all(a) (a).begin(),(a).end()
#define loop(i,a,b) for(int i=(a);i<(b);++i)
#define rep(i,n) for(int i=0;i<(n);++i)
#define iter(it,v) for(auto it=v.begin();it!=v.end();++it)
#define in(v) cin>>v;
#define out(v) cout<<v<<"\n"

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int H, W; in(H); in(W);

  map<char, int> m;
  rep(i, H) rep(j, W) {
    char a;
    in(a);
    ++m[a];
  }
  int board[H][W];
  rep(i, (H+1)/2) {
    board[i][0] = board[i][W-1] = i*W;
    board[H-1-i][0] = board[H-1-i][W-1] = i*W;
    loop(j, 1, (W+1)/2) {
      board[i][j] = board[i][W-1-j] = board[i][j-1] + 1;
      board[H-1-i][j] = board[H-1-i][W-1-j] = board[i][j-1] + 1;
    }
  }
  map<int, int> m2;
  rep(i, H) rep(j, W) {
    ++m2[board[i][j]];
  }
  priority_queue<int> q, q2;
  iter(it, m) {
    q.push(it->second);
  }
  iter(it, m2) {
    q2.push(it->second);
  }
  while (!q2.empty()) {
    int p2 = q2.top(); q2.pop();
    int p = q.top(); q.pop();
    if (p2 > p) {
      out("No");
      return 0;
    }
    q.push(p - p2);
  }
  out("Yes");

  return 0;
}

