        string s;
        cin >> s;
        for (int j = 0; j < w; ++j) {
            v[s[j]]++;
        }
    }
    if(w % 2) swap(h, w);
    using PQ = priority_queue<int>;
    PQ q;
    vector<int> v2;
    for (auto &&i : v) {
        if(i.second) q.emplace(i.second);
    }
    v2.reserve((h / 2) * (w / 2));
    for (int i = 0; i < (h/2)*(w/2); ++i) {
        v2.emplace_back(4);
    }
    for (int i = 0; i < (h%2) * (w/2) +  (w%2) * (h/2); ++i) {
        v2.emplace_back(2);
    }
    if((h%2)*(w%2)) v2.emplace_back(1);
    for (int i = 0; i < v2.size(); ++i) {
        int x = q.top(); q.pop();
        if(x < v2[i]){
            cout << "No\n";
            return 0;
        }else {
            x -= v2[i];
            q.emplace(x);
        }
    }
