const ll half_inf = ll(1e5);
const ll ll_inf = ll(1e9) * ll(1e9);

const int limit = 100;
int h, w;
char a[limit][limit];
unordered_map<int, int> mp, mp_mod;

void solve() {
    if (mp_mod[3] > 1) {
        cout << "No" << endl;
        return;
    } else if (mp_mod[3] == 1) {
        mp_mod[1]++, mp_mod[2]++, mp_mod[3]--;
    }
    if (h % 2 == 1 && w % 2 == 1) {
        if (mp_mod[1] == 1) {
            if (mp_mod[2] * 2 <= h - 1 + w - 1 && (h - 1 + w - 1 - mp_mod[2] * 2) % 4 == 0) {
                cout << "Yes" << endl;
                return;
            }
        }
    } else if (h % 2 == 0) {
        if (mp_mod[1] == 0) {
            if (mp_mod[2] * 2 <= h && (h - mp_mod[2] * 2) % 4 == 0) {
                cout << "Yes" << endl;
                return;
            }
        }
    } else if (w % 2 == 0) {
        if (mp_mod[1] == 0) {
            if (mp_mod[2] * 2 <= w && (w - mp_mod[2] * 2) % 4 == 0) {
                cout << "Yes" << endl;
                return;
            }
        }
    } else {
        if (mp_mod[1] == 0 && mp_mod[2] == 0) {
            cout << "Yes" << endl;
            return;
        }
    }
    cout << "No" << endl;
}

