		return 0;
	}
	cnt.assign(A, 0);
	forn(i, n) {
		static char buf[1000];
		scanf("%s\n", buf);
		forn(j, m) {
			++cnt[buf[j] - 'a'];
		}
	}
	return 1;
}

bool solve2(vi cnt, int times2) {
	forn(c, A) {
		if  (cnt[c] % 2 != 0) {
			return 0;
		}
	}

	forn(c, A) {
		if  (cnt[c] % 4 != 0) {
			assert(cnt[c] % 4 == 2);
			cnt[c] -= 2;
			--times2;
		}
	}

	if (times2 < 0) {
		return 0;
	}

	if  (times2 % 2 == 0) {
		return 1;
	}
	return 0;
}

bool solve(vi cnt) {
	if  (n % 2 == 0 && m % 2 == 0) {
		forn(c, A) {
			if  (cnt[c] % 4 != 0) {
				return 0;
			}
		}
		return 1;
	}

	if  (m % 2 == 0) {
		swap(n, m);
	}

	if  (n % 2 == 0) {
		forn(c, A) {
			if  (cnt[c] % 2 != 0) {
				return 0;
			}
		}

		forn(c, A) {
			cnt[c] /= 2;
		}

		int times = n / 2;
		int odd = 0;
		forn(c, A) {
			if  (cnt[c] & 1) {
				++odd;
			}
		}

		if (odd > times) {
			return 0;
		}

		times -= odd;

		if  (times & 1) {
			return 0;
		}
		return 1;
	}

	assert(n % 2 == 1 && m % 2 == 1);

	forn(c, A) {
		if  (!cnt[c]) {
			continue;
		}
		--cnt[c];
		if  (solve2(cnt, m / 2 + n / 2)) {
			return 1;
		}
		++cnt[c];
	}

	return 0;
}

bool solve() {
	return solve(cnt);
}

