typedef vector<vcc> vvcc;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll h, w;
        in >> h >> w;
        vvcc a(h, vcc(w));
        ll alpha[26] = {};
        rep(i, h) {
            rep(j, w) {
                in >> a[i][j];
                alpha[a[i][j] - 'a']++;
            }
        }
        ll sum = h * w;
        sort(alpha, alpha + 26);
        for (int i = 25; i >= 0 && alpha[i]; --i) {
            for (int _ = 0; _ < 10000; _++) {
                if (sum >= 4 && alpha[i] >= 4) {
                    alpha[i] -= 4;
                    sum -= 4;
                }
                else if (!(h == 2 && w == 2) && sum >= 2 && alpha[i] >= 2) {
                    alpha[i] -= 2;
                    sum -= 2;
                }
                else if (sum == 1 && alpha[i] == 1) {
                    sum -= 1;
                    alpha[i] -= 1;
                }
            }
        }
        out << (sum == 0 ? "Yes" : "No") << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
