int alpha[26]={};

bool solve(){
    int H,W;
    cin>>H>>W;
    vector<string> a(H);
    rep(y,H) cin>>a[y];
    rep(y,H)rep(x,W) {
        alpha[a[y][x]-'a']++;
    }

    int minus4=1,minus2=0;

    if(H%2==0){
        minus4 *= H/2;
        if(W%2==1) minus2 += H/2;
    }else{
        minus4 *= (H-1)/2;
        if(W%2==1) minus2 += (H-1)/2;
    }

    if(W%2==0){
        minus4 *= W/2;
        if(H%2==1) minus2 += W/2;
    }else{
        minus4 *= (W-1)/2;
        if(H%2==1) minus2 += (W-1)/2;
    }

    int set4=0,set2=0;
    rep(c,26){
        set4 += alpha[c]/4;
        set2 += (alpha[c]%4)>=2;
    }

    set4-=minus4;
    if(set4<0)return false;
    set2 += set4*2;
    set2 -= minus2;
    return set2>=0;
}

int main(void){
    cout<<(solve() ? "Yes" : "No")<<endl;
    return 0;
}

