#include<bits/stdc++.h>
using namespace std;
int H,W;
int No() { return puts("No") * 0;}
string paindram(vector<char>even, vector<char>odd){
    string res(W,'x');
    assert(W % 2 == odd.size());
    if(W % 2 == 1){
        res[W / 2] = odd.front();
    }
    for(int i = 0; i < even.size(); ++i)
        res[i] = res[W - 1 - i] = even[i];
    return res;
}
int main(){
    cin >> H >> W;
    vector<string>g(H);
    vector<string>ans(H,string(W,'z'));
    for(auto& s : g) cin >> s;
    vector<vector<char>>even(H);
    vector<vector<char>> odd(H);
    int idx  = 0;
    for(auto s : g){
        map<char,int>cnt;
        for(auto c :s) cnt[c] += 1;
        for(auto [c,num] : cnt){
            if(num % 2){
                odd[idx].push_back(c);
            }else{
                num /= 2;
                while(num > 0){
                    even[idx].push_back(c);
                    num /= 2;
                }
            }
        }
        if(W % 2 == 0){
            if(odd[idx].size() >= 1)
                return No();
        } else {
            if(odd[idx].size() != 1)
                return No();
        }
        ++idx;
    }
    //we can construct paindram sentence,
    int remu = 0;
    vector<bool>used(H,false);
    for(int i = 0; i < even.size(); ++i){
        if(used[i]) continue;
        for(int j = 0; j < even.size(); ++j){
            if(i == j or used[j])continue;
            if(even[i] == even[j] && odd[i] == odd[j]){
                used[i] = used[j] = true;
                ans[remu] = paindram(even[i],odd[j]);
                ans[H - remu - 1] = paindram(even[i],odd[i]);
                remu++;
                break;
            }
        }
    }
    int unused = count_if(used.begin(), used.end(),[](bool e){
        return !e;
    });
    if(H % 2 == 0 && unused > 0) return No();
    if(H % 2 == 1 && unused != 1) return No();
    if(H % 2 == 1){
        auto itr = find(used.begin(), used.end(),false);
        int id = distance(used.begin(),itr);
        ans[H / 2] = paindram(even[id],odd[id]);
    }
    cout << "Yes" << endl;
}

