using namespace std;

bool solve() {
	int h, w; cin >> h >> w;
	int cnt[26] = {};
	for(int i = 0; i < h; ++i) {
		for(int i = 0; i < w; ++i) {
			char c; cin >> c;
			cnt[c - 'a']++;
		}
	}
	int g1 = 0, g2 = 0, g4 = 0;
	if(h % 2 == 1 and w % 2 == 1) g1 = 1;
	if(h % 2 == 1) {
		g2 += w / 2;
	}
	if(w % 2 == 1) {
		g2 += h / 2;
	}
	g4 = (h / 2) * (w / 2);
	for(int i = 0; i < 26; ++i) {
		if(cnt[i] % 2 == 1) {
			if(g1 == 0) {
				return false;
			}
			cnt[i]--;
			g1--;
		}
	}
	if(g1 != 0) {
		return false;
	}
	for(int i = 0; i < 26; ++i) {
		if(cnt[i] % 4 == 2) {
			if(g2 == 0) {
				return false;
			}
			cnt[i] -= 2;
			g2--;
		}
	}
	for(int i = 0; i < 26; ++i) {
		if(cnt[i] > 0) {
			if(g2 == 0) {
				return false;
			}
			while(g2 > 0 and cnt[i] > 0) {
				cnt[i] -= 2;
				g2--;
			}
		}
	}
	if(g2 != 0) {
		return false;
	}
	for(int i = 0; i < 26; ++i) {
		if(cnt[i] > 0 and cnt[i] % 4 == 0) {
			if(g4 == 0) {
				return false;
			}
			g4 -= cnt[i] / 4;
			cnt[i] %= 4;
		}
	}
	if(g4 != 0) {
		return false;
	}
	for(int i = 0; i < 26; ++i) {
		if(cnt[i] > 0) {
			return false;
		}
	}
	return true;
}

int main() {
	cout << (solve() ? "Yes" : "No") << endl;
	return 0;
}

