const int N = 100;

int n, m, par[N * N], sz[N * N], cnt[26], need[5];

int find(int u)
{
    if (par[u] != u) {
        par[u] = find(par[u]);
    }
    return par[u];
}

void merge(int a, int b)
{
    a = find(a);
    b = find(b);
    if (a != b) {
        sz[a] += sz[b];
        par[b] = a;
    }
}

int get_id(int a, int b)
{
    return a * m + b;
}

int main()
{
#ifdef LOCAL_JUDGE
    freopen("C.in", "r", stdin);
#endif
    while (scanf("%d%d", &n, &m) == 2) {
        for (int i = 0; i < n * m; ++ i) {
            par[i] = i, sz[i] = 1;
        }
        for (int i = 0; i < n; ++ i) {
            for (int j = 0; j < m; ++ j) {
                merge(get_id(i, j), get_id(i, m - 1 - j));
                merge(get_id(i, j), get_id(n - 1 - i, j));
            }
        }
        memset(need, 0, sizeof(need));
        for (int i = 0; i < n * m; ++ i) {
            if (par[i] == i) {
                need[sz[i]] ++;
            }
        }
        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i < n; ++ i) {
            static char buf[N + 1];
            scanf("%s", buf);
            for (int j = 0; j < m; ++ j) {
                cnt[buf[j] - 'a'] ++;
            }
        }
        bool ok = true;
        for (int s = 4; s >= 1 && ok; -- s) {
            int left = need[s];
            for (int i = 0; i < 26; ++ i) {
                while (left && cnt[i] >= s) {
                    left --;
                    cnt[i] -= s;
                }
            }
            ok &= left == 0;
        }
        puts(ok ? "Yes" : "No");
    }
}

