        cnt[c - 'a']++;
    }

    VI vals(5, 0);

    for (int i = 0; i <= h - 1 - i; i++) {
        for (int j = 0; j <= w - 1 - j; j++) {
            set <pii> fields;

            FOR(x,0,1) FOR(y,0,1) {
                int pi = (x ? i : h - 1 - i);
                int pj = (y ? j : w - 1 - j);

                fields.insert({pi, pj});
            }

            int s = fields.size();
            vals[s]++;
        }
    }

    FOR(i,0,ALPH-1) if (cnt[i] % 2) {
        if (!vals[1]) answerNo();

        cnt[i]--;
        vals[1]--;
    }

    if (vals[1]) answerNo();

    FOR(i,0,ALPH-1) cnt[i] /= 2;

    FOR(i,0,ALPH-1) if (cnt[i] % 2) {
        if (!vals[2]) answerNo();

        cnt[i]--;
        vals[2]--;
