	if (H % 2 && W % 2) {
		g1 = 1;
		g2 = H / 2 + W / 2;
	}
	else if (H % 2) {
		g2 = W / 2;
	}
	else if (W % 2) {
		g2 = H / 2;
	}

	std::vector<int> ch(26, 0);
	for (int h = 0; h < H; h++) {
