			ch[i]--;
			g1--;
		}
	}

	for (int i = 0; i < 26; i++) {
		surp = ch[i] % 4;
		if (surp == 2 && g2) {
			ch[i] -= 2;
			g2--;
		}
	}

	if (g2 / 2) {
		g4 += g2 / 2;
		g2 -= (g2 / 2) * 2;
	}
	for (int i = 0; i < 26; i++) {
		surp = ch[i] % 4;
		if (!surp && ch[i] && g4) {
			g4 -= ch[i] / 4;
			ch[i] = 0;
		}
	}
	if (g1 || g2 || g4) {
		printf("No\n");
		return;
	}
	for (int i = 0; i < 26; i++) {
		if (ch[i]) {
			printf("No\n");
			return;
		}
	}
	printf("Yes\n");
}

