    int alpha[26]={};
    rep(y,H)rep(x,W) {
        alpha[a[y][x]-'a']++;
    }

    assert(W!=1);
    int odd=0;
    rep(c,26){
        odd += alpha[c]%2;
    }
    if(odd>1 || (odd>0 && (H*W)%2==0)) return false;

    int minus4 = (H/2)*(W/2);
