  if (mod[1] + mod[3] >= 2) {
    cout << "No" << endl;
    return 0;
  }
  if (mod[3] > 0) {
    ++mod[2];
  }
  int K =
      (H % 2 == 1 ? W : 0) + (W % 2 == 1 ? H : 0) - ((H * W) % 2 == 1 ? 1 : 0);
  K /= 2;
  bool res = mod[2] <= K && (K - mod[2]) % 2 == 0;
  cout << (res ? "Yes" : "No") << endl;
  return 0;
}

