#include "bits/stdc++.h"
using namespace std;

int n, m;

map<char, int> M;

bool solve() {
    int odd = 0;
    char letter = ' ';

    for(auto i: M)
	if(i.second % 2) {
	    ++odd;
	    letter = i.first;
	}

    if(odd > 1)
	return false;

    if((m % 2) && (n % 2)) {
	if(!odd)
	    return false;

	int mod = 0;

	for(auto i: M)
	    if(i.second % 4 != 0)
		++mod;

	if((n / 2) + (m / 2) > mod)
	    return false;

	return true;
    }

    if(odd)
	return false;

    if(!(m % 2) && !(n % 2)) {
	for(auto i: M)
	    if(i.second % 4)
		return false;

	return true;
    }

    int mod = 0;

    for(auto i: M)
	if(i.second % 4 != 0)
	    ++mod;

    if(n % 2) {
	if(mod > m / 2)
	    return false;
    }

    if(m % 2) {
	if(mod > n / 2)
	    return false;
    }

    return true;
}

int main() {
    cin >> n >> m;

    for(int i = 1; i <= n; ++i) 
	for(int j = 1; j <= m; ++j) {
	    char c;

	    cin >> c;
	    ++M[c];
	}

    if(solve())
	printf("Yes\n");
    else
	printf("No\n");

    return 0;
}

