bool check(vector<string> A){
  int h = A.size();
  int w = A[0].size();

  auto getString=[&](int i){
    string res;
    for(int j=0;j<h;j++) res += A[j][i];
    return res;
  };
  map<string,int> cnt;
  for(int i=0;i<w;i++) cnt[getString(i)]++;
  int ng = 0;
  for(auto p:cnt){
    string s = p.first;
    int c = p.second;
    if(c%2 == 0) continue;
    ng++;
  }
  if(w%2 == 0 && ng > 0) return 0;
  if(w%2 == 1 && ng > 1) return 0;
  return 1;
}

vector<string> rot90(const vector<string> &v){
  int h = v.size(), w = v[0].size();
  vector<string> res(w,string(h,'.'));
  for(int i=0;i<h;i++) for(int j=0;j<w;j++) res[j][h-i-1] = v[i][j];
  return res;
}

