char search(int cnt, int div) {
	if (div == 0)
		return '#';
	char choice = '#';
	for (const auto &kv : cnts) {
		if (kv.second >= cnt && kv.second % div == 0) {
			choice = kv.first;
			break;
		}
	}
	if (choice == '#')
		return search(cnt, div/2);
	return choice;
}

bool solve() {
	cnts.clear();
	REP(i, R) {
		for (char c : G[i]) {
			cnts[c]++;
		}
	}

	V<string> ans(R, string(C, '#'));


