					char choice = search(1, 1);
					if (choice == '#') {
						// cout << "No" << endl;
						return 0;
					}
					cnts[choice] -= 1;
					ans[top][l] = ans[top][r] = ans[bot][l] = ans[bot][r] = choice;
				} else if (l < r) {
