V<string> ans;
V<string> aa;
bool found;

bool isgood() {
	REP(i, R) {
		string rev = ans[i];
		reverse(begin(rev), end(rev));
		if (rev != ans[i])
			return 0;
	}
	REP(i, C) {
		string s;
		REP(j, R) {
			s.push_back(ans[j][i]);
		}
		string rev = s;
		reverse(begin(rev), end(rev));
		if (rev != s)
			return 0;
	}
	return 1;
}
void fill(int r, int c) {
	if (r == R) {
		// for (auto s : ans) {
		// 	cout << s << endl;
		// }
		// cout << endl;
		if (isgood()) {
			aa = ans;
			found = 1;
		}
		return;
	}
	if (c == C) {
		fill(r+1, 0);
		return;
	}
	REP(ci, 26) if (cnts[ci+'a']) {
		cnts[ci+'a']--;
		ans[r][c] = ci+'a';
		fill(r, c+1);
		ans[r][c] = '#';
		cnts[ci+'a']++;
	}
}


bool brute() {
	cnts.clear();
	REP(i, R) {
		for (char c : G[i]) {
			cnts[c]++;
		}
	}

	ans = V<string>(R, string(C, '#'));
	found = 0;
	fill(0, 0);
	return found;
}


