  cin >> H >> W;
  for(int i = 0; i < H; i++){
    cin >> grid[i];
  }

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      if(char_counts.find(grid[i][j]) == char_counts.end()){
        char_counts[grid[i][j]] = 1;
      } else {
        char_counts[grid[i][j]] ++;
      }
    }
  }

  int odd_count = 0;
  int two_mod_count = 0;
  for(auto it = char_counts.begin(); it != char_counts.end(); it++){
    char_counts[it->first] %= 4;
    if(char_counts[it->first] % 2 != 0){
      odd_count ++;
    }
    if(char_counts[it->first] == 2 || char_counts[it->first] == 3){
      two_mod_count ++;
    }
  }

  if(H % 2 == 0 && W % 2 == 0){
    if(odd_count > 0 || two_mod_count > 0){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  } else if(H % 2 == 1 && W % 2 == 0){
    if(odd_count > 0 || two_mod_count > W / 2){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  } else if(H % 2 == 0 && W % 2 == 1) {
    if(odd_count > 0 || two_mod_count > H / 2){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  } else {
    if(odd_count != 1 || two_mod_count > W / 2 + H / 2){
      cout << "No" << endl;
    } else {
      cout << "Yes" << endl;
    }
  }

  return 0;
}

