template<typename T>
bool is_structurable_even(const T& counter)
{
	bool more_4 = false;
	for(auto p : counter)
	{
		auto n = p.second;
		if(n % 2 != 0)
		{
			return false;
		}
		if(n >= 4)
		{
			more_4 = true;
		}
	}
	return more_4;
}
template<typename T>
bool is_structurable_odd(const T& counter)
{
	bool found_odd = false;
	for(auto p : counter)
	{
		auto n = p.second;
		if(n % 2 != 0)
		{
			if(found_odd) return false;
			found_odd = true;
		}
	}
	return found_odd;
}
int main()
{
	std::map<char,int> counter;
	int h,w;
	std::cin >> h >> w;
	for(int i=0;i<h;i++)
	{
		std::string s;
		std::cin >> s;
		for(auto c : s)
		{
			counter[c]++;
		}
	}
	bool result;
	if(h%2!=0&&w%2!=0)
	{
		result = is_structurable_odd(counter);
	}
	else
	{
		result = is_structurable_even(counter);
	}
	std::cout << (result?"Yes":"No") << std::endl;
}

