    for (int i = 0; i < 26; i++) {
        count[i] = 0;
    }
    int h, w;
    cin >> h >> w;
    string a[h];
    for (int i = 0; i < h; i++) {
        cin >> a[i];
    }

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            count[a[i][j] - 'a']++;
        }
    }

    sort(count, count + 26);

    vector<int> res;
    int hsho = h / 2;
    int hamari = h % 2;
    int wsho = w / 2;
    int wamari = w % 2;
    for (int i = 0; i < hsho * wsho; i++) {
        res.push_back(4);
    }
    for (int i = 0; i < hamari * wsho + hsho * wamari; i++) {
        res.push_back(2);
    }
    for (int i = 0; i < hamari * wamari; i++) {
        res.push_back(1);
    }

    int p = 0;
    while (p < res.size()) {
        sort(count, count + 26);
        for (int i = 25; i >= 0; i--) {
//            cout << "p = " << p << endl;
            if (p == res.size()) break;
            if (count[i] == 0) break;
            if (count[i] >= res[p]) {
                count[i] -= res[p];
//                cout << "count: " << count[i] << endl;
                p++;
            } else {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    for (int i = 0; i < 26; i++) {
        if (count[i] > 0) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
    return 0;
}

