    }

    int four(0), two(0), odd(0);

    for (char c = 'a'; c <= 'z'; ++c) {
        if (mp[c] == 0) continue;
        if (mp[c] >= 4) {
            four += mp[c] / 4;
            mp[c] %= 4;
            if (mp[c] > 0) {
                switch(mp[c]) {
                    case 1:
                        odd++;
                        mp[c] = 0;
                        break;
                    case 2:
                        two++;
                        mp[c] = 0;
                        break;
                    case 3:
                        two++;
                        odd++;
                        mp[c] = 0;
                        break;
                    default:
                        break;
                }
            }
        }
        else if (mp[c] > 1) {
            two++;
            mp[c] %= 2;
            if (mp[c] == 1) {
                odd++;
                mp[c] = 0;
            }
        }
        else if (mp[c] == 1) {
            odd++;
            mp[c] = 0;
        }
    }

    if (h % 2 == 1 and w % 2 == 1) {
        if (odd != 1) {
            cout << "No" << endl;
            return 0;
        }

        if (four >= (h / 2) * (w / 2)) {
            cout << "Yes" << endl;
        }
        else {
            cout << "No" << endl;
        }
    }
    else if (h % 2 == 0 and w % 2 == 0) {
        if (odd > 0) {
            cout << "No" << endl;
            return 0;
        }

        if (four == (h / 2) * (w / 2)) {
            cout << "Yes" << endl;
        }
        else {
            cout << "No" << endl;
        }
    }
    else {
        if (odd > 0) {
            cout << "No" << endl;
            return 0;
        }

        if (four >= (h / 2) * (w / 2)) {
            cout << "Yes" << endl;
        }
        else {
            cout << "No" << endl;
        }
    }

    return 0;
}

