  i64 H, W;
  std::cin >> H >> W;
  std::vector<std::string> a;
  tools::read(a, H);

  std::unordered_map<char, i64> map;
  for (const std::string& a_i : a) {
    for (const char& a_ij : a_i) {
      ++map[a_ij];
    }
  }
  std::vector<i64> slots;
  slots.reserve(map.size());
  std::transform(map.begin(), map.end(), std::back_inserter(slots), [](const std::pair<char, i64>& pair) {
    return pair.second;
  });

  i64 fours = (H / 2 * 2) * (W / 2 * 2) / 4;
  i64 twos = ((H % 2) * W + (W % 2) * H - (H % 2) * (W % 2) * 2) / 2;
  i64 ones = (H % 2) * (W % 2);
  for (i64& slot : slots) {
    while (slot >= 4 && fours > 0) {
      slot -= 4;
      --fours;
    }
  }
  for (i64& slot : slots) {
    while (slot >= 2 && twos > 0) {
      slot -= 2;
      --twos;
    }
  }
  for (i64& slot : slots) {
    while (slot >= 1 && ones > 0) {
      --slot;
      --ones;
    }
  }

  std::cout << (fours == 0 && twos == 0 && ones == 0 ? "Yes" : "No") << std::endl;
  return 0;
}

