inline char gc(void)
{
	#ifndef local_lwq
	static char buf[100000],*p1=buf,*p2=buf;

	if(p1!=p2) return *p1++;

	p1=buf;
	p2=p1+fread(buf,1,100000,stdin);

	return p1==p2?EOF:*p1++;
	#else
	return getchar();
	#endif
}

template<typename T> inline T read(void)
{
	T ret=(T)0;
	bool neg=false;
	char c=gc();

	while(!isdig(c))
	{
		neg|=(c=='-');
		c=gc();
	}
	while(isdig(c))
	{
		ret=ret*10+c-'0';
		c=gc();
	}
	ret=neg?-ret:ret;

	return ret;
}

