bool check_cnt(unordered_map<char, int> &cnt) {
  int odd = 0;
  int even = 0;

  for (auto &e : cnt) {
    odd += (e.second % 2 == 1) ? 1 : 0;
    even += (e.second % 2 == 0) ? 1 : 0;
  }

  if (odd > 1) return false;

  return true;
}

bool check_col(int col) {
  unordered_map<char, int> cnt;

  for (int i = 0; i < h; ++i) {
    cnt[a[i][col]] += 1;
  }

  return check_cnt(cnt);
}

bool check_row(int row) {
  unordered_map<char, int> cnt;

  for (int i = 0; i < w; ++i) {
    cnt[a[row][i]] += 1;
  }

  return check_cnt(cnt);
}

bool check_cols() {
  for (int i = 0; i < w; ++i) {
    if (!check_col(i)) return false;
  }

  return true;
}

bool check_rows() {
  for (int i = 0; i < h; ++i) {
    if (!check_row(i)) return false;
  }

  return true;
}

