    for (int i = 0; i < H * W; ++i) {
        char ai;
        cin >> ai;
        letter.push_back(ai);
    }

    sort(letter.begin(), letter.end());
    vector<int> counter;
    for (int i = 0; i < letter.size(); ++i) {
        int count = 1;
        while (letter[i] == letter[i + 1]) {
            count++;
            i++;
        }
        counter.push_back(count);
    }
    int pair_4 = 0;
    int pair_2 = 0;
    int single = 0;

    for (int i = 0; i < counter.size(); ++i) {
        pair_4 += counter[i] / 4;
        pair_2 += (counter[i] - counter[i] / 4 * 4) / 2;
        single += counter[i] % 2;
    }

    if (H % 2 == 1 && W % 2 == 0) {
        if (is_possible((H - 1) * W / 4, W / 2, pair_4, pair_2) && single == 0)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    } else if (H % 2 == 0 && W % 2 == 1) {
