            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    } else if (H % 2 == 0 && W % 2 == 0) {
        if (pair_4 == H * W / 4 && pair_2 == 0 && single == 0)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    } else {
        if (is_possible((H - 1) * (W - 1) / 4, (H - 1 + W - 1) / 2, pair_4, pair_2) && single == 1)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    }
}

