#include <bits/stdc++.h>
using namespace std;

int cnt[26];

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n, m;
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      char c; cin >> c;
      cnt[c - 'a']++;
    }
  }

  int v1 = 0, v2 = 0, v4 = 0;
  if ((n & 1) && (m & 1)) {
    v1 = 1;
  }
  if (n & 1) v2 += m / 2;
  if (m & 1) v2 += n / 2;
  v4 = (n / 2) * (m / 2);

  priority_queue<int> q;
  for (int i = 0; i < 26; i++) {
    if (cnt[i]) q.push(cnt[i]);
  }

//  cout << v1 << " " << v2 << " " << v4 << endl;
  while (!q.empty() && (v1 || v2 || v4)) {
    int v = q.top(); q.pop();
    if (v4) v -= 4, v4--;
    else if (v2) v -= 2, v2--;
    else if (v1) v -= 1, v1--;
    if (v < 0) {
      cout << "No" << endl;
      return 0;
    }
    if (v) q.push(v);
  }
  if (q.size() || v1 || v2 || v4) cout << "No" << endl;
  else cout << "Yes" << endl;
  return 0;
}

