	if (n % 2 == 0 && m % 2 == 0) {
		valid = (c1 == 0 && c2 == 0);
	} else if (n % 2 == 1 && m % 2 == 1) {
		//2n+1 * 2m+1
		//n+m x 2

		valid = (c1 == 1 && c2 % 2 == (n/2 + m/2) % 2 && c2 <= (n/2 + m/2));
	} else {
		//2a+1 * 2b
		//b

		if (n % 2 == 1) swap(n, m);
		int b = n / 2;
		valid = (c1 == 0 && b % 2 == c1 % 2 && c1 <= b);
	}

	printf("%s\n", valid ? "Yes" : "No");

	return 0;
}

