    if (tmp == 0) continue;
    if (tmp % 2 == 1){
      ones++;
      tmp -= 1;
    }
    // 4の数を入れる
    fours += tmp / 4;
    tmp %= 4;
    // 4を取り除いたあとの2の数を入れる（1個もしくは0個）
    twos += tmp / 2;
    assert(tmp % 2 == 0);
  }

  // H行 W列 の回文行列の標準形を、必要な「同じアルファベットの2人組や4人組（あとは1つか0つのソロ）の数」として求める
