    if (!checked[h][w]){
      checked[h][w] = true;
      ll reverse_h = H - 1 - h; // Hが奇数でも偶数でも同じ
      ll reverse_w = W - 1 - w; // 同上

      // A[h][w]と同じアルファベットである必要があるマスが何個あるか
      // 1つの場合（H, Wともに奇数で、かつ中心の場合）
      if (h == reverse_h && w == reverse_w){
        // ひっくり返しても同じ場合、その方向について「中心」であることが分かる
        // この場合、H, W ともに奇数で、かつ[h][w]が中心マスである
        required_one++;
        // 他にcheckedになるマスはない
      }
      else if (h == reverse_h){
        // 縦向きに中心である つまり、横にしか同アルファベットのマスがない
        required_two++;
        // 反転したマスをcheckedにする
        checked[h][reverse_w] = true;
      }
      else if (w == reverse_w){
        required_two++;
        checked[reverse_h][w] = true;
      }
      else{
        // 縦横どっちについても中心ではない
        required_four++;
        checked[h][reverse_w] = true;
        checked[reverse_h][w] = true;
        checked[reverse_h][reverse_w] = true;
      }
    }
  }

  // required_oneは1か0になっているはず
  // その数と、onesが異なれば構築不可
  if (required_one != ones){
    cout << "No" << endl;
    return 0;
  }

  // あとは、まずfoursから4個の「同じアルファベットの組」をとっていき、必要なところに当てはめる
  // まだ「4つの組」が必要（required_fourが残っている）なのにfoursがなくなっていれば構築不可能。そうでなければあとは「2」の組なので、構築可能
  if (fours >= required_four) cout << "Yes" << endl;
  else cout << "No" << endl;



}

