	map<char, int> cnt;
	REP(i, H) {
		REP(j, W) {
			cnt[f[i][j]]++;
		}
	}

	vector<char> two, one;
	for (auto&& cn : cnt) {
		char c = cn.first;
		int num = cn.second;
		if (num >= 4) num -= (num / 4) * 4;
		int rest = num % 4;
		if (rest >= 2) {
			rest -= 2;
			two.push_back(c);
		}
		if (rest) one.push_back(c);
	}

	if (even(H) and even(W)) YesNo(two.size() == 0 and one.size() == 0);
	else if (odd(H) and odd(W))
		YesNo(
			(((H == 1 or W == 1)) or ((two.size() <= ((H-1)/2 + (W - 1)/2))))
			and one.size() == 1);
	else YesNo(
			(((H == 1 or W == 1)) or ((two.size() <= ((H-1)/2 + (W - 1)/2))))
			and one.size() == 0);

    return 0;
}

