	{
		char c;
		cin >> c;
		mp[c]++;
	}
	if (h % 2 == 0 || w % 2 == 0)
	{
		g1 = 0;
		g4 = h * w / 4;
		if (h % 2 == 0 && w % 2 == 0)
			g2 = 0;
		else
		{
			g2 = (h % 2 == 0 ? h : w) / 2;
			if (h / 2 != 0 && w / 2 != 0) 
			g4 = (h / 2) * (w / 2);
		}
	}
	else
	{
		g1 = 1;
		g2 = (h / 2) + (w / 2);
		g4 = (h / 2) * (w / 2);
	}
	rep(i, g1)
	{
		for (auto p : mp)
		{
			auto k = p.first;
			auto v = p.second;
			if ((v % 4 == 1 || v % 4 == 3) && v > 0) 
			{
				mp[k]--;
				break;
			}
		}
	}
	rep(i, g2)
	{
		for (auto p : mp)
		{
			auto k = p.first;
			auto v = p.second;
			if (v % 4 == 2 && v > 0) 
			{
				mp[k] -= 2;
				break;
			}
		}
	}
	rep(i, g4)
	{
		for (auto p : mp)
		{
			auto k = p.first;
			auto v = p.second;
			if (v % 4 == 0 && v > 0) 
			{
				mp[k] -= 4;
				break;
			}
		}
	}
	bool ok = true;
	for (auto p : mp)
	{
		auto v = p.second;
		if (v != 0)
			ok = false;
	}
	if (ok)
		cout << "Yes" << endl;
	else
		cout << "No" << endl;
	return 0;
}

