	struct graph_w {
		struct road {
			lint to;
			lint w;
		};

		vector<vector<road>> gr;
		lint n;

		graph_w(lint _n) : gr(_n), n(_n) {};
		void input(lint m) {
			rep(i, m) {
				lint a, b, w;
				cin >> a >> b >> w;
				a--; b--;

				road atob, btoa;
				atob.to = b;
				atob.w = w;
				btoa.to = a;
				btoa.w = w;

				gr[a].push_back(atob);
				gr[b].push_back(btoa);
			}
		}
		void d_dfs_impl(lint pos, vector<lint>& d) {
			lint dd = d[pos];

			rep(i, gr[pos].size()) {
				lint child = gr[pos][i].to;
				lint w = gr[pos][i].w;
				if (d[child] > dd + w) {
					d[child] = dd + w;
					d_dfs_impl(child, d);
				}
			}
		}
		auto d_dfs(lint start) {
			vector<lint> d(n, intmax);
			d[start] = 0;
			d_dfs_impl(start, d);

			return d;
		}
		auto d_bfs(lint start) {
			vector<lint> d(n, intmax);
			d[start] = 0;

			queue<lint> q;

			q.push(start);

			while (q.size() > 0) {
				lint pos = q.front();
				q.pop();
				lint dd = d[pos];

				rep(i, gr[pos].size()) {
					lint child = gr[pos][i].to;
					lint w = gr[pos][i].w;
					if (d[child] > dd + w)
					{
						d[child] = dd + w;
						q.push(child);
					}
				}
			}

