    g4 = (h / 2) * (w / 2);
    ll cnt = 0;
    bool f = true;
    rep(i, g1){
        bool g = false;
        for(auto &m : mp){
            if(m.second % 2 == 1){
                g = true;
                m.second--;
                cnt++;
                break;
            }
        }
        if(!g)f = false;
    }
    rep(i, g2){
        bool g = false;
        for(auto &m : mp){
            if(m.second % 4 == 2){
                g = true;
                m.second -= 2;
                cnt += 2;
                break;
            }
        }
        if(!g)f = false;
    }
    rep(i, g4){
        bool g = false;
        for(auto &m : mp){
            if(m.second % 4 == 0){
                g = true;
                m.second -= 4;
                cnt += 4;
                break;
            }
        }
        if(!g)f = false;
    }
    if(cnt != h * w)f = false;
    cout << (f ? "Yes" : "No") << endl;
}

