        four = sum/4;
        two=0;
        one=0;
    }else if(H%2==1 && W%2==1){
        four = (H-1)*(W-1)/4;
        two = (sum-four-1)/2;
        one = 1;
    }else if(H%2==1){
        four = (H-1)*W/4;
        two = W/2;
        one = 0;
    }else{
        four = H*(W-1)/4;
        two = H/2;
