bool solve() {
    int one_found = 0;
    int fcnt = 0;
    for (auto x : cnt) {
        if (x & 1) {
            one_found++;
        }
        fcnt += x / 4;
    }
    if (fcnt < (h / 2) * (w / 2)) return false;
    if ((h & 1) && (w & 1)) {
        if (one_found > 1) return false;
    } else {
        if (one_found) return false;
    }
    return true;
}

