	int H, W; cin >> H >> W;
	VI alp(26, 0),cnt(4,0);
	REP(i,H) {
		string S; cin >> S;
		REP(j, W) alp[S[j] - 'a']++;
	}
	bool flg = true;

	if(!H&1 && !W&1){
		REP(i, 26) if (alp[i] % 4 != 0) flg = false;
	}
	else {
		cnt[0] = (H / 2)*(W / 2);
		cnt[1] = ((H & 1 && W & 1)?1:0);
		cnt[2] = ((W&1)?(H/2):0) + ((H&1)?(W/2):0);
