				if (alp[j] % 4 == 1 || alp[j] % 4 == 3) {
					alp[j] -= 1;
					break;
				}
			}
		}
		REP(i, cnt[2]) {
			REP(j, 26) {
				if (alp[j] % 4 == 2) {
					alp[j] -= 2;
					break;
				}
			}
		}
		REP(i, cnt[0]) {
			sort(ALL(alp), greater<int>());
