int main() {
  int H, W;
  cin >> H >> W;

  vector<int> alphabetCounts(26, 0);
  for (int y = 0; y < H; y++) {
    string S;
    cin >> S;
    for (int x = 0; x < W; x++) {
      alphabetCounts[S[x] - 'a']++;
    }
  }
  sort(alphabetCounts.begin(), alphabetCounts.end());

  for (int y = 0; y < (H + 1) / 2; y++) {
    for (int x = 0; x < (W + 1) / 2; x++) {
      int y2 = H - 1 - y;
      int x2 = W - 1 - x;
      int count = 0;
      if (x == x2 and y == y2) {
        count = 1;
      } else if (x == x2) {
        count = 2;
      } else if (y == y2) {
        count = 2;
      } else {
        count = 4;
      }

      if (count == 1) {
        for (int i = 0; i < 26; i++) {
          if (alphabetCounts[i] % 2 == 1) {
            alphabetCounts[i] -= 1;
            break;
          }
        }
      } else if (count == 4) {
        bool found = false;
        for (int i = 0; i < 26; i++) {
          if (alphabetCounts[i] >= 4) {
            alphabetCounts[i] -= 4;
            found = true;
            break;
          }
        }
        if (!found) {
          printf("No\n");
          return 0;
        }
      } else if (count == 2) {
        bool found = false;
        for (int i = 0; i < 26; i++) {
          if (alphabetCounts[i] % 4 == 2) {
            alphabetCounts[i] -= 2;
            found = true;
            break;
          }
        }
        if (!found) {
          for (int i = 0; i < 26; i++) {
            if (alphabetCounts[i] >= count) {
              alphabetCounts[i] -= 2;
              found = true;
              break;
            }
          }
        }
        if (!found) {
          printf("No\n");
          return 0;
        }
      }
    }
  }

  printf("Yes\n");

  return 0;
}

