                if(temp == 0)   continue;

                if(temp % 4 == mod[i] || temp % 4 == 4 - mod[i]){
                    if(i == 2){
                        g[i] -= temp / 4;
                        it->second -= 4 * (temp / 4);
                    }
                    else{
                        it->second -= mod[i];
                        --g[i];
                    }
                }
            }
        }
        if(g[1] > 0){
            for(auto it = cnt.begin(); it != cnt.end(); ++it){
                if(g[1] <= 0)   break;
                int temp = it->second;
                if(temp == 0)   continue;

                while(it->second > 0){
                    it->second -= 2;
                    --g[1];
                }
            }
        }
        if(g[2] > 0){
            for(auto it = cnt.begin(); it != cnt.end(); ++it){
                if(g[2] <= 0)   break;
                int temp = it->second;
                if(temp == 0)   continue;

                while(it->second > 0){
                    it->second -= 4;
                    --g[2];
                }
            }
        }
    }

    if(g[0] != 0 || g[1] != 0 || g[2] != 0){
        cout << "No\n";
        return 0;
    }
    for(auto it = cnt.begin(); it != cnt.end(); ++it){
        if(it->second != 0){
            cout << "No\n";
            return 0;
        }
    }
    cout << "Yes\n";
}

