int64_t sol() {
   auto ret = 0 * numeric_limits<int64_t>::max();
   if (n < m) swap(n,m);

   int od = 0; for (int c = 0; c < 256; c++) od += br[c] & 1;

   if (0 == (m & 1) || 0 == (n& 1)) {
      if (od)
         return 0 + ret;
   }

   if (1 == m) {
      if (n & 1)
         return 1 == od;
      return 0 == od;
   }

   vector<int> ma;
   int sig = 0;

   for (int c = 0; c < 256; c++) {
      if (br[c]) {
         ma.push_back(br[c]);
         sig += 1 == br[c];
      }
   }
   if (1 == ma.size())
      return 1;
   if (1 < sig)
      return 0;

   if (n & 1) {
      if (m & 1) {
         for (int i = 0; i < (int)ma.size(); i++) {
            if (0 == (ma[i] & 1))
               continue;

            int co[4] = { 0 };
            {
               const auto rem2 = (ma[i] + 3) & 3;
               co[rem2]++;
               co[ma[i] & 3]--;
            }

            for (int j = 0; j < (int)ma.size(); j++) {
               const auto rem = ma[j] & 3;
               co[rem]++;
            }

            if (co[1] || co[3])
               continue;
            if (co[2]*2 <= m+n-1)
               return 1;
         }

         return 0;
      }
   }
   else {
      if (0 == (m & 1)) {
         for (const auto &ce : ma) {
            if (ce & 3)
               return 0;
         }
         return 1;
      }
   }

   if (m & 1)
      swap(n, m);
   assert(n & 1 && 0 == (m&1));
   int re4 = 0;
   for (const auto &ce : ma) re4 += ce & 2;
   return ret + re4 <= m;
}

