bool cando(int h, int w) {
	if(h == 0 || w == 0) {
		return true;
	}
	int newh,neww;
	if(h != 1 && w != 1) {
		newh = h-2;
		neww = w-2;
		bool good = false;
		for(int i = 'a'; i<= 'z'; i++) {
			if(counts[i] >= 4) {
				counts[i]-= 4;
				good = true;
				break;
			}
		}
		if(!good) {
			return false;
		}
		int needdouble = (newh+neww);
		for(int i = 'a'; i<= 'z'; i++) {
			while(counts[i]%4 == 2 && needdouble > 0) {
				needdouble--;
				counts[i]-=2;
			}
		}
		for(int i = 'a'; i<= 'z'; i++) {
			while(counts[i] >= 2 && needdouble > 0) {
				needdouble--;
				counts[i]-=2;
			}
		}
		if(needdouble > 0) {
			return false;
		}
		return cando(newh,neww);
	} else if (h == 1 && w == 1) {
		return true;
	} else if(h == 1) {
		int needdouble = w/2;
		for(int i = 'a'; i<= 'z'; i++) {
			while(counts[i] >= 2 && needdouble > 0) {
				needdouble--;
				counts[i]-=2;
			}
		}
		if(needdouble > 0) {
			return false;
		}
		return true;
	} else {
		int needdouble = h/2;
		for(int i = 'a'; i<= 'z'; i++) {
			while(counts[i] >= 2 && needdouble > 0) {
				needdouble--;
				counts[i]-=2;
			}
		}
		if(needdouble > 0) {
			return false;
		}
		return true;
	}
}

