map<char,ll> mp;

bool solve(ll g1,ll g2, ll g4) {
  for(auto p:mp) {
    if(g1==0) break;
    if(p.second%2==1) {p.second--;g1--;} 
  }
  for(auto p:mp) {
    if(g2==0) break;
    if(p.second%4==2) {p.second--;g2--;} 
  }
  for(auto p:mp) {
    if(g4==0) break;
    if(p.second%4==0) {p.second--;g4--;} 
  }
  bool isok=true;
  for(auto p:mp) if(p.second>0) isok=false;
  return isok;
}

