		if (sum[1] == 1 && sum[2]%2==(H/2+W/2)%2 && sum[3] == 0) flg = true;
		if (sum[1] == 0 && (sum[2]+1)%2==(H/2+W/2)%2 && sum[3] == 1) flg = true;		
	}
	Yn(flg);
