int solve() {
	VI V = { 0, 0, 0 };
	for (int i = 0; i < 26; i++) {
		if (cnt[i] % 2 == 1) V[0]++, cnt[i]--;
		if (cnt[i] % 4 == 2) V[1]++, cnt[i] -= 2;
		V[2] += cnt[i] / 4;
	}

	if ((h % 2) && (w % 2)) {
		if (V[0] != 1) {
			return 0;
		}
