    if (h % 2 == 0 && w % 2 == 0) { // even * even
        rep(i, 26) if (cnt[i] % 4) return false;
        return true;
    }
    else if (h % 2 != 0 && w % 2 != 0) { // odd * odd
        ll one = 1;
        ll two = w/2 + h/2;
        ll four = (w*h - one - two*2) / 4;
        rep(i, 26) if (cnt[i] % 2) --cnt[i], --one;
        if (one < 0) return false;
        rep(i, 26) if (cnt[i] % 4) --two;
        return two >= 0;
    }
    else { // even * odd
        if (h % 2 == 0) swap(w, h);
        ll even = w, odd = h;
        ll two = even / 2;
        ll four = even * (odd-1) / 2;
        rep(i, 26) if (cnt[i] % 2) return false;
        rep(i, 26) {
            if (cnt[i] % 4) --two;
        }
        return two >= 0;
    }
    assert(false);
