  }

  vl cnts(5);
  for (auto iter = charCnts.begin(); iter != charCnts.end(); iter++) {
    ll tmp = iter->second;
    cnts[4] += tmp / 4;
    tmp %= 4;

    cnts[2] += tmp / 2;
    tmp %= 2;

    cnts[1] += tmp;
  }

  if (isYes(H, W, cnts)) {
    print(YES);
  } else {
    print(NO);
  }
  return 0;
}

