vector<int> vectorCnt(vector<char> a) {
    sort(a.begin(),a.end());
    int n=a.size();
    vector<int> b;
    int cnt=1;
    rep(i,n-1) {
            if (a[i+1]!=a[i]) {
                b.push_back(cnt);
                cnt=1;
            } else {
                ++cnt;
            }
    }
    b.push_back(cnt);
    return b;
}

