int main()
{
    int H, W;
    cin >> H >> W;
    vector<string> a(H);
    vector<int> num(26, 0);
    for (int i = 0; i < H; ++i) {
        cin >> a[i];
        for (char c : a[i]) {
            num[c - 'a']++;
        }
    }
    int odd_num = 0, max_num = INT_MIN;
    int num4 = 0, num2 = 0;
    for (int i = 0; i < 26; ++i) {
        if (num[i] % 2 == 1) {
            odd_num++;
        } else {
            num4 += num[i] / 4;
            num2 += (num[i] % 4 / 2);
        }
        max_num = max(max_num, num[i]);
    }

    //4隅が存在するなら少なくとも一個は4つ以上ある文字がないとダメ
    if (H >= 2 && W >= 2 && max_num < 4) {
        cout << "No" << endl;
        return 0;
    }

    if (H % 2 == 0 && W % 2 == 0) {
        //全て偶数じゃないといけない
        if (odd_num == 0 && H * W / 4 <= num4)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    } else if (H % 2 == 1 && W % 2 == 1) {
        if (odd_num == 1 && (H - 1) * (W - 1) / 4 <= num4)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    } else {
        //必ずHが奇数ということにする
        if (H % 2 == 0)
            swap(H, W);

        if (odd_num == 0 && (H - 1) * W / 4 <= num4)
            cout << "Yes" << endl;
        else
            cout << "No" << endl;
    }
}

