#define MAX_H (100)
#define MAX_W (100)
#define SIZE_BUF (30)

using namespace std;

int main() {
  // read inputs
  int H, W;
  char ass[MAX_H][MAX_W], buf[SIZE_BUF];
  scanf("%d %d", &H, &W);
  fgets(buf, SIZE_BUF, stdin);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%c", &ass[i][j]);
    }
    fgets(buf, SIZE_BUF, stdin);
  }

  // count the number of occurences of each letter
  int ns[26] = {};
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      ns[ass[i][j] - 'a']++;
    }
  }

  // place a letter in the center cell
  if (H % 2 == 1 && W % 2 == 1) {
    int num_place = 1;
    for (int k = 0; k < 26; k++) {
      if (ns[k] % 2 == 1) {
        ns[k]--;
        num_place--;
        break;
      }
    }

    if (num_place > 0) {
      printf("No\n");
      return 0;
    }
  }

  // place letters in the center row and column
  if (H % 2 == 1 || H % 2 == 1) {
    int num_place = 0;
    if (H % 2 == 1) {
      num_place += (W / 2) * 2;
    }
    if (W % 2 == 1) {
      num_place += (H / 2) * 2;
    }

    for (int k = 0; k < 26; k++) {
      if (ns[k] % 4 == 2) {
        ns[k] -= 2;
        num_place -= 2;
      }
    }

    if (num_place > 0) {
      for (int k = 0; k < 26; k++) {
        const int num_use = min(ns[k], num_place);
        ns[k] -= num_use;
        num_place -= num_use;
        if (num_place == 0) {
          break;
        }
      }
    }
  }

  // place the rest of the letters
  int is_possible = 1;
  for (int k = 0; k < 26; k++) {
    if (ns[k] % 4 != 0) {
      is_possible = 0;
      break;
    }
  }
  if (is_possible) {
    printf("Yes\n");
  } else {
    printf("No\n");
  }
}

