	vector<int> d(26, 0);


	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cin >> cc[i][j];
			for (int k = 0; k < 26; k++) {
				if (cc[i][j] == abc[k]) {
					d[k]++;
				}
			}
		}
	}

	priority_queue<int> pq;
	for (int i = 0; i < k; i++) {
		if (d[k] != 0) {
			pq.push(d[k]);
		}
	}

	int hh = h / 2;
	int ww = w / 2;
	int p = hh * ww;
	int q = h * w - p * 4;
	int r = q % 2;
	int s = q / 2;

	bool pqr = true;

	while (!pq.empty()) {
		int aa = pq.top();
		pq.pop();
		if (p > 0) {
			if (aa >= 4) {
				aa -= 4;
				if (aa > 0) {
					pq.push(aa);
				}
			}
			else {
				pqr = false;
				break;
			}
			p--;
		}
		else if (s > 0) {
			if (aa >= 2) {
				aa -= 2;
				if (aa > 0) {
					pq.push(aa);
				}
			}
			else {
				pqr = false;
				break;
			}
			s--;
		}
		else if (r > 0) {
			if (aa >= 1) {
				aa--;
				if (aa > 0) {
					pq.push(aa);
				}
			}
			else {
				pqr = false;
				break;
			}
			r--;
		}
		else {
			break;
		}
	}

	if (pqr) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

