typedef long long ll;

int H, W;

int main() {
    cin >> H >> W;
    int alpha[26];
    memset(alpha, 0, sizeof(alpha));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c;
            cin >> c;
            alpha[c - 'a']++;
        }
    }

    priority_queue<int> pq;
    for (int i = 0; i < 26; i++) {
        pq.push(alpha[i]);
    }

    bool f = true;
    for (int i = 0; i < (H+1)/2; i++) {
        for (int j = 0; j < (W+1)/2; j++) {
            int tp = pq.top();
            pq.pop();
            if (i == H/2 && j == W/2) {
                if (tp < 1) {
                    f = false;
                    break;
                }
                pq.push(tp - 1);
            }
            else if (i == H/2 || j == W/2) {
                if (tp < 2) {
                    f = false;
                    break;
                }
                pq.push(tp - 2);
            }
            else {
                if (tp < 4) {
                    f = false;
                    break;
                }
                pq.push(tp - 4);
            }
        }
        if (!f) break;
    }

    cout << (f ? "Yes" : "No") << endl;

    return 0;
}

