int n,m,buc[30],num;
char read[110];
void sub1()
{
	for(int i = 1;i <= 26;i++)
	{
		num += buc[i] / 2;
		buc[i] %= 2;
	}
	if(n / 2 > num)
	{
		printf("No\n");
		return;
	}
	printf("Yes\n");
}
void sub2()
{
	for(int i = 1;i <= 26;i++)
	{
		num += buc[i] / 2;
		buc[i] %= 2;
	}
	if(m / 2 > num)
	{
		printf("No\n");
		return;
	}
	printf("Yes\n");
}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i = 1;i <= n;i++)
	{
		scanf("%s",read + 1);
		for(int j = 1;j <= m;j++)
			buc[read[j] - 'a' + 1]++;
	}
	if(m == 1 && n >= 1){sub1();return 0;}
	if(n == 1 && m > 1){sub2();return 0;}
	for(int i = 1;i <= 26;i++)
	{
		num += buc[i] / 4;
		buc[i] %= 4;
	}
	if(n > 1 && m > 1 && n / 2 * m / 2 > num)
	{
		printf("No\n");
		return 0;
	}
	if(n % 2 == 1 || m % 2 == 1)
	{
		int cnt = 0;
		for(int i = 1;i <= 26;i++)if(buc[i] % 2)cnt++;
		if(cnt > 1)
		{
			printf("No\n");
			return 0;
		}
	}
	printf("Yes\n");
}

