using namespace std;

char alphas[26] = {'a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t','u','v','w','x','y','z'};

int main(){
    int H,W,sum,four,two,one;
    cin >> H >> W;
    sum = H*W;
    if(H%2==0 && W%2==0){
        four = sum/4;
        two=0;
        one=0;
    }else if(H%2==1 && W%2==1){
        four = (H-1)*(W-1)/4;
        two = (sum-4*four-1)/2;
        one = 1;
    }else if(H%2==1){
        four = (H-1)*W/4;
        two = W/2;
        one = 0;
    }else{
        four = H*(W-1)/4;
        two = H/2;
        one = 0;
    }

    vector<string> a(H);
    map<char,int> mp;
    for(int i=0;i<H;i++){
        cin >> a[i];
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            mp[a[i][j]]++;
        }
    }

    for(int i=0;i<26;i++){
        if(one==0){
            break;
        }
        if(mp[alphas[i]]%4==1 || mp[alphas[i]]%4==3){
            mp[alphas[i]]--;
            one--;
        }
    }

    for(int i=0;i<26;i++){
        if(two==0){
            break;
        }
        if(mp[alphas[i]]%4==2){
            mp[alphas[i]]-=2;
            two--;
        }
    }

    for(int i=0;i<26;i++){
        if(four==0){
            break;
        }
        while(mp[alphas[i]]%4==0 && 0<mp[alphas[i]]){
            if(four==0){
                break;
            }
            mp[alphas[i]] -= 4;
            four--;
        }
    }

    for(int i=0;i<26;i++){
        if(mp[alphas[i]]!=0){
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;
}

