int cnt[MaxN + 5], n, m;
char s[MaxN + 5];
void Init() {
	memset(cnt, 0, sizeof(cnt));
	for (int i = 1;i <= n;i++) {
		scanf("%s", s + 1);
		for (int j = 1; j <= m; j++) cnt[s[j]]++;
	}
}

void Solve() {
	int cnt_1 = 0, cnt_4 = 0, cnt_2 = 0;
	for (char i = 'a'; i <= 'z'; i++) {
		if(cnt[i] % 4 == 0) cnt_4++;
			else if(cnt[i] % 4 == 2) cnt_2++;
				else if(cnt[i] % 2 == 1) cnt_1++;
	}
	if((n & 1) && (m & 1)) {
		if((cnt_2 == n / 2 + m / 2) && cnt_1 == 1) printf("%Yes\n");
			else printf("No\n");
	}
	else if((n & 1) && (m % 2 == 0)) {
		if(cnt_2 == m / 2 && cnt_1 == 0) printf("Yes\n");
			else printf("No\n");
	}
	else if((n % 2 == 0) && (m & 1)) {
		if(cnt_2 == n / 2 && cnt_1 == 0) printf("Yes\n");
			else printf("No\n");
	}
	else {
		if(cnt_2 == 0 && cnt_1 == 0) printf("Yes\n");
			else printf("No\n");
	}
}
int main()
{
	while(~scanf("%d%d", &n, &m)) {
		Init();
		Solve();
	}
}

