        // 全部2の倍数
        two -= W/2;
        four -= H/2*W/2;
        if(one!=0 || two!=0 || four!=0) return false;
    }
    else{
        one--;
        two -= H/2+W/2;
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    return true;
}   

