int main()
{
	int h, w;
	cin >> h >> w;
	char c;
	for (int i = 0 ; i < h*w ; i++)
		cin >> c, cnt[c-'a']++;
	multiset<int> ss;
	for (int i = 0 ; i < 26 ; i++)
		if (cnt[i])
			ss.insert(cnt[i]);
	VI v;
	for (int i = 0 ; i < h/2 ; i++) {
		for (int j = 0 ; j < w/2 ; j++) {
			int a = 1;
			if (h - i - 1 > (h-1)/2) {
				a++;
				if (w - 1 - j > (w-1)/2)
					a+=2;
			}
			else if (w - 1 - j > (w-1)/2)
				a++;
			v.PB(a);
		}
	}
	sort(ALL(v), greater<int>());
	string ans = "Yes\n";
	for (auto it : v) {
		auto best = *ss.rbegin();
		if (best < it)
			ans = "No\n";
		else {
			ss.erase(best);
			best -= it;
			if (best)
				ss.insert(best);
		}
	}
	cout << ans;
	return 0;
}

