bool evens(){
	for(int i=0;i<=25;i++){
		if(C[i]%2!=0) return false;
	}
	return true;
}

bool evens_odd(){
	int count = 0;
	for(int i=0;i<=25;i++){
		if(C[i]%2!=0) count++;
	}
	if(count==1) return true;
	else false;
}

bool fours(){
	for(int i=0;i<=25;i++){
		if(C[i]%4!=0) return false;
	}
	return true;
}

bool odd_odd1(){
	int count = 0;
	for(int i=0;i<=25;i++){
		while(C[i]%4!=0){
			count++;
			C[i] -= 4;
			if(count==(H/2)*(W/2)) break;
		}
		if(count==(H/2)*(W/2)) break;
	}
	if(count <(H/2)*(W/2)) return false;
	else return evens_odd();
}


bool even_odd(int A,int B){
	int count = 0;
	for(int i=0;i<=25;i++){
		while(C[i]%4!=0){
			count++;
			C[i] -= 4;
			if(count==(A/2)*(B/2)) break;
		}
		if(count==(A/2)*(B/2)) break;
	}
	if(count < (A/2)*(B/2)) return false;
	else return evens();
}

