using namespace std;

int main() {
    int h, w;
    cin >> h >> w;
    vector<string> grid(h);
    for(int i = 0; i < h; i++)
    {
        cin >> grid[i];
    }
    vector<int> alphabet(26, 0);
    for(int i = 0; i < h; i++)
    {
        for(int j = 0; j < w; j++)
        {
            alphabet[grid[i][j] - 'a']++;
        }
    }
    auto check = [&]()
    {
        int odd = 0;
        int even = 0;
        for(int i = 0; i < 26; i++)
        {
            if(alphabet[i] == 1)
            {
                odd++;
            }else if(alphabet[i] == 2)
            {
                even++;
            }
        }
        return make_pair(odd, even);
    };
    for(int i = 0; i < 26; i++)
    {
        alphabet[i] = alphabet[i] % 4;
    }
    pair<int, int> result = check();
    //evenの数のチェックが必要
    if(h % 2 == 0 && w % 2 == 0)
    {
        //すべて0である必要がある
        if(result.second == 0 && result.first == 0)
        {
            cout << "Yes" << endl;
        }else{
            cout << "No" << endl;
        }
        return 0;
    }else if(h % 2 != 0 && w % 2 != 0)
    {
        //奇数，奇数
        //h - 1個までの2だったらYes
        if(result.first == 1 && result.second <= h - 1)
        {
            cout << "Yes" << endl;
        }else{
            cout << "No" << endl;
        }
    }else{
        //奇数，偶数
        //h or w / 2個までの2だったらYes
        int temp = h % 2 == 0 ? h : w;
        if(result.first == 0 && result.second <= temp / 2)
        {
            cout << "Yes" << endl;
        }else{
            cout << "No" << endl;
        }
    }
    return 0;
}

