class TaskC {
public:
	void solve(std::istream& in, std::ostream& out) {
		int n, m;
		in >> n >> m;
		vector<int> cnt(26);
		for (int i: range(n)) {
			for (int j: range(m)) {
				char c;
				in >> c;
				++cnt[c - 'a'];
			}
		}

		int cntOdd = 0;
		for (int i: range(26)) {
			if (cnt[i] % 2) {
				++cntOdd;
				--cnt[i];
			}
			cnt[i] /= 2;
		}
		if (cntOdd > 1) {
			out << "No\n";
			return;
		}
		int cnt2 = 0;
		for (int i: range(26)) {
			if (cnt[i] % 2) {
				++cnt2;
			}
		}

		int allowedCnt2 = (n % 2 ? m / 2 : 0) + (m % 2 ? n / 2: 0);
		if (cnt2 <= allowedCnt2) {
			out << "Yes\n";
			return;
		}
		out << "No\n";
	}
};


