using namespace std;

const int MAXN = 1000001;

int n,m;
int tam[MAXN];
int num[MAXN];
int parent[MAXN];

int Find(int u) {
	return u == parent[u] ? u : parent[u] = Find(parent[u]);
}

void Union(int u,int v) {
	int Ru = Find(u), Rv = Find(v);
	if(Ru == Rv) return;
	parent[Ru] = Rv;
	tam[Rv] += tam[Ru];
}

void Crear(int i,int a,int b) {
	while(a < b) {
		Union(i * m + a, i * m + b);
		a++, b--;
	}
}

void Crear2(int j,int a,int b) {
	while(a < b) {
		Union(a * m + j, b * m + j);
		a++, b--;
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	char c;
	cin>>n>>m;
	forn(i, n * m) {
		cin>>c;
		num[c]++;
	}

	forn(i, n)
	forn(j, m) {
		tam[i * m + j] = 1;
		parent[i * m + j] = i * n + j;
	}

	forn(i, n)
		Crear(i, 0, m - 1);

	forn(i, m)
		Crear2(i, 0, n - 1);

	set<int> s;
	vector<int> aux;
	forn(i, n)
	forn(j, m)
		if(s.find(Find(i * m + j)) == s.end()) {
			s.insert(Find(i * m + j));
			aux.pb(tam[Find(i * m + j)]);
		}
	sort(aux.begin(), aux.end());
	priority_queue<int> q;
	forn(i, MAXN)
		if(num[i]) {
			q.push(num[i]);
		}

	int i;
	for(i=aux.size()-1;i>=0 && !q.empty();) {
		int num = q.top();
		q.pop();
		if(num < aux[i]) break;
		if(num - aux[i] > 0) q.push(num - aux[i]);
		i--;
	}

	if(i < 0) cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}

