    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);
    lint H, W; cin >> H >> W;
    unordered_map<char, lint> count;
    range(i, 0, H) range(j, 0, W) {
        char c; cin >> c;
        count[c] += 1;
    }
    lint num_4 = 0, num_2 = 0, num_1 = 0;
    for (const auto& p : count) {
        char c; lint cnt;
        tie(c, cnt) = p;
        if (cnt >= 4) {
            num_4 += cnt / 4;
            cnt %= 4;
        }
        if (cnt >= 2) {
            num_2 += cnt / 2;
            cnt %= 2;
        }
        if (cnt >= 1) {
            num_1 += 1;
        }
    }
    bool is_feasible;
    if (H % 2 == 0 and W % 2 == 0) {
        is_feasible = (num_2 == 0) and (num_1 == 0);
    } else if (H % 2 == 0) {
        is_feasible = (num_2 <= (H / 2)) and (num_1 == 0);
    } else if (W % 2 == 0) {
        is_feasible = (num_2 <= (W / 2)) and (num_1 == 0);
