void solve(){
  int h,w;
  cin>>h>>w;
  vector<string>a(h);
  rep(i,h)cin>>a[i];
  bool ok=false;
  vector<int>c(26);
  rep(i,h){
    rep(j,w){
      c[a[i][j]-'a']++;
    }
  }
  int sum=0;
  rep(i,26){
    sum+=c[i]/4;
    c[i]%=4;
  }
  if(h%2==1&&w%2==1){
    int two=(h+w-2)/2;
    int one=1;
    rep(i,26){
      if(c[i]==2)two-=c[i]/2;
      else if(c[i]==1)one-=c[i];
    }
    if(two>=0&&one==0)ok=true;
  }
  else if(h%2==1){
    int two=w/2;
    bool ng=false;
    rep(i,26){
      if(c[i]==2)two-=c[i]/2;
      if(c[i]%2)ng=true;
    }
    if(!ng&&two>=0)ok=true;
  }
  else if(w%2==0){
    int two=h/2;
    bool ng=false;
    rep(i,26){
      if(c[i]==2)two-=c[i]/2;
      if(c[i]%2)ng=true;
    }
    if(!ng&&two>=0)ok=true;
  }
  else {
    bool ng=false;
    rep(i,26){
      if(c[i]!=0)ng=true;
    }
    if(!ng)ok=true;
  }
  if(ok)cout<<"Yes";
  else cout<<"No";
}

