const int C = 26;

int n, m;
int cnt[C];

bool fuck(int a1, int a2, int a4) {
	for (int i = 0; a1 && i < C; i++) {
		if (cnt[i] % 2 == 1) {
			a1--;
			cnt[i]--;
		}
	}
	if (a1) return false;
	for (int i = 0; i < C; i++) {
		if (cnt[i] % 2 != 0) {
			return false;
		}
	}

	for (int i = 0; a2 && i < C; i++) {
		while (cnt[i] % 4 == 2) {
			a2--;
			cnt[i] -= 2;
		}
	}

	if (a2) return true;

	for (int i = 0; i < C; i++) {
		if (cnt[i] % 4 != 0) return false;
	}

	return true;
}

