public:
  int N;
  Tmp(int N)
  : N(N)
  {}
};

void solve(void)
{
  int H, W; cin >> H >> W;
  vector<vector<char>> table(H, vector<char>(W));
  map<char, int> mp{};
  for (auto& r : table) {
    for (auto& c : r) {
      cin >> c;
      ++mp[c];
    }
  }

  int ex4{}, ex2{}, ex1{};
  bool p = H % 2 == 0;
  bool q = W % 2 == 0;
  if (p && q) {
    ex4 = (W / 2) * (H / 2);
  } else if (p) {
    ex4 = (W / 2) * (H / 2);
    ex2 = (H / 2);
  } else if (q) {
    ex4 = (W / 2) * (H / 2);
    ex2 = (W / 2);
  } else {
    ex4 = (W / 2) * (H / 2);
    ex2 = (W / 2) + (H / 2);
    ex1 = 1;
  }
  int cnt4{}, cnt2{}, cnt1{};
  for (char c = 'a'; c <= 'z'; ++c) {
    auto n = mp[c];
    if (n >= 4) {
      cnt4 += n / 4;
      n %= 4;
    }
    if (n >= 2) {
      cnt2 += n / 2;
      n %= 2;
    }
    if (n > 0) {
      cnt1 += n;
    }
  }
  if (cnt2 < ex2) {
    auto d = ex2 - cnt2;
    if (d * 2 > cnt4) {
      cout << "No" << CRLF;
      return;
    }
    cnt2 += d;
    cnt4 -= d*2;
    assert(cnt2 == ex2);
    assert(cnt4 >= 0);
  }
  if (cnt4 < ex4) {
    cout << "No" << CRLF;
    return;
  }
  cout << "Yes" << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

