int main() {
    int H, W;
    cin >> H >> W;

    vector<string> a(H);
    map<char, int> counter;
    for (int i = 0; i < H; i++) {
        cin >> a[i];
        for (char ch : a[i]) {
            counter[ch]++;
        }
    }
    if ((H & 1) and (W & 1)) {   // 両方奇数
        int life2 = H / 2 + W / 2,
            life1 = 1;
        for (auto& mp : counter) {
            if (mp.second % 4 == 0) continue;
            if (mp.second % 2 == 1) {
                life1--;
            }
            if (mp.second % 4 == 0) continue;
            if (mp.second % 2 == 0) {
                life2--;
            }
        }
        if (life1 == 1 or life2 < 0 ) cout << "No" << endl;
        else cout << "Yes" << endl;

    } else if ((H & 1) or (W & 1)) {
        int life = (H & 1) ? W / 2 : H / 2;
        for (auto& mp : counter) {
            if (mp.second % 4 == 0) continue;

            if (mp.second % 2 == 0) {
                life--;
            } else {
                cout << "No" << endl;
                return 0;
            }
        }
        if (life >= 0) cout << "Yes" << endl;
        else cout << "No" << endl;

    } else {
        for (auto& mp : counter) {
            if (mp.second % 4 != 0) {
                cout << "No" << endl;
                return 0;
            }
        }
        cout << "Yes" << endl;
    }

    return 0;
}

