const int N = 110;
const int A = 26;
int n, m;
int cnt[A];
char s[N];

void solve()
{
	scanf("%d%d", &n, &m);
	for(int i = 0; i < n; ++i)
	{
		scanf("%s", s);
		for (int j = 0; j < m; ++j)
			++cnt[s[j] - 'a'];
	}
	bool ok = true;
	if (n % 2 == 0 && m % 2 == 0)
	{
		for (int i = 0; i < A; ++i)
			ok &= cnt[i] % 4 == 0;
	}
	if (n * m % 2 == 1)
	{
		int twos = n / 2 + m / 2;
		int ones = 1;
		for (int i = 0; i < A; ++i)
		{
			cnt[i] %= 4;
			if (cnt[i] % 2 == 1)
			{
				--cnt[i];
				--ones;
			}
			if (cnt[i] == 2)
				--twos;
		}
		if (ones != 0)
			ok = false;
		if (!(twos >= 0 && twos % 2 == 0))
			ok = false;
	}
	else
	{
		int twos = n % 2 == 0 ? n / 2 : m / 2;
		for(int i = 0; i < A; ++i)
		{
			cnt[i] %= 4;
			if (cnt[i] % 2 == 1)
				ok = false;
			else if (cnt[i] != 0)
				--twos;
		}
		if (!(twos >= 0 && twos % 2 == 0))
			ok = false;
	}
	puts(ok ? "Yes" : "No");
}

