bool solve(){
    map<char,int> cnt;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            cnt[A[i][j]]++;
        }
    }
    int four = 0, two = 0, one = 0;
    for (char c = 'a'; c <= 'z'; c++)
    {
        four+= cnt[c]/4;
        two += (cnt[c]%4)/2;
        one += (cnt[c]%4)%2;
    }

    if(H%2==0 && W%2==0){
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    else if(H%2!=0 && W%2==0){
        // 全部2の倍数
        two -= W/2;
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    else if(H%2==0 && W%2!=0){
        // 全部2の倍数
        two -= H/2;
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    else{
        one--;
        two -= (H/2)+(W/2);
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    return true;
}   

