        cnt[i] -= n * 2;
        two -= n;
    }
    for(int i = 0; i < 26 && one; i++) {
        if(cnt[i] & 1) {
            one = 0;
            cnt[i]--;
            break;
        }
    }
    return one == 0 &&
           two == 0 &&
           four == 0;
}

