using namespace std;
typedef long long ll;

ll N, M;
string S[100];

int main(void) {
  cin >> N >> M;
  REP(i, 0, N) cin >> S[i];

  ll cnt[256];
  REP(i, 0, 256) cnt[i] = 0;
  REP(i, 0, N) REP(j, 0, M) cnt[S[i][j]]++;

  map<ll, ll> mp;
  REP(i, 0, 256) {
    if(cnt[i] % 4 == 0) mp[4] += cnt[i];
    if(cnt[i] % 4 == 1) mp[1] += 1;
    if(cnt[i] % 4 == 2) mp[2] += 2, mp[4] += (cnt[i] - 2);
    if(cnt[i] % 4 == 3) mp[1] += 1, mp[2] += 2, mp[4] += (cnt[i] - 3);
  }

  bool f;
  if(N % 2 == 1 && M % 2 == 1) {
    bool f1 = mp[1] == 1;
    bool f2 = mp[2] <= M + N - 1 && (M + N - 1 - mp[2]) % 4 == 0;
    f = f1 && f2;
  }
  if(N % 2 == 1 && M % 2 == 0) {
    bool f1 = mp[1] == 0;
    bool f2 = mp[2] <= M && (M - mp[2]) % 4 == 0;
    f = f1 && f2;
  }
  if(N % 2 == 0 && M % 2 == 1) {
    bool f1 = mp[1] == 0;
    bool f2 = mp[2] <= N && (N - mp[2]) % 4 == 0;
    f = f1 && f2;
  }
  if(N % 2 == 0 && M % 2 == 0) {
    bool f1 = mp[1] == 0;
    bool f2 = mp[2] == 0;
    f = f1 && f2;
  }

  cout << (f ? "Yes" : "No") << endl;
}

