    cin>>h>>w;
    char mat[h][w];
    for(int i=0;i<h;++i)
        for(int j=0;j<w;++j)
            cin>>mat[i][j];
    int cnt[26]={0};
    for(int i=0;i<h;++i)
        for(int j=0;j<w;++j)
            cnt[mat[i][j]-'a']++;
    sort(cnt,cnt+26,comp);
    for(int i=0;i<h/2;++i)
        for(int j=0;j<w/2;++j){
            if(cnt[0]>=4){
                cnt[0]-=4;
                sort(cnt,cnt+26,comp);
            }
            else{
                cout<<"NO";
                return;
            }
        }
    if(h%2 && w%2){
        for(int i=0;i<h/2;++i){
            if(cnt[0]>=2){
                cnt[0]-=2;
                sort(cnt,cnt+26,comp);
            }
            else
            {
                cout<<"NO";
                return;
            }
        }
        for(int i=0;i<w/2;++i){
            if(cnt[0]>=2){
                cnt[0]-=2;
                sort(cnt,cnt+26,comp);
            }
            else
            {
                cout<<"NO";
                return;
            }
        }
    }
    else if(h%2 || w%2){
        int c=(h%2)?h:w;
        for(int i=0;i<c/2;++i){
            if(cnt[0]>=2){
                cnt[0]-=2;
                sort(cnt,cnt+26,comp);
            }
            else
