        for (int j = 0; j < W; ++j) {
            char c;
            cin >> c;

            ++cnt[c - 'a'];
        }
    }

    unordered_map<int, int> stock;

    if (H % 2 == 1 && W % 2 == 1) {
        stock[1] = 1;
    }

    if (H % 2 == 1) {
        stock[2] += W / 2;
    }
    if (W % 2 == 1) {
        stock[2] += H / 2;
    }

    stock[4] = (H * W - 2 * stock[2] - stock[1]) / 4;

    //LOG("%d %d %d\n", stock[1], stock[2], stock[4]);

    for (int i = 0; i < 26; ++i) {
        for (int x : { 4, 2, 1 }) {
