            if (cnt[i] >= x) {
                int use = min(cnt[i] / x, stock[x]);
                cnt[i] -= use * x;
                stock[x] -= use;

                //LOG("%d/%d : %d, %d, %d\n", cnt[i], x, use, cnt[i], stock[i]);
            }
        }
        if (cnt[i] > 0) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;

    return 0;
}

