#include <bits/stdc++.h>

using namespace std;

using ll = long long;

bool Check(auto cnt, const int h, const int w) {
    const int n1 = floor(h / 2.0) * floor(w / 2.0);
    const int n2 = floor((h * w - n1 * 4) / 2.0);

    for (auto &it : cnt)
        if (it.second % 2 == 1) {
            --it.second;
            break;
        }
    for (auto &it : cnt)
        if (it.second % 2 == 1) return false;

    int x1 = 0, x2 = 0;
    for (auto &it : cnt) {
        if (it.second == 2) {
            ++x2;
            it.second = 0;
        }
    }
    for (auto &it : cnt) {
        if (0 < it.second && it.second % 4 != 0) {
            ++x2;
            it.second -= 2;
        }
    }
    if (n2 < x2) return false;
    for (auto &it : cnt) {
        if (0 < it.second && it.second % 4 == 0) {
            x1 += it.second / 4;
            it.second = 0;
        }
    }
    for (auto &it : cnt)
        if (0 < it.second) return false;

    if (x1 != n1 || n2 != x2) return false;

    return true;
}

