bool f(int n, int m, vector<int>& v) {
  while (n > 0) {
    if (v.back() < m) {
      return false;
    }
    if (v.back() >= m) {
      v.back() -= m;
      n -= m;
    }
    sort(v.begin(), v.end());
  }
  return true;
}

