            int odd = h%2;
            for(int i = 0; i < 26; i++) odd -= (cnt[i]%2);
            if(odd == 0)    cout << "Yes" << endl;
            else            cout << "No" << endl;
        }
        return 0;
    }

    auto f = [&](int a, int b) -> bool{
        for(int i = 0; i < 26 && a > 0; i++){
            if(cnt[i] == 2 || cnt[i] == 3)    cnt[i] -= 2, a--;
        }
        for(int i = 0; i < 26 && a > 0; i++){
            while(cnt[i] >= 2 && a > 0) cnt[i] -= 2, a--;
        }
        for(int i = 0; i < 26 && b > 0; i++){
            while(cnt[i] >= 4 && b > 0)  cnt[i] -= 4, b--;
        }
        return (a == 0 && b == 0);
    };

    bool judge = true;
    if(h%2 + w%2 == 0){
        for(int x : cnt)    judge &= (x%4==0);
    }else if(h%2 + w%2 == 2){
        int want4 = (h-1)/2*(w-1)*2;
        int want2 = (h-1)/2 + (w-1)/2;
        judge = f(want2, want4);
