using namespace std;

int H, W;
signed main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin >> H >> W;
    map<char, int> map;
    REP(i, H) REP(j, W) {
        char c;
        cin >> c;
        map[c]++;
    }

    bool ok = true;
    if (W & 1 && H & 1) {
        int oddnum = 0;
        for (auto& kv : map) {
            if (kv.second % 4 == 1) {
                kv.second--;
                oddnum++;
            }
        }
        if (oddnum > 1) ok = false;

        int twonum = 0;
        for (auto& kv : map) {
            if (kv.second % 4 == 2) {
                twonum++;
                kv.second -= 2;
            }
        }
        if (twonum > H / 2 + W / 2) ok = false;

        for (auto kv : map) {
            if (kv.second % 4 != 0) ok = false;
        }
    } else if ((W & 1) == 0 && (H & 1) == 0) {
        for (auto kv : map) {
            if (kv.second % 4 != 0) ok = false;
        }
    } else {
        int twonum = 0;
        for (auto& kv : map) {
            if (kv.second % 4 == 2) {
                twonum++;
                kv.second -= 2;
            }
        }
        int t = H & 1 ? W : H;
        if (twonum > t / 2) ok = false;

        for (auto kv : map) {
            if (kv.second % 4 != 0) {
                ok = false;
            }
        }
    }

    ok ? cout << "Yes" << endl : cout << "No" << endl;
    return 0;
}

