			{
				return false;
			}
		}
	}
	else if (n % 2 || m % 2)
	{
		for (int i = 0; i<26; i++)
		{
			temp[i] %= 4;
		}
		if (n % 2 != m % 2)
		{
			int count = 0;
			for (int i = 0; i<26; i++)
			{
				if (temp[i] % 2 == 1)
				{
					return false;
				}
				else if (temp[i]) count++;
			}
			if (m % 2)
				if (count>(n / 2)) return false;
				else
					if (count>(m / 2)) return false;
		}
		else
		{
			int counto = 0, counte = 0;
			for (int i = 0; i<26; i++)
			{
				if (temp[i] % 2 == 1)
				{
					counto++;
				}
				else if (temp[i]) counte++;
				if (counte>(n / 2 + m / 2)) return false;
				if (counto>1) return false;
			}
		}
	}
	return true;
}

