  memset(t, -1, sizeof(t));

  REP(i, H) {
    string s; cin >> s;
    REP(j, W) bin[s[j]-'a']++;
  }

  int Q = 0;
  REP(i, H) REP(j, W) {
    if (t[i][j] == -1) {
      t[i][j] = Q;
      t[H-1-i][j] = Q;
      t[i][W-1-j] = Q;
      t[H-1-i][W-1-j] = Q;
      Q++;
    }
  }

  vector<int> need(5);
  {
    map<int,int> counter;
    REP(i, H) REP(j, W) {
      counter[ t[i][j] ] += 1;
    }
    for (auto it = counter.begin(); it != counter.end(); ++it) {
      need[it->second]++;
    }
  }
  bool ans = true;

  vector<int> have;
  for (int i = 0; i < 26; i++){
    int x = bin[i];
    while (need[4] > 0 && x >= 4) {
      x -= 4;
      need[4]--;
    }
    if (x > 0) have.push_back(x);
  }
  if (need[4] > 0) ans = false;

  // pv(ALL(need));
  // pv(ALL(have));
  for (int i = 0; i < (int)have.size(); i++) {
    while (need[3] > 0 && have[i] >= 3) {
      need[3]--;
      have[i] -= 3;
    }
  }
  for (int i = 0; i < (int)have.size(); i++) {
    while (need[2] > 0 && have[i] >= 2) {
      need[2]--;
      have[i] -= 2;
    }
  }
  for (int i = 0; i < (int)have.size(); i++) {
    while (need[1] > 0 && have[i] >= 1) {
      need[1]--;
      have[i] -= 1;
    }
  }

  if (need[1] + need[2] + need[3] + need[4] > 0) ans = false;



  cout << (ans?"Yes":"No") << endl;
  return 0;
}

