  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cin >> field[i][j];
    }
  }

  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      _count[field[i][j]-'a']++;
    }
  }

  // 1,2,4個あるべき数を計算
  int one = 1;
  int two = H / 2 + W / 2;
  int four = (H / 2) * (W / 2);
  if (!(H & 1) && !(W & 1)) {
    one = two = 0;
  } else if (!(H & 1) || !(W & 1)) {
    one = 0;
    if (!(H & 1)) two = H / 2;
    else two = W / 2;
  }

  int cnt = 0;
  for (int i = 0; i < 26; i++) {
    if (cnt == one) break;
    if (_count[i] % 4 == 1 || _count[i] % 4 == 3) {
      _count[i]--;
      cnt++;
    }
  }
  cnt = 0;
  for (int i = 0; i < 26; i++) {
    if (cnt == two) break;
    while (_count[i] % 4 == 2) {
      _count[i] -= 2;
      cnt++;
      if (cnt == two) break;
    }
  }
  cnt = 0;
  for (int i = 0; i < 26; i++) {
    if (cnt == four) break;
    if (_count[i] == 0) continue;
    while (_count[i] % 4 == 0) {
      _count[i] -= 4;
      cnt++;
      if (cnt == four || _count[i] == 0) break;
    }
  }

  string ans = "Yes";
  for (int i = 0; i < 26; i++) {
    if (_count[i]) ans = "No";
  }

  // 解答
