int main()
{
  err();
  cin>>h>>w;
  int a=h*w;
  bool ht = h%2==0;
  bool wt = w%2==0;
  REP(i,h)
  {
    string s; cin>>s;
    for (char c : s) mp[c-'a']++;
  }

  if (ht&&wt)
  {
    REP(i,26) if (mp[i]%4!=0) err();
    cout << "Yes" << endl;
