using namespace std;

const int MAXN = 100 + 10;

int H, W;
char A[MAXN][MAXN];
int cnt[1000];
int used[MAXN][MAXN];

bool chk()
{
	for (int i = 0; i < H; i ++)
		for (int j = 0; j < W; j ++)
			cnt[A[i][j]] ++;
	int ccc[5] = {0, 0, 0, 0, 0};
	for (int i = 0; i < H; i ++)
		for (int j = 0; j < W; j ++)
			if (! used[i][j])
			{
				int ii, jj;
				int cc = 0;
				ii = i; jj = j; cc += (used[ii][jj] == 0); used[ii][jj] = 1;
				ii = H - 1 - i; jj = j; cc += (used[ii][jj] == 0); used[ii][jj] = 1;
				ii = i; jj = W - 1 - j; cc += (used[ii][jj] == 0); used[ii][jj] = 1;
				ii = H - 1 - i; jj = W - 1 - j; cc += (used[ii][jj] == 0); used[ii][jj] = 1;
				ccc[cc] ++;
			}
	for (int i = 4; i >= 0; i --)
		while (ccc[i] --)
		{
			int ok = 0;
			for (char c = 'z'; c >= 'a'; c --)
				if (cnt[c] >= i)
				{
					cnt[c] -= i;
					ok = 1;
					break;
				}
			if (ok == 0)
				return 0;
		}
	return 1;
}

void Work()
{
	scanf("%d%d", &H, &W);
	for (int i = 0; i < H; i ++)
		scanf("%s", A[i]);
	printf(chk() ? "Yes\n" : "No\n");
}

int main()
{
	Work();
	return 0;
}

