#include <stdio.h>
#include <stdlib.h>
#include <algorithm>

#define MAX_H (100)
#define MAX_W (100)
#define SIZE_BUF (30)
#define NUM_ALPHA (26)

void pick_center(int *cnts, int n) {
  for (int i = 0; i < n; i++) {
    if (cnts[i] % 2 == 1) {
      cnts[i]--;
      return;
    }
  }
  for (int i = 0; i < n; i++) {
    if (cnts[i] > 0) {
      cnts[i]--;
      return;
    }
  }
}

void pick_center_line(int *cnts, int n, int num) {
  int t = num;
  if (t > 0) {
    for (int i = 0; i < n; i++) {
      if (cnts[i] % 4 == 2) {
        cnts[i] -= 2;
        t -= 2;
        if (t == 0) {
          return;
        }
      }
    }
  }
  if (t > 0) {
    for (int i = 0; i < n; i++) {
      if (i < n) {
        if (cnts[i] >= t) {
          cnts[i] -= t;
          t = 0;
        } else {
          t -= cnts[i];
          cnts[i] = 0;
        }
        if (t == 0) {
          return;
        }
      }
    }
  }
}

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  int H, W;
  char ass[MAX_H * MAX_W], buf[SIZE_BUF];
  scanf("%d %d", &H, &W);
  fgets(buf, SIZE_BUF, stdin);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      scanf("%c", &ass[j + i * W]);
    }
    fgets(buf, SIZE_BUF, stdin);
  }

  // count each letter
  int cnts[NUM_ALPHA] = {};
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cnts[ass[j + i * W] - 'a']++;
    }
  }

  // try composing a palindrome matrix
  int possible = 1;
  // pick the element in the middle if there is one
  if (H % 2 == 1 && W % 2 == 1) {
    pick_center(cnts, NUM_ALPHA);
  }
  // check that all the counts are even at this point
  for (int i = 0; i < NUM_ALPHA; i++) {
    if (cnts[i] % 2 != 0) {
      possible = 0;
      break;
    }
  }

  // try picking characters in the middle of each row
  // (not including the character in the middle of the matrix)
  if (H % 2 == 1) {
    pick_center_line(cnts, NUM_ALPHA, (W / 2) * 2);
  }
  if (W % 2 == 1) {
    pick_center_line(cnts, NUM_ALPHA, (H / 2) * 2);
  }
  // check that all counts are divisible by 4 at this point
  // check that all the counts are even at this point
  for (int i = 0; i < NUM_ALPHA; i++) {
    if (cnts[i] % 4 != 0) {
      possible = 0;
      break;
    }
  }
  if (possible) {
    printf("Yes\n");
  } else {
    printf("No\n");
  }

  return 0;
}

