int main() {
	int n = nxt(), m = nxt();
	vector<int> cnt(26);
	for (int i = 0; i < n; ++i) {
		string s;
		cin >> s;
		for (char c : s) {
			cnt[c - 'a'] += 1;
		}
	}

	int quad = 0, dbl = 0, sngl = 0;
	for (int x : cnt) {
		quad += x / 4;
		dbl += x % 4 / 2;
		sngl += x % 2;
	}

	int need_quad = (n / 2) * (m / 2);
	int need_sgnl = (n % 2) * (m % 2);
	int need_dbl = (n * m - need_sgnl - 4 * need_quad) / 2;

	if (need_quad > quad) {
		puts("No");
		return 0;
	}
	quad -= need_quad;
	dbl += quad * 2;
	if (need_dbl > dbl) {
		puts("No");
		return 0;
	}
	puts("Yes");

	return 0;
