string s[200];
int ok[26],rea[26];
vector<int> odd;
int n,m;
int main()
{
	cin>>n>>m;
	for(int i=0;i<n;i++){
		cin>>s[i];
		for(int j=0;j<m;j++){
			ok[s[i][j]-'a']++;
		}
	}
	int cnt=0;
	for(int i=0;i<26;i++){
		if(ok[i]%4==0){
			rea[i]=ok[i];
		}
	}
	for(int i=0;i<26;i++){
		if(ok[i]%2==1){
			odd.push_back(ok[i]);
			cnt++;
		}
	}
	if(cnt>1){
		cout<<"No";
		return 0;
	}
	else{
		if(cnt==1){
			int w=n*m;
			w-=odd[0];
			int p;
			if((int)sqrt(odd[0])%2){
				p=sqrt(odd[0]);
			}
			else{
				p=sqrt(odd[0]-1);
			}
			int a,b;
			for(int i=p;i>=1;i-=2){
				if(odd[0]%i==0){
					a=i,b=odd[0]/i;
					break;
				}
			}
			w-=(min(n,m)-min(a,b)-1)*max(n,m);
			w-=(max(n,m)-max(a,n)-1)*min(n,m);
			for(int i=0;i<26;i++){
				w-=rea[i];
			}
			if(w>0){
				cout<<"No";
				return 0;
			}
			else{
				cout<<"Yes";
				return 0;
			}
		}
		else{
			int w=n*m;
			cout<<"Yes";
			return 0;
		}
	}
    return 0;
}

