void solve() {
  int n, m;
  cin >> n >> m;
  map<char, int> mp;
  rep(i, n) rep(j, m) {
    char c;
    cin >> c;
    mp[c]++;
  }
  int cnt = 0;
  for (auto e : mp) {
    if (e.S >= 4) {
      cnt += e.S / 4;
      mp[e.F] -= e.S / 4 * 4;
    }
  }
  if (cnt < (n / 2) * (m / 2)) {
    cout << "No" << endl;
    return;
  }
  if (n % 2 == 0 && m % 2 == 0) {
    cout << "Yes" << endl;
    return;
  }

  cnt = 0;
  for (auto e : mp) if (e.S % 2 == 0) cnt += e.S / 2;
  if (n % 2 && m % 2 == 0) {
    if (cnt == m / 2) cout << "Yes" << endl;
    else cout << "No" << endl;
  } else if (n % 2 == 0 && m % 2) {
    if (cnt == n / 2) cout << "Yes" << endl;
    else cout << "No" << endl;
  } else {
    if (cnt == (n / 2) + (m / 2)) cout << "Yes" << endl;
    else cout << "No" << endl;
  }
}

