#include <iostream>
#include <algorithm>

using namespace std;

int main(int argc, char const *argv[]) {
	int H,W;
	std::cin >> H >> W;
	char sub;
	int count = 26;
	// 英小文字のそれぞれの個数をカウントする
	int lst[count];
	// 初期化
	for (size_t i = 0; i < count; i++) {
		lst[i] = 0;
	}
	for (size_t i = 0; i < H; i++) {
		for (size_t j = 0; j < W; j++) {
			std::cin >> sub;
			lst[sub - 'a'] += 1;
		}
	}
	// 全ての英小文字に対してmod4をとる
	for (size_t i = 0; i < count; i++) {
		lst[i] %= 4;
	}

	// mod4を取り、1,2,3になる文字の数を取得
	int one,two,three;
	one = two = three = 0;
	for (size_t i = 0; i < count; i++) {
		if (lst[i] == 1) {
			one++;
		}
		if (lst[i] == 2) {
			two++;
		}
		if (lst[i] == 3) {
			three++;
		}
	}


	bool flag = false;

	// 偶数列 * 偶数列ならば、全ての文字は4で割り切れなければならない
	if (H % 2 == 0 && W % 2 == 0) {
		if (one == 0 && two == 0 && three == 0) {
			flag = true;
		}
	}
	// 奇数列 * 奇数列
	else if (H % 2 == 1 && W % 2 == 1) {
		// mod4で1になる文字が1つ、2になるのは縦/2+横/2の数以下ならば良い
		if (one == 1 && three == 0 && two <= (H/2 + W/2)) {
			flag = true;
		}
		// mod4で3になる文字が1つ、2になるのは縦/2+横/2-1以下ならば良い
		if (one == 0 && three == 1 && two <= (H/2 + W/2 - 1)) {
			flag = true;
		}
	}
	// 偶数列 * 奇数列
	else {
		int temp;
		if (H % 2 == 1) {
			temp = W;
		}
		else if (W % 2 == 1) {
			temp = H;
		}
		int syo,amari;
		syo = temp / 4;
		amari = temp % 4;
		if (one == 0 && three == 0){
			if (amari == 0) {
				if (two % 2 == 0 && two <= syo * 2) {
					flag = true;
				}
			}
			else {
				if (two % 2 == 1 && (two - amari/2) <= syo * 2) {
					flag = true;
				}
			}
		}
	}

	if (flag) {
		std::cout << "Yes" << '\n';
	}
	else {
		std::cout << "No" << '\n';
	}
	return 0;
}

