const int MAXN = 30;
int vis[MAXN];
string s;

int main(void){
    int n, m;
    cin >>  n >> m;
    for(int i = 0; i < n; i++){
        cin >> s;
        for(int j = 0; j < m; j++){
            vis[s[j] - 'a']++;
        }
    }
    if(m == 1 && n == 1){
        cout << "Yes" << endl;
        return 0;
    }
    if(n == 1 || m == 1){
        int cnt = 0;
        for(int i = 0; i < 26; i++){
            if(vis[i] == 1) cnt++;
        }
        if(cnt > 1) cout << "No" << endl;
        else cout << "Yes" << endl;
        return 0;
    }
    if(n % 2 == 0 && m % 2 == 0){
        for(int i = 0; i < 26; i++){
            if(vis[i] % 4 == 0) continue;
            else{
                cout << "No" << endl;
                return 0;
            }
        }

    }else if(n & 1 && m % 2 == 0){
        int cnt = 0;
        for(int i = 0; i < 26; i++){
            if(vis[i] & 1){
                cout << "No" << endl;
                return 0;
            }else if(vis[i] % 4 == 0) continue;
            else cnt += vis[i] % 4;
        }
        if(cnt > m){
            cout << "No" << endl;
            return 0;
        }
    }else if(m & 1 && n % 2 == 0){
        int cnt = 0;
        for(int i = 0; i < 26; i++){
            if(vis[i] & 1){
                cout << "No" << endl;
                return 0;
            }else if(vis[i] % 4 == 0) continue;
            else cnt += vis[i] % 4;
        }
        if(cnt > n){
            cout << "No" << endl;
            return 0;
        }
    }else{
        int cnt = 0, gg = 0;
        for(int i = 0; i < 26; i++){
            if(vis[i] % 4 == 0) continue;
            else if((vis[i] % 4) & 1) cnt++, gg += vis[i] % 4;
            else gg += vis[i] % 4;
        }
        if(cnt > 1 || gg > n + m - 1){
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
    return 0;
}

