  }

  // count each letter
  int cnts[NUM_ALPHA] = {};
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cnts[ass[j + i * W] - 'a']++;
    }
  }

  // try composing a palindrome matrix
  int possible = 1;
  // pick the element in the middle if there is one
  if (H % 2 == 1 && W % 2 == 1) {
    int t = 1;
    for (int i = 0; i < NUM_ALPHA; i++) {
      if (cnts[i] % 2 == 1) {
        cnts[i]--;
        t--;
      }
    }
    if (t > 0) {
      for (int i = 0; i < NUM_ALPHA; i++) {
        if (cnts[i] > 0) {
          cnts[i]--;
          t--;
        }
      }
    }
  }
  // check that all the counts are even at this point
  for (int i = 0; i < NUM_ALPHA; i++) {
    if (cnts[i] % 2 != 0) {
      possible = 0;
      break;
    }
  }

  // try picking characters in the middle of each row
  // (not including the character in the middle of the matrix)
  if (H % 2 == 1) {
    const int num = (W / 2) * 2;
    int t = num;
    for (int i = 0; i < NUM_ALPHA; i++) {
      while (cnts[i] % 4 != 2) {
        i++;
      }
      if (cnts[i] % 4 == 2) {
        cnts[i] -= 2;
        t -= 2;
      }
    }
    if (t > 0) {
      for (int i = 0; i < NUM_ALPHA; i++) {
        while (cnts[i] <= 0) {
          i++;
        }
        if (cnts[i] >= t) {
          cnts[i] -= t;
          t = 0;
        } else {
          t -= cnts[i];
          cnts[i] = 0;
        }
        if (t == 0) {
          break;
        }
      }
    }
  }
  if (W % 2 == 1) {
    const int num = (H / 2) * 2;
    int t = num;
    for (int i = 0; i < NUM_ALPHA; i++) {
      while (cnts[i] % 4 != 2) {
        i++;
      }
      if (cnts[i] % 4 == 2) {
        cnts[i] -= 2;
        t -= 2;
      }
    }
    if (t > 0) {
      for (int i = 0; i < NUM_ALPHA; i++) {
        while (cnts[i] <= 0) {
          i++;
        }
        if (cnts[i] >= t) {
          cnts[i] -= t;
          t = 0;
        } else {
          t -= cnts[i];
          cnts[i] = 0;
        }
        if (t == 0) {
          break;
        }
      }
    }
  }
  // check that all counts are divisible by 4 at this point
  // check that all the counts are even at this point
  for (int i = 0; i < NUM_ALPHA; i++) {
    if (cnts[i] % 4 != 0) {
      possible = 0;
      break;
    }
  }
  if (possible) {
    printf("Yes\n");
  } else {
    printf("No\n");
  }

  return 0;
}

