	if( h % 2 == 0 && w % 2 == 0 ){
		a = h*w/4;
	} else if( h % 2 == 0 && w % 2 == 1 ){
		a = (w-1)*h/4;
		b = h/2;
	} else if( h % 2 == 1 && w % 2 == 0 ){
		a = (h-1)*w/4;
		b = w/2;
	} else if( h % 2 == 1 && w % 2 == 1 ){
		a = (h-1)*(w-1)/4;
		b = (h+w-1)/2;
		c = 1;
	}
	for( int i = 0; i < a; ++i ) valid.push_back(4);
	for( int i = 0; i < b; ++i ) valid.push_back(2);
	for( int i = 0; i < c; ++i ) valid.push_back(1);	

	vector<int> candy;
	for( auto paar : mp ){
		int gs = paar.second;
		if( gs % 2 == 1 ){
			candy.push_back(1);
			gs -= 1;
		}
		if( gs % 4 == 2 ){
			candy.push_back(2);
			gs -= 2;
		}
		for( int i = 0; i < gs/4; ++i ) candy.push_back(4);
