	b = lower_bound( valid.begin(), valid.end(), 5 ) - lower_bound( valid.begin(), valid.end(), 4 );
	c = lower_bound( candy.begin(), candy.end(), 4 ) - lower_bound( candy.begin(), candy.end(), 2 );
	int bound = d = lower_bound( candy.begin(), candy.end(), 5 ) - lower_bound( candy.begin(), candy.end(), 4 );
	if( a == c && b == d ) return yes();
