class UnionFind {
private:
	Vec< int > data;
	int num_of_g;

public:
	UnionFind(int n) : data(n, -1), num_of_g(n) {}

	bool unionSet(int x, int y) {
		x = root(x); y = root(y);

		if (x == y) return 0;

		if (data[y] < data[x]) swap(x, y);
		data[x] += data[y]; data[y] = x;
		--num_of_g;

		return 1;
	}

	bool sameSet(int x, int y) { return root(x) == root(y); }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
	int getNumOfG() { return num_of_g; }
};

int H, W;
string a[111];

int getID(int x, int y) { return y * W + x; }

void yes() { puts("Yes"); exit(0); }
void no() { puts("No"); exit(0); }

void solve() {
	UnionFind uf(H * W);
	for_(y,0,H) for_(x,0,W) {
		if (x < W-x-1) uf.unionSet(getID(x, y), getID(W-x-1, y));
		if (y < H-y-1) uf.unionSet(getID(x, y), getID(x, H-y-1));
	}

	map< int, int > grp;
	for_(y,0,H) for_(x,0,W) grp[uf.root(getID(x,y))]++;

	Vec< int > nums;
	for (auto p : grp) {
		nums.push_back(p.second);
		//cerr << p.first << " " << p.second << endl;
	}
	sort(allof(nums), greater< int >());

	map< char, int > crp;
	for_(y,0,H) for_(x,0,W) crp[a[y][x]]++;

	priority_queue< int > que;
	for (auto p : crp) que.push(p.second);

	for (int x : nums) {
		if (que.top() < x) no();
		int v = que.top(); que.pop();
		if (v-x > 0) que.push(v-x);
	}

	if (que.empty()) yes();
	no();
}

int main() {
	cin >> H >> W;
	for_(y,0,H) cin >> a[y];
	solve();
}
