namespace {
    int H, W;
    vector<string> F;
    void input() {
        cin >> H >> W;
        F.resize(H);
        for (auto& L : F) cin >> L;
    }

    void solve() {
        vector<int> count(26, 0);
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int c = F[i][j] - 'a';
                count[c]++;
            }
        }
        auto f = [&]() {
            if (H % 2 == 0 && W % 2 == 0) {
                for (auto c : count) {
                    if (c % 4 != 0) return false;
                }
                return true;
            } else if (H % 2 == 0 && W % 2 == 1) {
                auto x = 0;
                for (auto c : count) {
                    if (c % 2 == 1) return false;
                    x += (c % 4);
                }
                return x <= H;
            } else if (H % 2 == 1 && W % 2 == 0) {
                auto x = 0;
                for (auto c : count) {
                    if (c % 2 == 1) return false;
                    x += (c % 4);
                }
                return x <= W;
            } else {
                assert(H % 2 == 1 && W % 2 == 1);
                auto x = 0;
                bool flag = false;
                for (auto c : count) {
                    if (c % 2 == 1) {
                        if (flag) return false;
                        flag = true;
                    }
                    x += (c % 4);
                }
                return x <= H + W - 1;
            }
        };
        cout << (f() ? "Yes" : "No") << endl;
    }
}

