using namespace std;

bool is_palindrome(const vector<char>& str)
{
    for (int d = 0; d < str.size() / 2; ++d) {
      if (str[d] != str[str.size() - d - 1]) return false;
    }
    return true;
}

bool test(const vector<vector<char>>& matrix)
{
  size_t size0 = matrix.size();
  size_t size1 = matrix[0].size();
  vector<int> next(size1, -1);
  size_t first_i0 = -1;
  for (int i0 = 0; i0 < size0; ++i0) {
    vector<int> count(26, 0);
    for (int i1 = 0; i1 < size1; ++i1) {
      ++count[matrix[i0][i1] - 'a'];
    }
    int odd = 0, even = 0;
    for (size_t i = 0; i < count.size(); ++i) {
      if (count[i] % 2 == 0) ++even;
      else ++odd;
    }
    if ((size1 % 2 == 0 and odd > 0) or (size1 % 2 == 1 and odd != 1)) return false;
    if (first_i0 == -1 and !is_palindrome(matrix[i0])) {
      first_i0 = i0;
      vector<char> new_row(size1, '\0');
      size_t d = 0;
      for (int i = 0; i < count.size(); ++i) {
        if (count[i] == 0) continue;
        if (count[i] % 2 == 1) {
          new_row[size1 / 2] = 'a' + i;
          --count[i];
        }
        for (int c = 0; c < count[i]; c += 2) {
          new_row[d] = new_row[size1 - d - 1] = 'a' + i;
          ++d;
        }
      }
      vector<bool> used(size1, false);
      for (int o = 0; o < size1; ++o) {
        for (int n = 0; n < size1; ++n) {
          if (used[n] == false and new_row[n] == matrix[i0][o]) {
            next[o] = n;
            used[n] = true;
            break;
          }
        }
      }
    }
  }

  if (first_i0 == -1) return true;

  for (size_t i0 = 0; i0 < size0; ++i0) {
    if (i0 == first_i0) continue;
    vector<char> new_row(size1, '\0');
    for (size_t r = 0; r < next.size(); ++r) new_row[next[r]] = matrix[i0][r];
    if (!is_palindrome(new_row)) return false;
  }

  return true;
}

vector<vector<char>> transpose(const vector<vector<char>>& matrix)
{
  size_t size0 = matrix.size();
  size_t size1 = matrix[0].size();
  vector<vector<char>> new_matrix(size1, vector<char>(size0, '\0'));
  for (size_t i0 = 0; i0 < size0; ++i0) {
    for (size_t i1 = 0; i1 < size1; ++i1) {
      new_matrix[i1][i0] = matrix[i0][i1];
    }
  }
  return new_matrix;
}

int main()
{
  int H, W;
  cin >> H >> W;
  vector<vector<char>> matrix(H, vector<char>(W, '\0'));
  for (int h = 0; h < H; ++h) {
    for (int w = 0; w < W; ++w) {
      cin >> matrix[h][w];
    }
  }

  cout << ((test(matrix) and test(transpose(matrix))) ? "Yes" : "No") << endl;
  return 0;
}

