using pi = pair<int,int>;

const string ok = "Yes", ng = "No";

string solve()
{
    int h,w;
    cin >>h >>w;

    int ct[26]={};
    rep(i,h)
    {
        string s;
        cin >>s;
        rep(j,w) ++ct[s[j]-'a'];
    }

    vector<vector<bool>> done(h,vector<bool>(w));

    priority_queue<int> pq;
    int odd = 0;
    rep(i,26)
    {
        if(ct[i]>0)
        {
            if(ct[i]%2==1)
            {
                --ct[i];
                ++odd;
            }
            if(ct[i]>0) pq.push(ct[i]);
        }
    }

    if(h%2==1 && w%2==1)
    {
        if(odd!=1) return ng;
        done[h/2][w/2]=true;
    }
    else
    {
        if(odd>0) return ng;
    }

    rep(i,h)rep(j,w)if(!done[i][j])
    {
        set<pi> s;
        s.insert(pi(i,j));
        s.insert(pi(i,w-1-j));
        s.insert(pi(h-1-i,w-1-j));
        s.insert(pi(h-1-i,j));

        int val = pq.top();
        pq.pop();
        if(val<s.size()) return ng;

        val -= s.size();
        if(val>0) pq.push(val);

        for(const auto &p:s) done[p.fi][p.se]=true;
    }

    return ok;
}

