void solve(ll H, ll W, vector<string> a) {
  vector<int> cnt(26);
  for (string &s: a) {
    for (char c: s) cnt[c - 'a']++;
  }
  int four = (H / 2) * (W / 2);
  int two = (H / 2) * (W % 2) + (H % 2) * (W / 2);
