bool solve(){

  map<char,int> memo;
  rep(i,H){
    rep(j,W){
      memo[S[i][j]]++;
    }
  }

  map<int,int> memo2;
  FOR(it,memo){
    int num = it->second;
    while(num-4 >= 0){
      memo2[4]++;
      num -= 4;
    }
    while(num-2 >= 0){
      memo2[2]++;
      num -= 2;
    }
    if(num > 0) memo2[num]++;
  }

  if(H%2==0 && W%2==0){
    int x = (H/2)*(W/2);
    if(memo2[4] == x) return true;
    return false;
  }
  if(H%2==0 && W%2==1){
    int x = (H/2)*((W-1)/2);
    if(memo2[4] >= x){
      memo2[2] += (memo2[4]-x)/2;
      if(memo2[2] == H/2) return true;
    }
    return false;
  }
  if(H%2==1 && W%2==0){
    int x = ((H-1)/2)*(W/2);
    if(memo2[4] >= x){
      memo2[2] += (memo2[4]-x)/2;
      if(memo2[2] == W/2) return true;
    }
    return false;
