    if(memo2[4] >= x){
      memo2[2] += (memo2[4]-x)/2;
      int y = (H-1)/2 + (W-1)/2;
      if(memo2[2] == y && memo2[1] == 1) return true;
    }
    return false;    
  }

  return false;
}


