bool Judge(int H,int W, map<char,int> &cnt){
	if(H%2 == 0&& W%2 == 0){
		for(auto p:cnt) if(p.second%4) return false;
		return true;
	}
	else if(H%2 == 0 || W%2 == 0){
		if(H%2) swap(H,W);
		int m = 0;
		for(auto p:cnt){
			if(p.second%2) return false;
			if(p.second%4) ++m;
		}
		if(m > H/2) return false;
		return true;
	}
	else{
		int m1 = 0, m2 = 0;
		for(auto p:cnt){
			if(p.second%2) m1++;
			if(m1>1) return false;
			int k = (p.second/2)*2;
			if(k%4) m2++;
		}
		if(m2 > H/2 + W/2) return false;
		return true;
	}
}

