    int tw = 0;
    int fw = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 ) {
	if( vec[i] % 2 == 0 ) {
	  ++tw;
	} else {
	  return false;
	}
      } else ++fw;
    }
    int rem = ( h & 1 ) ? w : h;
    while( rem - tw > 0 ) {
      --fw;
      tw += 2;
    }
    if( fw < 0 ) return false;
    return rem == tw;
  } else {
    int on = 0;
    int tw = 0;
    int fr = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 == 0 ) {
	++fr;
      } else if( vec[i] % 2 == 0 ) {
	++tw;
      } else {
	++on;
      }
    }
    if( on != 1 ) return false;
    if( tw > 4 ) return false;
    if( tw < 4 ) {
      while( 4 - tw > 0 ) {
	--fr;
	if( fr < 0 ) return false;
	tw += 2;
      }
    }
    return tw == 4;
  }
  return true;
}

