const int SIGMA = 26;
const int MAXN = 100;

int seen[SIGMA];
char s[1 + MAXN], answer[1 + MAXN][1 + MAXN];

bool TwoLines(int l1, int l2, int m) {
    int c1 = 1, c2 = m, letter = 0;
    while (c1 < c2) {
        while (letter < SIGMA && seen[letter] < 4)
            letter++;
        if (letter == SIGMA)
            return false;
        seen[letter] -= 4;
        c1++;
        c2--;
    }
    letter = 0;
    if (c1 == c2) {
        while (letter < SIGMA && seen[letter] < 2)
            letter++;
        if (letter == SIGMA)
            return false;
        seen[letter] -= 2;
    }
    return true;
}

bool OneLine(int l, int m) {
    int c1 = 1, c2 = m, letter = 0;
    while (c1 < c2) {
        while (letter < SIGMA && seen[letter] < 2)
            letter++;
        if (letter == SIGMA)
            return false;
        seen[letter] -= 2;
        c1++;
        c2--;
    }
    letter = 0;
    if (c1 == c2) {
        while (letter < SIGMA && seen[letter] < 1)
            letter++;
        if (letter == SIGMA)
            return false;
        seen[letter] -= 1;
    }
    return true;
}

bool Check(int n, int m) {
    int l1 = 1, l2 = n;
    while (l1 < l2) {
        if (!TwoLines(l1, l2, m))
            return false;
        l1++;
        l2--;
    }
    if (l1 == l2)
        if (!OneLine(l1, m))
            return false;
    return true;
}

