int main(){
    int H,W,sum,four,two,one;
    cin >> H >> W;
    sum = H*W;
    if(H%2==0 && W%2==0){
        four = sum;
        two=0;
        one=0;
    }else if(H%2==1 && W%2==1){
        four = (H-1)*(W-1);
        two = sum-four-1;
        one = 1;
    }else if(H%2==1){
        four = (H-1)*W;
        two = sum-four;
        one = 0;
    }else{
        four = H*(W-1);
        two = sum-four;
        one = 0;
    }

    vector<string> a(H);
    map<char,int> mp;
    for(int i=0;i<H;i++){
        cin >> a[i];
