            mp[a[i][j]]++;
        }
    }

    for(int i=0;i<26;i++){
        if(one==0){
            break;
        }

        if(mp[alphas[i]]%4==1 || mp[alphas[i]]%4==3){
            sum -= 1;
            mp[alphas[i]]--;
            one--;
        }
    }

    for(int i=0;i<26;i++){
        if(two==0){
            break;
        }
        if(mp[alphas[i]]%4==2){
            sum -= 2;
            mp[alphas[i]]-=2;
            two-=2;
        }
    }

    for(int i=0;i<26;i++){
