	{
		slots.PB( 4 );
	}
 	REP( ( H % 2 ) * W / 2 + ( W % 2 ) * H / 2 )
	{
		slots.PB( 2 );
	}
	REP( ( H % 2 ) * ( W % 2 ) )
	{
		slots.PB( 1 );
	}

	priority_queue< int > que;
	{
		VI counts( 26 );
		for_each( ALL( A ), [&]( const auto &row ){
				for_each( ALL( row ), [&]( const char c ){ ++counts[ c - 'a' ]; } );
				} );
		FOR( c, counts )
		{
			que.push( c );
		}
	}

	FOR( s, slots )
	{
		const int c = que.top();
		que.pop();

		if ( c < s )
		{
			cout << "No" << endl;
			return 0;
		}

		que.push( c - s );
	}
	cout << "Yes" << endl;

	return 0;
