		bool fail = 0;
		memset(cnt,0,sizeof(cnt));
		for(register int i=1;i<=n;++i) {
			scanf("%s",mp[i]);
			for(register int j=0;j<m;++j)
			cnt[mp[i][j] - 'a'] ++;
		}
