			int l1 = (n + 1)/2 - 1, l2 = (m + 1)/2 - 1;
			int c1 = l1 + l2,lim = l1 * l2; bool fl = 0;
			for(register int i=0;i<26;++i) {
				if (!cnt[i]) continue;
				int h  = cnt[i] / 4;
				int Y = cnt[i] % 4;
				if (h > lim) {
					h -= lim;
					lim = 0;
					Y += h * 4;
				} else lim -= h;
				if (Y & 1) {
					if (fl) {
						fail = 1;
						break;
					}
					Y --; fl = 1;
				}
				Y /= 2;
				if (c1 >= Y) c1 -= Y;
				else {
					fail = 1;
					break;
				}
			}
		}
		else if ((m&1)||(n&1)) {
			int lim,c = (m&1) ? n : m;
