#include <bits/stdc++.h>
using namespace std;
typedef int64_t ll;
typedef vector<string> vss;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll h, w;
        in >> h >> w;
        vss a(h);
        ll count[26] = {};
        for (int i = 0; i < h; i++) {
            in >> a[i];
            for (int j = 0; j < w; j++) {
                count[a[i][j] - 'a']++;
            }
        }
        ll g1 = 1;
        ll g2 = h / 2 + w / 2;
        ll g4 = (h / 2) * (w / 2);
        while (g1-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (count[i] % 4 == 1 || count[i] % 4 == 3) {
                    count[i]--;
                    break;
                }
            }
        }
        sort(count, count + 26);
        while (g2-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (count[i] % 4 == 2) {
                    count[i] -= 2;
                    break;
                }
            }
        }
        while (g4-- > 0) {
            for (int i = 0; i < 26; ++i) {
                if (count[i] % 4 == 0) {
                    count[i] -= 4;
                    break;
                }
            }
        }
        ll sum = 0;
        for (int i = 0; i < 26; ++i) {
            sum += count[i];
        }
        out << (sum == 0 ? "Yes" : "No") << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
