    i64 H, W; cin >> H >> W;
    vector<i64> dist(26, 0);
    REP(i, H) REP(j, W) {
        char a; cin >> a;
        dist[a - 'a']++;
    }

    auto solve = [&]() -> bool {
        i64 N = H * W;
        i64 n4 = 0, n2 = 0, n1 = 0;
        REP(i, 26) {
            n4 += dist[i] / 4;
            dist[i] = dist[i] % 4;
            n2 += dist[i] / 2;
            dist[i] = dist[i] % 2;
            n1 += dist[i];
        }
        if (H % 2 == 0 && W % 2 == 0) {
            if (N / 4 == n4) return true;
            else return false;
        } else if (H % 2 == 1 && W % 2 == 1) {
            if (n1 > 1) return false;
            i64 rem = N - H - W + 1;
            if (rem / 4 > n4) return false;
            n2 += (n4 - rem / 4) * 2;
            rem = H + W - 1;
            if (rem / 2 == n2) return true;
            else return false;
        } else {
            if (H % 2 == 1) swap(H, W);
            i64 rem = N - H;
            if (rem / 4 > n4) return false;
            n2 += (n4 - rem / 4) * 2;
            rem = H;
            if (rem / 2 == n2) return true;
            else return false;
        }
        return false;
    };

