bool ok1() {
    for (int i = 0; i < 26; ++i) {
        if (!mp[i])
            continue;
        if (mp[i] % 4 != 0)
            return 0;
    }
    return 1;
}

bool ok2() {
    int four = a * b - (a + b - 1);
    four /= 4;
    int i;
    for (i = 0; i < 26; ++i) {
        int t = min(mp[i] / 4, four);
        mp[i] -= t * 4;
        four -= t;
    }
    if (four)
        return 0;
    int two = a / 2 + b / 2;
    for (i = 0; i < 26; ++i) {
        int t = min(mp[i] / 2, two);
        mp[i] -= t * 2;
        two -= t;
    }
    if (two)
        return 0;
    for (i = 0; i < 26; ++i) {
        if (mp[i])
            return 1;
    }
    return 0;
}

bool ok3() {
    int even = a % 2 == 0 ? a : b;
    int four = a * b - even;
    four /= 4;
    int i;
    for (i = 0; i < 26; ++i) {
        int t = min(mp[i] / 4, four);
        mp[i] -= t * 4;
        four -= t;
    }
    if (four)
        return 0;
    int two = even / 2;
    for (i = 0; i < 26; ++i) {
        int t = min(mp[i] / 2, two);
        mp[i] -= t * 2;
        two -= t;
    }
    return !two;
}

