    }

    map<char, int> cnt;
    set<char> se;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (cnt.count(S[i][j])) cnt[S[i][j]]++;
            else cnt[S[i][j]] = 1;
            se.insert(S[i][j]);
        }
    }

    bool ans = true;
    int com1 = (H/2) + (W/2);
    int com2 = (H/2) * (W/2);
    int f, g, h;
    if (H % 2 == 1 && W % 2 == 1) {
        f = 1; g = com1, h = com2;
    } else if (H % 2 == 0 && W % 2 == 0) {
        f = 0; g = 0; h = com2;
    } else {
        f = 0; g = com1; h = com2;
    }

    for (int com = 0; com < f; com++) {
        bool none = true;
        for (auto c : se) {
            if (cnt[c] % 4 == 1 || cnt[c] % 4 == 3) {
                cnt[c]--;
                none = false;
                break;
            }
        }
        if (none) break;
    }

    for (int com = 0; com < g; com++) {
        bool none = true;
        for (auto c : se) {
            if (cnt[c] % 4 == 2) {
                cnt[c] -= 2;
                none = false;
                break;
            }
        }
        if (none) break;
    }


    for (int com = 0; com < h; com++) {
        bool none = true;
        for (auto c : se) {
            if (cnt[c] == 0) continue;
            if (cnt[c] % 4 == 0) {
                cnt[c] -= 4;
                none = false;
                break;
            }
        }
        if (com < h && none) ans = false;
        if (none) break;
    }

    for (auto c : se) {
        if (cnt[c] != 0) ans = false;
    }
    //for (auto c : se) cout << c << " : " << cnt[c] << endl;
    cout << ((ans) ? "Yes" : "No") << endl;
    return 0;
}

