    set<char> se;
    for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
        if (cnt.count(S[i][j])) cnt[S[i][j]]++;
        else cnt[S[i][j]] = 1;
        se.insert(S[i][j]);
    }

    bool ans = true;
    int com1 = (H/2) + (W/2), com2 = (H/2) * (W/2);
    int f, g, h;
    if (H % 2 == 1 && W % 2 == 1) {
        f = 1; g = com1, h = com2;
    } else if (H % 2 == 0 && W % 2 == 0) {
        f = 0; g = 0; h = com2;
    } else {
        f = 0; h = com2;
        if (H % 2 == 0) g = H/2;
        else g = W/2;
    }

    int cou = 0;
    while (cou < f) {
        bool a = true;
        for (auto c : se) {
            if (cnt[c]%4 == 1 || cnt[c]%4 == 3) {
                cnt[c]--;
                cou++;
                a = false;
                break;
            }
        }
        if (a) break;
    }
    f -= cou;
    cou = 0;

    while (cou < g) {
        bool a = true;
        for (auto c : se) {
            if (cnt[c]%4 == 2) {
                cnt[c] -= 2;
                cou++;
                a = false;
                break;
            }
        }
        if (a) break;
    }
    g -= cou;
    cou = 0;

    while (cou < h) {
        bool a = true;
