    if (m[2] > (H - 1) / 2 + (W - 1) / 2) return "No";
    return "Yes";
  }

  if (W % 2) swap(H, W);

  int m[4] = {0};
  fore(p, alp) m[p.second% 4]++;
  if (m[1] || m[3]) return "No";
  if (m[2] > W / 2) return "No";
  return "Yes";
}

