bool oo(int mod[], int x, int y) {
  if(mod[1] == 0 && mod[3] == 1) {
      mod[2]++;
  } else if(!(mod[1] == 1 && mod[3] == 0)) {
    return false;
  }
  return mod[2] <= x + y - 2;
