  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      ++mp[a[i][j] - 'a'];
    }
  }

  if (h == 1 || w == 1) {
    int odd = 0;
    for (auto x : mp) {
      if (x.second & 1) {
        ++odd;
      }
    }
    if (odd > 1) {
      cout << "No" << endl;
      return 0;
    } else {
      cout << "Yes" << endl;
      return 0;
    }
  }

  //
  // どっちも奇数
  // 奇数は必ず 1 つ
  // 奇数 - 1 を含めて、
  // 4 の倍数 + 2 は奇数 / 2 + 奇数 / 2 個まで
  // 他は 4 の倍数
  //
  // 96369
  // 85258
  // 74147
  // 85258
  // 96369
  //
  // どっちも偶数
  // 全部 4 の倍数
  //
  // 943349
  // 852258
  // 761167
  // 761167
  // 852258
  // 943349
  //
  //
  // 偶数と奇数
  // 全部 4 の倍数か、4 の倍数 + 2 が 偶数 / 2 個までとあとは 4 の倍数
  //
  // 943349
  // 852258
  // 761167
  // 852258
  // 943349
  //

  if (h % 2 == 0 && w % 2 == 0) {
    for (auto x : mp) {
      if (x.second % 4 != 0) {
        cout << "No" << endl;
        return 0;
      }
    }
    cout << "Yes" << endl;
    return 0;
  } else if (h & 1 && w & 1) {
    int cnt_odd = 0;
    int odd;
    for (auto x : mp) {
      if (x.second & 1) {
        odd = x.second;
        ++cnt_odd;
      } 
    }
    if (cnt_odd != 1) {
      cout << "No" << endl;
      return 0;
    }
    int lim = h / 2 + w / 2;
    int num = 0;
    for (auto x : mp) {
      if (x.second == odd) {
        --odd;
        if (odd % 4 == 2) {
          ++num;
        }
      }
      if (x.second % 4 == 2) {
        ++num;
      } else if (x.second % 4 != 0) {
        cout << "No" << endl;
        return 0;
      }
    }
    if (num <= lim) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  } else {
    int lim;
    if (h % 2 == 0) lim = h / 2;
    else lim = w / 2;
    int num = 0;
    for (auto x : mp) {
      if (x.second % 4 == 2) {
        ++num;
      } else if (x.second % 4 != 0) {
        cout << "No" << endl;
        return 0;
      }
    }
    if (num <= lim) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }


  return 0;
}

