				return false;
		}
	}
	else if(n % 2 && m % 2){
		int mod2(0),mod1(0);
		for(int i(0);i<26;++i){
			if(a[i] % 4 == 2) ++mod2;
			else if(a[i] % 4 == 1) ++mod1;
			else if(a[i] % 4 == 3) ++mod1,++mod2;
		}
		if(mod1 == 1 && mod2 <= (n / 2 + m / 2))
			return true;
		else 
			return false;
	}
	else{
		if(n % 2) swap(n,m);
		int mod2(0),mod13(0);
		for(int i(0);i<26;++i){
			if(a[i] % 4 == 2) ++mod2;
			else if(a[i] % 4 != 0) ++mod13;
		}
		if(mod13 == 0 && mod2 <= n / 2) 
			return true;
		return false;
	}
}
