    if(h <= 1 || w <= 1) return 0;
    int ret = 1;
    ret += (w - 2) / 2;
    ret += (h - 2) / 2;
    return ret + Func4(h - 2, w - 2);
}

int Func2(int h, int w){
    if(h <= 0 || w <= 0) return 0;
    if(h == 1 && w == 1) return 0;
    if(h == 1) return w / 2;
    if(w == 1) return h / 2;
    int ret = 0;
    ret += w % 2;
    ret += h % 2;
    return ret + Func2(h - 2, w - 2);
}

