			return false;
		}
		return true;
	} else {
		int needdouble = h/2;
		for(int i = 'a'; i<= 'z'; i++) {
			while(counts[i] >= 2 && needdouble > 0) {
				needdouble--;
				counts[i]-=2;
			}
		}
		if(needdouble > 0) {
			return false;
		}
		return true;
	}
}

