struct UnionFind {
    UnionFind() : m_parents(0), m_rank(0) {}
    UnionFind(size_t N) : m_parents(N), m_rank(N) {
        for (auto i = 0; i < N; i++) {
            m_parents[i] = i;
            m_rank[i] = 0;
        }
    }

    void merge(size_t t1, size_t t2) {
        auto p1 = this->parent(t1);
        auto p2 = this->parent(t2);

        if (p1 == p2) {
            return ;
        }

        if (this->m_rank[p1] < this->m_rank[p2]) {
            this->m_parents[p1] = p2;
        } else {
            this->m_parents[p2] = p1;
            if (this->m_rank[p1] == this->m_rank[p2]) {
                this->m_rank[p1] += 1;
            }
        }
    }
    bool is_same(size_t t1, size_t t2) const {
        return this->parent(t1) == this->parent(t2);
    }

    size_t parent(size_t t) const {
        auto p = this->m_parents[t];
        if (p == t) {
            return t;
        } else {
            auto p2 = this->parent(p);
            this->m_parents[t] = p2;
            return p2;
        }
    }
private:
    mutable vector<size_t> m_parents;
    vector<u64> m_rank;

};

int body(int &argc, char **argv) {
    using namespace debug;
    auto H = read<i32>();
    auto W = read<i32>();
    auto as = V<string>(H);
    REP (i, H) {
        as[i] = read<string>();
    }

    UnionFind set(H * W);
    V<size_t> os(26, 0);
    REP (i, H) {
        REP (j, W) {
            auto a = as[i][j] - 'a';
            os[a] += 1;

            // (i, j) -> i * W + j
            auto id = i * W + j;
            auto s1 = (H - i - 1) * W + j;
            auto s2 = i * W + (W - j - 1);
            set.merge(id, s1);
            set.merge(id, s2);
        }
    }

    V<i32> ns(H * W, 0);
    REP (i, H) {
        REP (j, W) {
            auto id = i * W + j;
            auto p = set.parent(id);
            ns[p] += 1;
        }
    }

    sort(CTR(ns), greater<size_t>());
    sort(CTR(os));

    FORE (n, ns) {
        // n文字同じ文字が必要
        auto use = -1;
        REP (i, 26) {
            if (os[i] >= n) {
                use = i;
                break;
            }
        }
        if (use < 0) {
            cout << "No" << endl;
            return 0;
        }

        os[use] -= n;
        sort(CTR(os));
    }
    cout << "Yes" << endl;


    return 0;
}

