const int kN = 100 + 5;
int a[kN][kN];
int cnt[26];

bool solve(int w2, int w4)
{
    std::vector<int> x(cnt, cnt + 26);
    for (int i = 0; i < 26; ++ i) {
        int tmp = std::min(cnt[i] / 4, w4);
        w4 -= tmp;
        cnt[i] -= tmp * 4;
    }
    for (int i = 0; i < 26; ++ i) {
        int tmp = std::min(cnt[i] / 2, w2);
        w2 -= tmp;
        cnt[i] -= tmp * 2;
    }
    return !w2 && !w4;
}

