        num_place -= 2;
        if (num_place == 0) {
          break;
        }
      }
    }

    if (num_place > 0) {
      for (int k = 0; k < 26; k++) {
        const int num_use = min(ns[k], num_place);
        ns[k] -= num_use;
        num_place -= num_use;
        if (num_place == 0) {
          break;
        }
      }
    }
  }
  for (int k = 0; k < 26; k++) {
    printf("%d ", ns[k]);
  }
  printf("\n");

  // place the rest of the letters
  int is_possible = 1, num_place = ((H / 2) * 2) * ((W / 2) * 2);
