int n, m, s[26];
int sum[100];
bool used[110][110];

int pop(int x, int y) {
	int ans = 0;
	if (!used[x][y])
		ans = 1;
	used[x][y] = true;
	return ans;
}

int main() {
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++) {
			char k;
			for (k = getchar(); k <= 32; k = getchar());
			s[k - 'a'] += 1;
		}
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			if (!used[i][j]) {
				int ss = 0;
				ss += pop(i, j);
				ss += pop(n - i + 1, j);
				ss += pop(i, m - j + 1);
				ss += pop(n - i + 1, m - j + 1);
				sum[ss] += 1;
			}
	for (int i = 4; i >= 1; i--)
		for (int j = 1; j <= sum[i]; j++) {
			bool find = false;
			for (int k = 0; k < 26; k++)
				if (s[k] >= i) {
					s[k] -= i;
					find = true;
					break;
				}
			if (!find) {
				printf("No\n");
				return 0;
			}
		}
	printf("Yes\n");
}

