            count[c]++;
        }
    }
    if (h % 2 == 0 && w % 2 == 0) {  //両方偶数
        for (auto itr = count.begin(); itr != count.end(); itr++) {
            auto now = *itr;
            if (now.second % 4 != 0) {
                no();
                return 0;
            }
        }
    } else if ((h + w) % 2 == 1) {  //片っぽ奇数
        // h:奇数と思いたい
        if (h % 2 == 0) swap(h, w);
