            auto now = (*itr).second;
            if (now % 2 != 0) {
                no();
                return 0;
            } else if (now % 4 != 0) {
                a++;
            }
        }
        if (a > w / 2) {
            no();
            return 0;
        }
    } else {  //両方奇数
        // a:4n+2,b:奇数
        int a = 0, b = 0;
        for (auto itr = count.begin(); itr != count.end(); itr++) {
            auto now = (*itr).second;
            if (now % 2 != 0) {
                b++;
            } else if (now % 4 != 0) {
                a++;
            }
        }
        if (a > h / 2 + w / 2 || b != 1) {
            no();
            return 0;
        }
    }
    cout << "Yes" << endl;
    return 0;
