bool solve() {
    int h, w;
    cin >> h >> w;
    map<char, int> m;
    priority_queue<pair<int, char>> q;
    rep(i, h) {
        string s;
        cin >> s;
        rep(j, w) {
            m[s[j]]++;
        }
    }
    for (auto e: m) {
        q.emplace(e.second, e.first);
    }

    int fours = (h / 2) * (w / 2);
    int twos = (h % 2) * (w / 2) + (w % 2) * (h / 2);
    int ones = h % 2 && w % 2 ? 1 : 0;
    cerr << fours << " " << twos << " " << ones << endl;
    cerr << h * w << " " << fours * 4 + twos * 2 + ones << endl;

    while (fours) {
        auto e = q.top();
        q.pop();
        if (e.first < 4) return false;
        q.emplace(e.first - 4, e.second);
        fours--;
    }
    while (twos) {
        auto e = q.top();
        q.pop();
        if (e.first < 2) return false;
        q.emplace(e.first - 2, e.second);
        twos--;
    }
    return true;
}

