const int ALPHABETE = 26;

int possible(int H, int W, vector<int>n)
{
    int c4 = (H / 2) * (W / 2); // 4個必要な文字
    int c2 = (H % 2) * (W / 2) + (W % 2) * (H / 2); // 2個必要な文字
    int c1 = (H % 2) * (W % 2); // 1個だけ必要な文字
    int i, use;

    for(i = 0; i < ALPHABETE; i++) {
        if(n[i] >= 4 && c4 >= 1) {
            use = min(c4, n[i] / 4);
            c4 -= use;
            n[i] -= 4 * use;
        }
        if(n[i] >= 2 && c2 >= 1) {
            use = min(c2, n[i] / 2);
            c2 -= use;
            n[i] -= 2 * use;
        }
        if(n[i] >= 1 && c1 >= 1) {
            use = min(c1, n[i]);
            c1 -= use;
            n[i] -= 1 * use;
        }
    }
    if(c4 == 0 && c2 == 0 && c1 == 0) {
        return true;
    } else {
        return false;
    }
}

int main()
{
    int H, W;
    int i, j, k;
    cin >> H >> W;
    vector<int> n = vector<int>(ALPHABETE, 0);
    string s;
    char c;

    for(i = 0; i < H; ++i) {
        cin >> s;
        for(j = 0; j < W; ++j) {
            c = s[j];
            n[c - 'a']++;
        }
    }

    if(possible(H, W, n)) {
        cout << "Yes";
    } else {
        cout << "No";
    }

    return 0;
}

