int dp[256];
int par[10005];
int sz[10005];
int find(int x) {
  return par[x] == x ? x : (par[x] = find(par[x]));
}
void merge(int x, int y) {
  x = find(x);
  y = find(y);
  if(x == y) return;
  sz[y] += sz[x];
  par[x] = y;
}
void solve() {
  int r,c;
  cin >> r >> c;
  for(int i = 0; i < r*c; i++) {
    par[i] = i;
    sz[i] = 1;
  }
  for(int i = 0; i < r; i++) {
    string s;
    cin >> s;
    for(int j = 0; j < c; j++) {
      merge(i*c+j, i*c+(c-1-j));
      merge(i*c+j, (r-1-i)*c+j);
      dp[s[j]]++;
    }
  }
  set<int> seen;
  bool bad = false;
  for(int want = 4; !bad && want >= 1; want--) {
    for(int i = 0; !bad && i < r*c; i++) {
      if(seen.count(find(i)) || sz[find(i)] != want) continue;
      seen.insert(find(i));
      bool found = false;
      for(int a = 0; a < 256; a++) {
        if(dp[a] >= sz[find(i)]) {
          dp[a] -= sz[find(i)];
          found = true;
          break;
        }
      }
      bad = !found;
    }
  }
  if(bad) {
    cout << "No\n";
  }
  else {
    cout << "Yes\n";
  }
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << " ";
    solve();
  }
}

