bool reduce(vint &v, int n, int unit) {
  // cout << "## " << n << ' ' << unit << endl;
  REP(i,v.size()) {
    int cnt = min(n, v[i] / unit);
    n -= cnt;
    v[i] -= cnt * unit;
  }
  return n == 0;
}

