		co[i] -= chop * 4;
		needQuads -= chop;
		chop = min(needPairs, co[i] / 2);
		co[i] -= chop * 2;
		needPairs -= chop * 2;
	}
	if (needPairs || needQuads || needSingle) {
		cout << "No";
	}
	else {
		cout << "Yes";
	}
	return 0;
no:
	cout << "No";
}

