std::string a[112];
int cou[112];
std::string field[112];

int main()
{
	in >> H >> W;
	rep(i, H)
	{
		in >> a[i];
		field[i].resize(W + 1);
	}

	rep(i, H)
	{
		for (auto c : a[i]) { ++cou[c - 'a']; }
	}
