int change(char ch){return ch-'a';}
int main(){
	scanf("%d%d",&n,&m);
	int one=(n>>1)*(m>>1),two=(n&1)*(m>>1)+(m&1)*(n>>1),three=m&n&1;
	for (int i=1;i<=n;i++){
		scanf("%s",str+1);
		for (int j=1;j<=m;j++) num[change(str[j])]++;
	}
	bool flag=true;
	for (int i=0;i<ABC;i++){
		while (num[i]>=4&&one){
			num[i]-=4;
			one--;
		}
		while (num[i]>=2&&two){
			num[i]-=2;
			two--;
		}
		while (num[i]&&three){
			num[i]--;
			three--;
		}
		if (num[i]){
			flag=false;
			break;
		}
	}
	if (flag) printf("Yes");
	else printf("No");
	return 0;
