bool calc1(){ // H＊W%4==0
  for (auto it=Ump.begin(); it !=Ump.end(); ++it){
    int cnt = it->second;
    if (cnt%4==0) continue;
    else return false;
  }
  return true;
}

bool calc2(int cnt_2){ // H＊W%4!=0 && H＊W%2==0

  for (auto it=Ump.begin(); it !=Ump.end(); ++it){
    int cnt = it->second;
    if (cnt%4==0) continue;
    if (cnt%2==1) return false;
    cnt_2--;
    if (cnt_2 < 0) return false;
  }
  return true;
}

bool calc3(int cnt_2){ // H＊W%2!=0
  int cnt_1 = 1;
  for (auto it=Ump.begin(); it !=Ump.end(); ++it){
    int cnt = it->second;
    if (cnt%4==0) continue;
    if (cnt%2==1) cnt_1--;
    else cnt_2--;
    if (cnt_1 < 0 || cnt_2 < 0) return false;
  }
  return true;
}

