template<typename T> inline T read(void)
{
	T ret=(T)0;
	bool neg=false;
	char c=gc();

	while(!isdig(c))
	{
		neg|=(c=='-');
		c=gc();
	}
	while(isdig(c))
	{
		ret=ret*10+c-'0';
		c=gc();
	}
	ret=neg?-ret:ret;

	return ret;
}

