bool pal(map<char, int> cNum, set<char> cset)
{
    if (cset.size() == 0) return true;
    if (cset.size() == 1 && cNum[*cset.begin()] == 1)
        return true;

    vector<char> cSet;
    for (auto i = cset.begin(); i != cset.end(); ++i)
        cSet.push_back(*i);
    bool okay = false;
    for (auto c : cSet) {
        if (cNum[c] < 2)
            continue;
        else {
            map<char, int> nextNum = cNum;
            nextNum[c] -= 2;
            set<char> nextSet = cset;
            if (nextNum[c] == 0) nextSet.erase(c);
            okay += pal(nextNum, nextSet);
        }
    }
    return okay;
}

bool palind(map<char, int> cNum, set<char> cset, int depth)
{
    if (depth == 0) {
        if (pal(cNum, cset))
            return true;
        else
            return false;
    }
    if (cset.size() == 0)
        return false;
    vector<char> cSet;
    for (auto i = cset.begin(); i != cset.end(); ++i)
        cSet.push_back(*i);
    bool okay = false;
    for (auto c : cSet) {
        if (cNum[c] < 4)
            continue;
        else {
            map<char, int> nextNum = cNum;
            nextNum[c] -= 4;
            set<char> nextSet = cset;
            if (nextNum[c] == 0) nextSet.erase(c);
            okay += palind(nextNum, nextSet, depth-1);
        }
    }
    return okay;
}

