    return 0;
  }

  else if (!ht&&!wt)
  {
    REP(i,26)
    {
      int s = mp[i];
      if (s%4==0)
      {
        a -= s - (s%4);
        mp[i] = s%4;
      }
    }
    while (a>1)
      REP(i,26)
      {
        int s = mp[i];
        if (s!=0&&s%2==0)
        {
          a -= s - (s%2);
          mp[i] = s%2;
          continue;
        }
      }
    int sum = 0;
    REP(i,26) {
      sum += mp[i];
    }
    if (sum==1) cout << "Yes" << endl;
    else cout << "No" << endl;
    return 0;
  }
}

