using namespace std;
int num[30],color[111][111];
int h,w; 
char s[1001];
bool dfs(int x,int y){
	if(x==h+1)return true;
	if(color[x][y]){
		if(y==w)return dfs(x+1,1);
		else return dfs(x,y+1);
	}
	for(int c=1;c<=27;c++)
	if(num[c]){
		int i,j,cnt=1;color[x][y]=c;
		i=h-x+1,j=w-y+1;if(!color[i][j]){cnt++;color[i][j]=c;}
		i=x,j=w-y+1;if(!color[i][j]){cnt++;color[i][j]=c;}
		i=h-x+1,j=y;if(!color[i][j]){cnt++;color[i][j]=c;}
		if(num[c]>=cnt){
			num[c]-=cnt;
			bool could;
			if(y==w) could=dfs(x+1,1);
			else could=dfs(x,y+1);
			if(could)return could;
			num[c]+=cnt;
		}
		color[i][j]=0;
		i=h-x+1,j=w-y+1;color[i][j]=0;
		i=x,j=w-y+1;color[i][j]=0;
		i=h-x+1,j=y;color[i][j]=0;
	}
	return false;
}
int main(){
	scanf("%d%d",&h,&w);
	for(int i=1;i<=h;i++){
		scanf("%s",s);
		for(int j=0;j<w;j++)
		num[s[j]-'a'+1]++;
	}
	if(dfs(1,1))printf("Yes\n");
	else printf("No\n");

	return 0;
}

