		need[4] = (H*(W - 1)) / 4;
		need[2] = H / 2;
	}
	if (H % 2 == 1 && W % 2 == 0) {
		need[4] = ((H - 1)*W) / 4;
		need[2] = W / 2;
	}
	if (H % 2 == 1 && W % 2 == 1) {
		need[1] = 1;
		need[4] = ((H - 1)*(W - 1)) / 4;
		need[2] = ((H - 1) / 2) + ((W - 1) / 2);
	}
	for (int i = 0; i < 30 ; i++) {
		if (al[i]) {
			int m = al[i] / 4;
			if (need[4] >= m) {
				need[4] -= m;
			}
			else {
				m = need[4];
				need[4] = 0;
			}
			al[i] -= m * 4;
			if (al[i]) {
				m = al[i] / 2;
				if (need[2] >= m) {
					need[2] -= m;
				}
				else {
					m = need[2];
					need[2] = 0;
				}
				al[i] -= m * 2;
				if (al[i]) {
					if (need[1] >= al[i]) {
						need[1] -= al[i];
					}
