typedef vector<int8_t> vcc;
typedef vector<vcc> vvcc;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll h, w;
        in >> h >> w;
        vvcc a(h, vcc(w));
        ll alpha[26] = {};
        rep(i, h) {
            rep(j, w) {
                in >> a[i][j];
                alpha[a[i][j] - 'a']++;
            }
        }
        ll g2 = h / 2 + w / 2;
        ll g4 = (h / 2)*(w / 2);
        sort(alpha, alpha + 26, greater<ll>());
        for (int i = 0; i < 26 && alpha[i]; ++i) {
            if (alpha[i] % 4 == 1 || alpha[i] % 4 == 3) {
                alpha[i]--;
                sort(alpha, alpha + 26, greater<ll>());
                break;
            }
        }
        while (!(h == 2 && w == 2) && g2 > 0) {
            ll pre = g2;
            for (int i = 0; i < 26 && alpha[i]; ++i) {
                if (alpha[i] % 4 == 2) {
                    alpha[i] -= 2;
                    sort(alpha, alpha + 26, greater<ll>());
                    g2--;
                    break;
                }
            }
            if (g2 == 0 || pre == g2) {
                break;
            }
        }
        while (g4 > 0) {
            ll pre = g4;
            for (int i = 0; i < 26 && alpha[i]; ++i) {
                if (alpha[i] % 4 == 0) {
                    alpha[i] -= 4;
                    sort(alpha, alpha + 26, greater<ll>());
                    g4--;
                }
                if (g4 == 0) {
                    break;
                }
            }
            if (g4 == 0 || pre == g4) {
                break;
            }
        }
        ll sum = 0;
        for (int i = 0; i < 26; ++i) {
            sum += alpha[i];
        }
        out << (sum == 0 ? "Yes" : "No") << '\n';
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
