void Solve()
{
	ll H, W;
	cin >> H >> W;
	vector<ll> word(26, 0);
	REP(i, H) {
		REP(j, W) {
			char a;
			cin >> a;
			word[a - 'a']++;
		}
	}

	ll bai4 = count_if(ALL(word), [](ll one){ return one != 0 && one % 4 == 0; });
	ll bai2 = count_if(ALL(word), [](ll one){ return one != 0 && one % 4 != 0 && one % 2 == 0; });
	ll odd = count_if(ALL(word), [](ll one){ return IsOdd(one); });

	string ans = "No";
	if (IsEven(H) && IsEven(W)) {
		if (bai2 == 0 && odd == 0) ans = "Yes";
	} else if (IsOdd(H) && IsOdd(W)) {
		ll bai2Num = (H + W - 2) / 2;
		if (bai2 <= bai2Num && odd == 1) ans = "Yes";
	} else {
		ll bai2Num = IsOdd(H) ? W / 2 : H / 2;
		if (bai2 <= bai2Num && odd == 0) ans = "Yes";
	}

	cout << ans << endl;
}

