inline bool deccheck(int &x) {
    --x;
    if (x < 0) {
        cout << "No" << endl;
        return false;
    }
    return true;
}

int main() {
    int H, W;
    cin >> H >> W;

    unordered_map<char, int> cnt;

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            char c;
            cin >> c;

            ++cnt[c - 'A'];
        }
    }

    int fours = 0, twos = 0, ones = 0;

    if (H % 2 == 1 && W % 2 == 1) {
        ones = 1;
    }

    if (H % 2 == 1) {
        twos += W / 2;
    }
    if (W % 2 == 1) {
        twos += H / 2;
    }

    fours = (H * W - 2 * twos - ones) / 4;

    for (const pair<char, int> &c : cnt) {
        while (cnt[c.first] > 0) {
            if (cnt[c.first] >= 4) {
                cnt[c.first] -= 4;
                if (!deccheck(fours)) return 0;
            }
            else if (cnt[c.first] >= 2) {
                cnt[c.first] -= 2;
                if (!deccheck(twos)) return 0;
            }
            else if (cnt[c.first] >= 1) {
                cnt[c.first] -= 1;
                if (!deccheck(ones)) return 0;
            }
        }
    }

    cout << "Yes" << endl;

    return 0;
}

