int v[100][100];
int var[26] = {0};

bool dfs(int ch[26], int n) {
  if(var[n]==0) return true;
  for(int i=0; i<26; i++)
    {
      if(var[n] <= ch[i]) {
	ch[i]-=var[n];
	if(dfs(ch, n+1)) {
	  return true;
	}
	ch[i]+=var[n];
      }
    }
  return false;
}

int main(void) {
  int h, w;
  int ch[26] = {0};
  cin>>h>>w;
  for(int i=0; i<h; i++) {
    for(int j=0; j<w; j++) {
      char c;
      cin>>c;
      ch[c-'a']++;
    }
  }

  int num_var=1;

  for(int i=0; i<h; i++) {
    for(int j=0; j<w; j++) {
      if(v[i][j]==0) {
	var[num_var]++;
	v[i][j]=num_var;
	v[i][w-(j+1)]=num_var;
	v[h-(i+1)][j]=num_var++;
      } else {
	var[v[i][j]]++;
	v[i][w-(j+1)]=v[i][j];
	v[h-(i+1)][j]=v[i][j];
      }
    }
  }

  if(dfs(ch, 1)) cout<<"Yes"<<endl;
  else cout<<"No"<<endl;

  return 0;
}

