bool solve(int h, int w, vs a) {
	vi alphabet(26);
	for (auto row : a) {
		for (auto c : row) {
			alphabet[c - 'a']++;
		}
	}

	if (h % 2 == 0 && w % 2 == 0) {
		for (auto v : alphabet) {
			if (v % 4 != 0) {
				return false;
			}
		}

		return true;
	}

	if ((h & 1) && (w & 1)) {
		vi cnt(4);
		for (auto v : alphabet) {
			if (v == 0) continue;
			cnt[v % 4]++;
		}

		if (cnt[3] || cnt[1] != 1 || cnt[2] > (h - 1) / 2 + (w - 1) / 2) {
			return false;
		}

		return true;
	}


