		swap(h, w);
	}

	vi cnt(4);
	for (auto v : alphabet) {
		if (v == 0) continue;
		cnt[v % 4]++;
	}

	if (cnt[1] || cnt[3] || cnt[2] > w / 2) {
		return false;
	}

	return true;
}

