	while (a.size() < b.size())
	{
		a = '0' + a;
	}

	int rest = 0;
	while (!a.empty())
	{
		rest += int(a[a.size() - 1] - '0') + int(b[b.size() - 1] - '0');
		if (rest >= 10)
		{
			result = char(rest % 10 + '0') + result;
			rest /= 10;
		}
		else
		{
			result = char(rest + '0') + result;
			rest = 0;
		}
		a.erase(a.size() - 1);
		b.erase(b.size() - 1);
	}
