    int cnt[26] = {};

    for (int i : rep(0, H)) {
        for (int j : rep(0, W)) {
            cnt[a[i][j] - 'a']++;
        }
    }

    int q = 0, w = 0, s = 0;
    for (int i : rep(0, 26)) {
        while (cnt[i] >= 4) {
            cnt[i] -= 4;
            q++;
        }

        while (cnt[i] >= 2) {
            cnt[i] -= 2;
            w++;
        }

        while (cnt[i] >= 1) {
            cnt[i] -= 1;
            s++;
        }
    }

