bool check(VI alphabet) {
  if(H % 2 == 0 && W % 2 == 0) { // both even
    REP(i, 26) { if(alphabet[i] % 4 != 0) { return false; } }
  }
  else if(H % 2 == 0 || W % 2 == 0) { // 1 odd & 1 even
    VI center_alphabet(26, 0);
    int center_alphabet_num = 0;
    REP(i, 26) {
      if(alphabet[i] % 4 != 0) {
        center_alphabet[i] +=  alphabet[i] % 4;
        center_alphabet_num += alphabet[i] % 4;
      }
    }
    if(H % 2 == 0 && center_alphabet_num > H) { return false; }
    else if(W % 2 == 0 && center_alphabet_num > W) { return false; }
    REP(i, 26) { if(center_alphabet[i] % 2 != 0) { return false; } }
  }
  else {
    VI center_alphabet(26, 0);
    int center_alphabet_num = 0;
    int odd_alphabet_num = 0;
    REP(i, 26) {
      if(alphabet[i] % 4 != 0) {
