    for(auto& p : mp){
        if(four && p.second >= 4){
            p.second -= 4;
            four--;
        }
    }
    for(auto& p : mp){
        if(two && p.second >= 2){
            p.second -= 2;
            two--;
        }
    }
    for(auto& p : mp){
        if(one && p.second >= 1){
            p.second--;
            one--;
        }
    }

    bool yes = true;
    for(auto& p : mp){
        yes &= (!p.second);
    }
    yes &= (!one & !two & !four);

    if(yes) cout << "Yes" << endl;
    else cout << "No" << endl;
}

