  } else if( f == 1 ) {

    int tw = 0;
    int fw = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      int v = vec[i];
      int tmp = v / 4;
      fw += tmp;
      v -= tmp * 4;
      tmp = v / 2;
      tw += tmp;
      v -= tmp * 2;
      if( v ) return false;
    }
    int rem = ( h & 1 ) ? w : h;
    rem /= 2;
    while( rem - tw > 0 ) {
      --fw;
      tw += 2;
    }
    if( fw < 0 ) return false;
    return rem == tw;
  } else {
    int on = 0;
    int tw = 0;
    int fr = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      int v = vec[i];
      int tmp = v / 4;
      fr += tmp;
      v -= tmp * 4;
      tmp = v / 2;
      tw += tmp;
      v -= tmp * 2;
      on += v;
    }
    if( on != 1 ) return false;
    int rem = ( h - 1 ) / 2 + ( w - 1 ) / 2 - 1;
    int rem4 = (int)( ( h - 1 ) / 2 ) * (int)((w-1)/2);
    if( tw > rem ) return false;
    if( tw < rem ) {
      while( rem - tw > 0 ) {
	--fr;
	if( fr < 0 ) return false;
	tw += 2;
      }
    }
    return tw == rem && fr == rem4;
  }
  return true;
}

