bool canTake(int k, int cnt)
{
	FOR(i, 0, 26)
	{
		if (cnt == 0) break;
		while (CNT[i] >= k)
		{
			if (cnt == 0) break;
			CNT[i] -= k;
			cnt--;
		}
	}

	return cnt == 0;
}

void yes()
{
	cout << "Yes" << endl;
	exit(0);
}

void no()
{
	cout << "No" << endl;
	exit(0);
