	FOR(i, 0, n)
	{
		FOR(j, 0, m) CNT[A[i][j] - 'a']++;
	}

	if (n % 2 == 0 && m % 2 == 0)
	{
		if (canTake(4, n * m / 4)) yes();
		no();
	}

	if (n % 2 != 0 && m % 2 != 0)
	{
		int cnt2 = n / 2 + m / 2;
		int cnt4 = (n * m - cnt2 * 2 - 1) / 4;
		if (!canTake(4, cnt4)) no();
		if (!canTake(2, cnt2)) no();

		yes();
	}

	if (m % 2 != 0) swap(n, m);
	int cnt2 = m / 2;
	int cnt4 = (m * n - cnt2 * 2) / 4;
	//cout << cnt2 << " " << cnt4 << endl;
	if (!canTake(4, cnt4)) no();
	if (!canTake(2, cnt2)) no();
	yes();
}

