bool check(std::map<char, int> m, int h, int w) {
  int cnt2 = 0, cnt1 = 0;
  for (auto itr = m.begin(); itr != m.end(); ++itr) {
    if (itr->second % 4 == 3) {
      ++cnt2;
      ++cnt1;
    } else if (itr->second % 4 == 2)
      ++cnt2;
    else if (itr->second % 4 == 1)
      ++cnt1;
  }
  if (h % 2 == 0 && w % 2 == 0) {
    if (cnt2 == 0 && cnt1 == 0)
      return true;
    else
      return false;
  }
  if (h % 2 == 0 && w % 2 != 0) {
    if (cnt2 <= h/2 && cnt1 == 0)
      return true;
    else
      return false;
  }
  if (h % 2 != 0 && w % 2 ==0) {
    if (cnt2 <= w/2&& cnt1 == 0)
      return true;
    else
      return false;
  }
  else {
    if (cnt2 <= (w-1)/2 + (h-1)/2 && cnt1 == 1)
      return true;
    else
      return false;
  }
}

