bool solve(){
  int h,w;
  cin>>h>>w;
  vector<string> vec(h);
  rep(i,h) cin>>vec[i];

  vector<int> cnt(26,0);
  rep(i,h)rep(j,w) cnt[vec[i][j]-'a']++;

  int a=0,b=0,c=0;
  a = (h/2)*(w/2); //4
  b = (h%2)*(w/2) + (h/2)*(w%2); //2
  c = (h%2)*(w%2); //1

  // a
  rep(i,26) if(a>0 && cnt[i]>=4){
    int x = cnt[i]/4;
    cnt[i] %=4;
    a -= x;
    if(a<0){
      a=0;
      cnt[i] += -a*4;
    }
  }
  if(a>0) return false;

  // b
  rep(i,26) if(b>0 && cnt[i]>=2){
    int x = cnt[i]/2;
    cnt[i] %=2;
    b -= x;
    if(b<0){
      b=0;
      cnt[i] += -b*2;
    }
  }
  if(b>0) return false;

  // c
  rep(i,26) if(c>0 && cnt[i]){
    if(cnt[i]==1){
      c=0;
      cnt[i]=0;
    }
    else return false;
  }

  rep(i,26) if(cnt[i]>0) return false;

  return a==0 && b==0 && c==0;
}

