  }else{
    //n odd m odd
    // 4*[(n-1)*(m-1)/4] 2*[(n-1)/2 +(m-1)/2] 1*1
    int cnt1=0;
    for(int i=0;i<26;++i){
      if(cnt[i]&1)cnt1++;
