bool solve(int h,int w){
    int x4=0,x2=0,x1=0;
    if(h%2&&w%2) x4 = (h-1)*(w-1)/4,x2 = (h+w-2)/2,x1 = 1;
    else if(h%2) x4 = (h-1)*w/4,x2 = w/2;
    else if(w%2) x4 = h*(w-1)/4,x2 = h/2;
    else x4 = h*w/4;

    for(auto ite = mp.begin();ite != mp.end();++ite){
        int x = ite->second;

        if(x/4>=x4) x -= 4*x4,x4 = 0;
        else x4 -= x/4,x %= 4;

        if(x/2>=x2) x -= 2*x2,x2 = 0;
        else x2 -= x/2,x %= 2;

        if(x1 && x==x1) x -= 1,x1 = 0;

        if(x) return false; 
    }
    if(x4||x2||x1) return false;
    else return true;
}

