void solve(){
    int H, W;

    cin >> H >> W;

    rep (i, H) {
        cin >> Mat[i];
    }

    rep(i, H) rep (j, W) {
        cnt[Mat[i][j]]++;
    }

    int isOdd = 0;
    REP(i, 'a', 'z' + 1) {
        if (cnt[i] % 2) {
            isOdd ++;
        }
    }

    if (isOdd > 1) {
        cout << "No" << endl;
        return;
    }

    if (isOdd == 1 && (H % 2 == 0 || W % 2 == 0)) {
        cout << "No" << endl;
        return;
    }

    int mincnt = min(H/2, W/2);
    int is4bai = 0;
    REP(i, 'a', 'z' + 1) {
        is4bai += cnt[i] / 4;
    }

    if (is4bai < mincnt * 3 - ((H%2 || W%2))) {
        cout << "No" <<endl;
        return;
    }

    cout << "Yes" <<endl;
}

