    vector<string> a(h);
    for(int i = 0; i < h; ++i){
        cin >> a[i];
    }
    map<char, int> cnt;
    for(int i = 0; i < h; ++i){
        for(int j = 0; j < w; ++j){
            cnt[a[i][j]]++;
        }
    }

    vector<int> g(3, 0);
    g[2] = (h / 2) * (w / 2);
    if(h % 2 != 0 && w % 2 != 0){
        g[0] = 1;
        g[1] = h / 2 + w / 2;
    }
    else{
        g[1] = (h * w - g[2] * 4) / 2;
    }

    vector<int> mod(3);
    mod[0] = 1;
    mod[1] = 2;
    mod[2] = 4;

    for(int i = 0; i < 3; ++i){
        for(auto it = cnt.begin(); it != cnt.end(); ++it){
            if(g[i] <= 0)   break;
            int temp = it->second;
            if(temp == 0)   continue;

            if(temp % 4 == mod[i] || temp % 4 == 4 - mod[i]){
                if(i == 2){
                    g[i] -= temp / 4;
                    it->second -= 4 * (temp / 4);
                }
                else{
                    it->second -= mod[i];
                    --g[i];
                }
            }
        }
    }

    for(auto it = cnt.begin(); it != cnt.end(); ++it){
        if(it->second != 0){
            cout << "No\n";
            return 0;
        }
    }
    cout << "Yes\n";
