const LLONG MOD = 1000000007;

int main()
{
	int H, W; cin >> H >> W;
	map<char, int> ch2NumMap;
	REP(i, H * W) {
		char ch; cin >> ch; ++ch2NumMap[ch];
	}
	int fourPairNum = (H / 2) * (W / 2);
	int twoPairNum = (H % 2) * (W / 2) + (H / 2) * (W % 2);
	int singleNum = H * W - fourPairNum * 4 - twoPairNum * 2;
	bool isYes = true;
	if (singleNum == 1)
	{
		for (auto &kvp : ch2NumMap)
		{
			if (kvp.second % 2 == 1)
			{
				--singleNum;
				--kvp.second;
			}
		}
	}
	if (singleNum > 0)
	{
		isYes = false;
	}
	for (auto &kvp : ch2NumMap)
	{
		if (fourPairNum == 0) break;
		if (kvp.second >= 4)
		{
			--fourPairNum;
			kvp.second -= 4;
		}
	}
	if (fourPairNum > 0)
	{
		isYes = false;
	}
	for (auto &kvp : ch2NumMap)
	{
		if (twoPairNum == 0) break;
		if (kvp.second >= 2)
		{
			--twoPairNum;
			kvp.second -= 2;
		}
	}
	if (twoPairNum > 0)
	{
		isYes = false;
	}
	cout << (isYes ? "Yes" : "No") << endl;
}

