int a[505][505],tot[105];
int n,m,all1 = 0,all2 = 0,all4 = 0;

void Init(){
	int sum = 0;
	for(int i = 1;i <= n;i++)
		for(int j = 1;j <= m;j++) a[i][j] = 1;
	for(int i = 1;i <= n;i++){
		for(int j = 1;j <= m;j++){
			if(a[i][j] == 0) continue;
			sum = 0;
			if(a[i][j] == 1){
				sum++;
				a[i][j] = 0;
			}
			if(a[i][m - j + 1] == 1){
				sum++;
				a[i][m - j + 1] = 0;
			}
			if(a[n - i + 1][j] == 1){
				sum++;
				a[n - i + 1][j] = 0;
			}
			if(a[n - i + 1][m - j + 1] == 1){
				sum++;
				a[n - i + 1][m - j + 1] = 0;
			}
			if(sum == 1) ++all1;
			if(sum == 2) ++all2;
			if(sum == 4) ++all4;
		}
	}
}

