	scanf("%d %d",&n,&m);
	Init();
	memset(tot,0,sizeof(tot));
	for(int i = 1;i <= n;i++){
		for(int j = 1;j <= m;j++){
			char x;
			scanf(" %c",&x);
			tot[x - '0']++;
		}
	}
	if(all4 > 0){
		for(int i = 'a' - '0';i <= 'z' - '0';i++){
			int sum = tot[i] / 4;
			if(all4 >= sum){
				all4 -= sum;
				tot[i] -= 4 * sum;
			}
			else{
				tot[i] -= 4 * all4;
				all4 = 0;
			}
			if(all4 == 0) break;
		}
		if(all4 != 0){
			printf("No");
			return 0;
		}
	}
	if(all2 > 0){
		for(int i = 'a' - '0';i <= 'z' - '0';i++){
			int sum = tot[i] / 2;
			if(all2 >= sum){
				all2 -= sum;
				tot[i] -= 2 * sum;
			}
			else{
				tot[i] -= 2 * all2;
				all2 = 0;
			}
			if(all2 == 0) break;
		}
		if(all2 != 0){
			printf("No");
			return 0;
		}
	}
	if(all1 > 0){
		for(int i = 'a' - '0';i <= 'z' -'0';i++){
			int sum = tot[i] / 1;
			if(all1 >= sum){
				all1 -= sum;
				tot[i] -= 1 * sum;
			}
