int h, w;
char A[101][101];
int charcount[26];   //count['文字' - 'a'] == aの個数
int main()
{
  cin >> h >> w;
  for(int i=0; i<h; ++i){
    for(int j=0; j<w; ++j){
      char c;
      cin >> c;
      A[i][j] = c;
      charcount[c -'a'] ++;
    }
  }


  // 場合分け even-even, even-odd, odd-odd
  if(h%2==0 && w%2==0){
    //even-even
    //全部4の倍数じゃないとだめ
    for(char c='a'; c<='z'; ++c){
      if(charcount[c-'a'] % 4 != 0){
        goto impossible;
      }
    }

  }else if(h%2==1 && w%2==1){
    //odd-odd
    int pivot = h+w-1;
    int nonpivot = h*w-pivot;
    //4個以上ある文字は、ノンピボットに詰めていく
    for(char c='a'; c<='z'; ++c){
      auto& cc = charcount[c-'a'];
      while(nonpivot >= 4 && cc>=4){
        cc -= 4;
        nonpivot -= 4;
      }
    }
    //ノンピボットが埋まっていなければ無理
    if(nonpivot > 0) goto impossible;
    //残りの文字でピボットを埋めていく
    //2個以上ある文字は、ピボットに詰めていく
    for(char c='a'; c<='z'; ++c){
      auto& cc = charcount[c-'a'];
      while(pivot >= 2 && cc>=2){
        cc -= 2;
        pivot -= 2;
      }
    }
    // pivotが1になっていれば可能、1より大きければ不可能
    if(pivot > 1) goto impossible;

  }else{
    //even-odd
    int pivot = h%2==0 ? h : w;
    int nonpivot = h*w-pivot;
    //4個以上ある文字は、ノンピボットに詰めていく
    for(char c='a'; c<='z'; ++c){
      auto& cc = charcount[c-'a'];
      while(nonpivot >= 4 && cc>=4){
        cc -= 4;
        nonpivot -= 4;
      }
    }
    //ノンピボットが埋まっていなければ無理
    if(nonpivot > 0) goto impossible;
    //残りの文字でピボットを埋めていく
    //2個以上ある文字は、ピボットに詰めていく
    for(char c='a'; c<='z'; ++c){
      auto& cc = charcount[c-'a'];
      while(pivot >= 2 && cc>=2){
        cc -= 2;
        pivot -= 2;
      }
    }
    // pivotが0で可能、0より大きければ不可能
    if(pivot > 0) goto impossible;
  }

  cout << "Yes" << endl;
  return 0;
  impossible:
  cout << "No" << endl;
  return 0;
}

