bool check(int H,int W,vector<int> &alph){
  // H,W がともに偶数のときは4つの塊のみ
  // H,W の片方が偶数のときは4つの塊の他に2つの塊が偶数のやつ/2個存在
  // H,W がともに奇数のときは2つの塊がH/2+W/2個、1つが1個ある
  int not2 = 0;
  int not4 = 0;
  rep(i, alph.size()){
    if (alph[i]%2 != 0) not2++;
    else if (alph[i]%4 != 0) not4++;
  }
  if (H%2 == 0 && W%2 == 0){
    if (not2 > 0) return false;
    if (not4 > 0) return false;
    return true;
