    if (not2 > 0) return false;
    if (H%2==0 && not4 > H/2) return false;
    if (W%2==0 && not4 > W/2) return false;
    return true;
  }else{
    if (not2 > 1) return false;
    if (not4 > H/2+W/2) return false;
    return true;
  }
}

