  int cnt = 0;
  for(auto v : mp) {
    if( v.second % 2 != 0 ) ++cnt;
  }
  if( n % 2 == 0 ) {
    return cnt == 0;
  } else {
    return cnt == 1;
  }
}

bool compute(vector<int> &vec,int h,int w) {
  int f = ( h & 1 ) + ( w & 1 );
  if( f == 0 ) {
    int need = ( h / 2 ) * ( w / 2 );
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 ) return false;
      vec[i] /= 4;
      need -= vec[i];
    }
    return need == 0;
  } else if( f == 1 ) {
    int tw = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 ) {
	if( vec[i] % 2 == 0 ) {
	  ++tw;
	} else {
	  return false;
	}
      }
    }
    int rem = ( h & 1 ) ? w : h;
    if( tw > rem ) return false;
  } else {
    int med = 0;
    int tw = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 ) {
	if( vec[i] % 2 == 0 ) {
	  ++tw;
	  if( tw  > 4 ) return false;
	} else {
	  ++med;
	  if( med > 1 ) return false;
	}
      }
    }
  }
  return true;
}

