bool isKai(const string& s) {
	int N = s.size();
	for (int i = 0; i < N/2; i++) {
		if (s[i] != s[N-1-i]) return false;
	}
	return true;
}

int main() {
	int H, W;
	cin >> H >> W;
	vector<string> board(H);
	for (int i = 0; i < H; i++)
		cin >> board[i];
	vector<vector<int> > hoge(26);
	for (int i = 0; i < W; i++) {
		hoge[board[0][i] - 'a'].push_back(i);
	}
	vector<int> perm(W, -1);
	int oddCnt = 0;
	for (int i = 0; i < 26; i++) {
		if (hoge[i].size()%2) oddCnt++;
	}
	if (oddCnt >= 2) no();
	if (oddCnt > 0 && W%2 == 0) no();
	int left = 0, right = W;
	for (int i = 0; i < 26; i++) {
		int itr = 0;
		if (hoge[i].size() % 2) {
			perm[hoge[i][itr++]] = W/2;
		}
		for (; itr < hoge[i].size(); itr += 2) {
			perm[hoge[i][itr]] = left++;
			perm[hoge[i][itr+1]] = --right;
		}
	}
	for (int i = 0; i < W; i++) 
		assert(perm[i] != -1);
	for (int i = 0; i < W; i++) {
		for (int j = 0; j < W; j++) {
			assert(perm[i] != perm[j]);
		}
	}
	// Debug
	//for (int i = 0; i < W; i++) {
	//	cout << perm[i];
	//}
	//cout << endl;
	map<string, int> mp;
	for (int i = 0; i < H; i++) {
		string next;
		for (int j = 0; j < W; j++) {
			next += " ";
		}
		for (int j = 0; j < W; j++) {
			next[perm[j]] = board[i][j];
		}
		if (!isKai(next)) no();
		mp[next]++;
	}
	oddCnt = 0;
	for (auto p : mp) {
		if (p.second%2) oddCnt++;
	}
	if (oddCnt > 1) no();
	if (oddCnt > 0 && H%2==0) no();
	cout << "Yes" << endl;
	return 0;
}

