    if(h%2 == 0 && w%2 == 0){
        center = 0;
        cross = 0;
    }
    if(h%2 == 0 && w%2 == 1){
        center = 0;
        cross = h;
    }
    if(h%2 == 1 && w%2 == 0){
        center = 0;
        cross = w;
    }
    if(h%2 == 1 && w%2 == 1){
        center = 1;
        cross = h+w-2;
    }

    int other = h*w - center - cross;
    for(int i=0;i<ALPHABET;i++){
        if(count[i]%2 == 0){
            cross -= count[i]%4;
            int toother = (count[i]/4)*4;
            if(other < toother){
                cross -= toother-other;
                other = 0;
            }else{
                other -= toother;
            }
        }else{
            if(h%2 == 0 || w%2 == 0) ans = "No";
            center--;
            cross -= count[i]-1;
        }
        if(center < 0 || cross < 0 || other < 0) ans = "No";
    }

    cout << ans << endl;

    return 0;
}

