		puts("No");
}
void stp_4()    //不相等偶数 
{
	if(f[2]== 1 && f[1] == 0)
		puts("Yes");
	else 
		puts("No");
}
void stp_5(int sum)  //相等偶数 
{
	if(f[4] == sum)
		puts("Yes");
	else 
		puts("No");
}
