    for(int i=0;i<H;i++){
        cin >> a[i];
        for(int j=0;j<W;j++){
            a_count[a[i][j] - 'a']++;
        }
    }

    priority_queue<int> que1;
    for(int i=0;i<26;i++){
        if(a_count[i] > 0){
            que1.push(a_count[i]);
        }
    }

    UnionFind uf(H * W);
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            uf.unite(i * W + j, i * W + (W - 1 - j));
        }
    }
    for(int j=0;j<W;j++){
        for(int i=0;i<H;i++){
            uf.unite(i * W + j, (H - 1 - i) * W + j);
        }
    }

    map<int, int> mp;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            mp[uf.find(i * W + j)]++;
        }
    }

    priority_queue<int> que2;
    for(auto p : mp){
        que2.push(p.second);
    }

    bool ok = true;
    while(que2.size()){
        int need = que2.top();
        que2.pop();
        int cap = que1.top();
        que1.pop();
        if(need > cap){
            ok = false;
            break;
        }
        cap -= need;
        if(cap > 0){
            que1.push(cap);
        }
    }
    assert(!ok || que1.size() == 0);

    if(ok){
        cout << "Yes" << endl;
    }else{
        cout << "No" << endl;
    }

