int cnt[26];

void no()
{
    puts("No");
}

void solve()
{
    int n, m;
    cin >> n >> m;
    forn (i, n)
    {
        string s;
        cin >> s;
        for (char c : s) ++cnt[c - 'a'];
    }
    if ((n & 1) && (m & 1))
    {
        forn (i, 26) if (cnt[i] & 1)
        {
            --cnt[i];
            break;
        }
        forn (i, 26) if (cnt[i] & 1) return no();
        int x = n + m - 2;
        for (int i = 0; i < 26 && x; ++i) if (cnt[i] % 4 == 2)
        {
            x -= 2;
            cnt[i] -= 2;
        }
        forn (i, 26) if (cnt[i] % 4 == 2) return no();
        if (x % 4) return no();
        while (x)
        {
            int _x = x;
            forn (i, 26) if (cnt[i] >= 4)
            {
                cnt[i] -= 4;
                x -= 4;
            }
            if (_x == x) break;
        }
        if (x) return no();
        puts("Yes");
        return;
    }
    if ((n & 1) || (m & 1))
    {
        if (m & 1) swap(n, m);
        int x = m;
        forn (i, 26) if (cnt[i] & 1) return no();
        for (int i = 0; i < 26 && x; ++i) if (cnt[i] % 4 == 2)
        {
            x -= 2;
            cnt[i] -= 2;
        }
        if (x % 4) return no();
        while (x)
        {
            int _x = x;
            forn (i, 26) if (cnt[i] >= 4)
            {
                x -= 4;
                cnt[i] -= 4;
            }
            if (_x == x) break;
        }
        if (x) return no();
    }
    forn (i, 26) if (cnt[i] % 4) return no();
    puts("Yes");
}

