int main(){
  int h,w;
  int odd_count = 0;
  int four_count = 0;
  map <char, int> s;
  cin >> h >> w;
  for (int i=0;i<w;i++) {
    for (int j=0;j<h;j++) {
      char c;
      cin >> c;
      if (s.find(c)==s.end()) {
	s[c] = 1;
      } else {
	s[c]++;
      }
    }
  }
  if (h==1 && w==1) {
    cout << "Yes" << endl;
    return 0;
  }
  for (auto it = s.begin();it != s.end();it++) {
    if (it->second % 4 == 2) {
      four_count++;
    }
    if (it->second % 4 == 3) {
      four_count++;
      odd_count++;
    }
    if (it->second % 4 == 1) {
      odd_count++;
    }
  }
  if (h % 2 == 0 && w % 2 == 0) {
    if (four_count > 0) {
      cout << "No" << endl;
      return 0;
    }
  }  
  if (h % 2 == 0 && w % 2 == 1) {
    if (odd_count > 0) {
      cout << "No" << endl;
      return 0;
    }
    if (four_count > h/2) {
      cout << "No" << endl;
      return 0;
    }
  }  

  if (h%2 == 1 && w%2 == 0) {
    if (odd_count > 0) {
      cout << "No" << endl;
      return 0;
    }
    if (four_count > w/2) {
      cout << "No" << endl;
      return 0;
    }
  }  
  if (h%2 == 1 && w%2 == 1) {
    if (odd_count > 1) {
      cout << "No" << endl;
      return 0;
    }
    if (four_count > ((h+w - 2)/2)) {
      cout << "No" << endl;
      return 0;
    }
  }  
  cout << "Yes" << endl;
}

