void solve(){
  li i,j;cin>>n>>m;
  rep(i,0,n){
    rep(j,0,m){
      cin>>a[i][j];
      cnt[a[i][j]-'a']++;
    }
  }
  sort(cnt,cnt+26);
  reverse(cnt,cnt+26);
  li ans=n*m;
  rep(i,0,26){
    while(cnt[i]>=4){
      if(n%2==1 and m%2==0 and ans==m) break;
      if(n%2==0 and m%2==1 and ans==n) break;
      if(n%2==1 and m%2==1 and ans==n+m-1) break;
