  if(n%2==0 and m%2==1 and ans!=n){
    cout<<"No";
    return ;
  }
  if(n%2==0 and m%2==0 and ans!=0){
    cout<<"No";
    return ;
  }
  if(n%2==1 and m%2==1 and ans!=m+n-1){
    cout<<"No";
    return ;
  }
  rep(i,0,26){
    while(cnt[i]>=2){
      if(n%2==1 and m%2==1 and ans==1) break;
      ans-=2;
      cnt[i]-=2;
