  }
  if(N % 2 == 1 && M % 2 == 0) {
    bool f1 = mp[1] + mp[3] == 0;
    bool f2 = mp[2] + mp[3] <= M;
    bool f3 = (M - mp[2] - mp[3]) % 4 == 0;
    f = f1 && f2 && f3;
  }
  if(N % 2 == 0 && M % 2 == 1) {
    bool f1 = mp[1] + mp[3] == 0;
    bool f2 = mp[2] + mp[3] <= N;
