bool solve(ll g1,ll g2, ll g4) {
  for(auto p:mp) {
    if(g1==0) break;
    if(p.second%2==1) {mp[p.first]-=1;g1--;}
  }
  for(auto p:mp) {
    if(g2==0) break;
    if(p.second%4==2) {mp[p.first]-=2;g2--;} 
  }
  for(auto p:mp) {
