			if (t == 0) break;
			if (need4) {
				if (t < 4) return 0;
				need4--;
				Q.emplace(t - 4);
			}
			else if (need2) {
				if (t < 2) return 0;
				need2--;
				Q.emplace(t - 2);
			}
		}
		return (need4 == 0 && need2 == 0);
	};

	if (h % 2 && w % 2) {
		out("OO");
		out(nc);
		if (sz(nc) != 1) return 0;
		int odd = nc[0];
		C[odd]--;
		int need4 = (h-1)*(w-1)/4;
		int need2 = (h-1)/2 + (w-1)/2;
		return judge(need4, need2);
	}
	else if (h % 2) {
		out("OE");
		if (sz(nc)) return 0;
		int need2 = (w - 2) / 2;
		int need4 = w * (h - 1) / 4;
		return judge(need4, need2);
	}
	else if (w % 2) {
		out("EO");
		if (sz(nc)) return 0;
		int need2 = (h - 2) / 2;
		int need4 = h * (w - 1) / 4;
		return judge(need4, need2);
	}
	else {
		out("EE");
		if (sz(nc)) return 0;
		int need2 = 0;
		int need4 = h*w/4;
		return judge(need4, need2);
	}
	assert(false);
}

