  }

  int g1, g2, g3;
  if (h % 2 == 0 && w % 2 == 0) {
    g1 = 0, g2 = 0, g3 = h * w / 4;
  } else if (h % 2 == 1 && w % 2 == 1) {
    g1 = 2, g2 = (h / 2) + (w / 2), g3 = (h / 2) * (w / 2);
  } else {
    g1 = 0, g2 = w / 2, g3 = w * (h - 1) / 4;
  }


  bool check = true;
  int j = 0;
  rep(i, 26) {
    if (j == g1) break;
    if (num[i] % 4 == 1 || num[i] % 4 == 3) {
      j ++;
      num[i] --;
    }
  }
  if (j != g1) check = false;
  j = 0;
  rep(i, 26) {
    if (j == g2) break;
    if (num[i] % 4 == 2) {
      j ++;
      num[i] -= 2;
    }
  }
  if (j != g2) check = false;
  j = 0;
  rep(i, 26) {
    if (j == g3) break;
    if (num[i] > 0 && num[i] % 4 == 0) {
      j ++;
      num[i] -= 4;
    }
  }
