bool check(string s,int rem) {
  map<char,int> mp;
  int n = s.size();
  rep(i,n) ++mp[s[i]];
  int cnt = 0;
  for(auto v : mp) {
    if( v.second % 2 != 0 ) ++cnt;
  }
  if( n % 2 == 0 ) {
    return cnt == 0;
  } else {
    return cnt == 1;
  }
}

bool compute(vector<int> &vec,int h,int w) {
  int f = ( h & 1 ) + ( w & 1 );
  if( f == 0 ) {
    int need = ( h / 2 ) * ( w / 2 );
    rep(i,(int)vec.size()) if( vec[i] ) {
      if( vec[i] % 4 ) return false;
      vec[i] /= 4;
      need -= vec[i];
    }
    return need == 0;
  } else if( f == 1 ) {

    int tw = 0;
    int fw = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      int v = vec[i];
      int tmp = v / 4;
      fw += tmp;
      v -= tmp * 4;
      tmp = v / 2;
      tw += tmp;
      v -= tmp * 2;
      if( v ) return false;
    }
    int rem = ( h & 1 ) ? w : h;
    while( rem - tw > 0 ) {
      --fw;
      tw += 2;
    }
    if( fw < 0 ) return false;
    return rem == tw;
  } else {
    int on = 0;
    int tw = 0;
    int fr = 0;
    rep(i,(int)vec.size()) if( vec[i] ) {
      int v = vec[i];
      int tmp = v / 4;
      fr += tmp;
      v -= tmp * 4;
      tmp = v / 2;
      tw += tmp;
      v -= tmp * 2;
      on += v;
    }
    if( on != 1 ) return false;
    int rem = ( h - 1 ) / 2 + ( w - 1 ) / 2 - 1;
    if( tw > rem ) return false;
    if( tw < rem ) {
      while( rem - tw > 0 ) {
	--fr;
	if( fr < 0 ) return false;
	tw += 2;
      }
    }
    return tw == rem;
  }
  return true;
}

