        for(int j = 0; j < w; j++) {
            int val = inp[j] - 'a';
            freq[val]++;
        }
    }

    bool ok = true;
    for(int i = 0; i < 26; i++) {
        if(freq[i] > 0) {
            while(cnt[4] > 0 && freq[i] >= 4) { 
