                cnt[2]--;
                freq[i] -= 2;
            }
            while(cnt[1] > 0 && freq[i] >= 1) {
                cnt[1]--;
                freq[i] -= 1;
            }

            if(freq[i] > 0)
                ok = false;
        }
    }

    printf("%s\n", ok ? "Yes" : "No");

