int cnt[30],n,m,nx,ny;
int mps[200][200];
int main()
{
	memset(mps,-1,sizeof mps);
	scanf("%d%d",&n,&m);
	nx=1,ny=1;
	for(int i=1;i<=n;i++)
	{
		char sd[200]; scanf("%s",sd);
		for(int j=0;j<m;j++) 
			cnt[sd[j]-'a']++;
	}
	for(int j=0;j<26;j++)
	{
		if(cnt[j]&1)
		{
			if(n%2==0||m%2==0)
			{
				puts("No\n");
				return 0;
			}
			if(mps[n/2+1][m/2+1]!=-1)
			{
				puts("No\n");
				return 0;
			}
			mps[n/2+1][m/2+1]=j;
			cnt[j]--;
		}
		if(cnt[j]%4==2)
		{
			if(n%2==0&&m%2==0) 
			{
				puts("No\n");
				return 0;
			}
			int fg=0; 
			if(m&1) for(int i=1;!fg&&i<=n/2;i++)
				if(mps[i][m/2+1]==-1) mps[i][m/2+1]=j,mps[n-i+1][m/2+1]=j,fg=1;
			if(n&1) for(int i=1;!fg&&i<=m/2;i++)
				if(mps[n/2+1][i]==-1) mps[n/2+1][i]=j,mps[n/2+1][m-i+1]=j,fg=1;
			if(!fg)
			{
				puts("No\n");
				return 0;
			}
			cnt[j]-=2;
		}
		for(int i=1;i<=cnt[j]/4;i++)
		{
			while(mps[nx][ny]!=-1)
			{
				ny++; if(ny==m/2+1)
				ny=1,nx++;
			}
			mps[nx][ny]=j;
			mps[n-nx+1][ny]=j;
			mps[nx][m-ny+1]=j;
			mps[n-nx+1][m-ny+1]=j;
		}
	}
	puts("Yes\n");
	return 0;
}

