typedef long long ll;
const int maxn = 105;

char str[maxn][maxn];
int cnt[maxn];

int main(){
	int n,m;
	scanf("%d%d",&n,&m);
	for(int i=0;i<n;i++){
		scanf("%s",str[i]);
	}
	memset(cnt,0,sizeof(cnt));
	for(int i=0;i<n;i++)
		for(int j=0;j<m;j++){
			cnt[str[i][j]-'a']++;
	}
	bool flag=true;
	if(n==1||m==1){
		if(n==1&&m==1){
			flag=true;		
		}
		else{
		 if(n>m) swap(n,m);
		 	int left=(m&1)?1:0;
		 	for(int i=0;i<26;i++){
		 		if(cnt[i]&1) left--; 
			 }
			 if(left>=0) flag=true;
			 else flag=true;
		}
	}else{
		if(n%2==0&&m%2==0){
			for(int i=0;i<26;i++){
				if(cnt[i]%4) flag=false;
			}
		}else if(n%2==0||m%2==0){
			if(m&1) swap(n,m);
			int left=m;
			for(int i=0;i<26;i++){
				if(cnt[i]%4==1||cnt[i]%4==3){
					flag=false;
				}else if(cnt[i]%4==2){
					left-=2;
				}
			}
			if(left<0) flag=false;
		}else {
			int left1 = 1;
			int left2 = n+m-1;
			for(int i=0;i<26;i++){
				if(cnt[i]%4==1||cnt[i]%4==3) {
					left1--;
					if(cnt[i]%4==3) left2-=2;
				}else if(cnt[i]%4==2){
					left2-=2;
				}
			}
			if(left1<0) flag=false;
			if(left2<0) flag=false;
		}
	}
	if(flag) printf("Yes\n");
	else printf("No\n");
	return 0;
}

