#include<iostream>
#include<map>

std::map<char, int> mp;

bool ans = true;
void solve(int H, int W){
	if(H <= 0 && W <= 0)return;

	bool check;
	for(int i = 0; i < H; i += 2){
		check = false;

		if(H - i >= 2){
			if(W >= 2){
				for(auto kv : mp){
					if(kv.second >= 4) {
						kv.second -= 4;	
						check = true;
						break;
					}
				}
			}else{
				for(auto kv : mp){
					if(kv.second >= 2) {
						kv.second -= 2;	
						check = true;
						break;
					}
				}
			}
		}else{
			if(W >= 2){
				for(auto kv : mp){
					if(kv.second >= 2) {
						kv.second -= 2;	
						check = true;
						break;
					}
				}
			}else{
				for(auto kv : mp){
					if(kv.second >= 1) {
						kv.second -= 1;	
						check = true;
						break;
					}
				}
			}

		}
		if(!check)ans = false;
	}

	for(int i = 0; i < W; i += 2){
		check = false;

		if(W - i >= 2){
			if(H >= 2){
				for(auto kv : mp){
					if(kv.second >= 4) {
						kv.second -= 4;	
						check = true;
						break;
					}
				}
			}else{
				for(auto kv : mp){
					if(kv.second >= 2) {
						kv.second -= 2;	
						check = true;
						break;
					}
				}
			}
		}else{
			if(H >= 2){
				for(auto kv : mp){
					if(kv.second >= 2) {
						kv.second -= 2;	
						check = true;
						break;
					}
				}
			}else{
				for(auto kv : mp){
					if(kv.second >= 1) {
						kv.second -= 1;	
						check = true;
						break;
					}
				}
			}

		}
		if(!check)ans = false;
	}

	if(H >= 2)H -= 2;
	else H = 0;

	if(W >= 2)W -= 2;
	else W = 0;

	solve(H, W);
}

int main(){
	int H, W;
	std::cin >> H >> W;
	char a;
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			std::cin >> a;
			mp[a]++;
		}
	}

	solve(H, W);

	std::cout << (ans ? "Yes" : "No") << std::endl;

}

