#define _CRT_SECURE_NO_WARNINGS
int N = 0, M = 0;

int main() {

	scanf("%d %d", &N, &M);
	int count[30] = {};
	char c, cc;
	for (int i = 0; i < N; i++) {
		scanf("%c", &cc);
		for (int j = 0; j < M; j++) {
			scanf("%c", &c);
			count[c - 'a']++;
		}
	}
	bool flag = true;
	int center = 0;
	int normal = 0;
	int semi = 0;
	for (int i = 0; i <= 25; i++) {
		if (count[i] != 0) {
			switch (count[i] % 4) {
			case 0:
				break;
			case 1:
				center++;
				break;
			case 2:
				semi++;
				break;
			case 3:
				semi++;
				center++;
				break;
			}

			normal += count[i] / 4;
			if (normal>0) {
				if (N / 2 + M / 2 - 1 < normal) {
					semi += (normal - (N / 2 + M / 2 - 1)) * 2;
				}
			}

			if (N % 2 == 0 && M % 2 == 0) {
				if (semi > 0) {
					flag = false;
					break;
				}
			}
			else if (N % 2 == 0 && M % 2 == 1) {
				if (semi > N / 2) {
					flag = false;
					break;
				}
			}
			else if (N % 2 == 1 && M % 2 == 0) {
				if (semi > M / 2) {
					flag = false;
					break;
				}
			}


			if (N % 2 == 1 && M % 2 == 1) {
				if (center > 1) {
					flag = false;
					break;
				}
				if (semi > N / 2+ M / 2) {
					flag = false;
					break;
				}

			}
			else {
				if (center > 0) {
					flag = false;
					break;
				}
			}
		}
	}

	if (flag) {
		printf("Yes\n");
	}
	else {
		printf("No\n");
	}
	return 0;
}

