      } else if( vec[i] % 2 == 0 ) {
	++tw;
      } else {
	++on;
      }
    }
    if( on > 2 ) return false;
    if( tw > 4 ) return false;
    if( tw < 4 ) {
      while( 4 - tw > 0 ) {
	--fr;
	if( fr < 0 ) return false;
	tw += 2;
      }
    }
    return tw == 4;
  }
  return true;
}

