int H, W;


bool check(const std::map<char, int>& map)
{
  int a;

  if (H % 2 == 0 && W % 2 == 0) {
    a = H * W;
  }
  else if (H % 2 && W % 2) {
    a = H * W - (H + W) + 1;
  }
  else if (H % 2) {
    a = H * W - W;
  }
  else {
    assert(W % 2 && H % 2 == 0);

    a = H * W - H;
  }

  assert(a % 4 == 0);

  std::priority_queue<int> pq;

  for (const auto& kv : map)
    pq.push(kv.second);

  for (int i = 0; i < a / 4; i ++) {
    int x = pq.top(); pq.pop();

    if (x < 4)
      return false;

    x -= 4;

    if (x)
      pq.push(x);
  }

  int ce = 0, co = 0;

  while (! pq.empty()) {
    int x = pq.top(); pq.pop();

    (x % 2 == 0 ? ce : co) ++;
  }

  if (H % 2 == 0 && W % 2 == 0) {
    return co == 0;
  }
  else if (H % 2 && W % 2) {
    return co == 1;
  }
  else {
    return co == 0;
  }
}

