      int x2 = W - 1 - x;
      if (x == x2 and y == y2) {
        counts.push_back(1);
      } else if (x == x2) {
        counts.push_back(2);
      } else if (y == y2) {
        counts.push_back(2);
      } else {
        counts.push_back(4);
      }
    }
  }
  sort(counts.begin(), counts.end());

  for (int i = 0; i < counts.size(); i++) {
