int main(/* int argc, char *argv[] */) {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout << setprecision(20);

  auto solve = [&]() -> bool {
    vector<ll> cnt(26);
    ll H, W; cin >> H >> W;
    for (ll i = 0; i < H; i++) {
      string s; cin >> s;
      for (ll j = 0; j < W; j++) {
	char c = s.at(j) - 'a';
	cnt.at(c)++;
      }
    }
    ll n4 = 0;
    ll n2 = 0;
    ll n1 = 0;
    for (ll i = 0; i < 26; i++) {
      ll res = cnt.at(i) % 4;
      if (res == 0) n4++;
      else if (res == 2) n2++;
      else n1++;
    }
    ll numodd = (H % 2) + (W % 2);
    if (numodd == 0) {
      return (n1 == 0) && (n2 == 0);
    }else if (numodd == 1) {
      if (H % 2 == 1) {
	return (n1 == 0) && (n2 <= W / 2);
      }else {
	return (n1 == 0) && (n2 <= H / 2);
      }
    }else if (numodd == 2) {
      return (n1 <= 1) && (n1 + 2 * n2 <= W + H - 1);
    }else assert(0);
  };

  cout << (solve() ? "Yes\n" : "No\n");

  return 0;
}

