        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
    else if(H%2!=0 && W%2==0){
        // 全部2の倍数
        two -= W/2;
        four -= (H/2)*(W/2);
        if(one!=0 || two!=0 || four!=0) return false;
    }
