const string YES = "Yes";
const string NO = "No";

bool isYes(ll h, ll w, vl &cnts) {
  if (h >= 2 && w >= 2) {
    if (cnts[4] <= 0) {
      return false;
    }
    cnts[4]--;

    ll need = (h + w - 4) * 2;
    if (cnts[2] * 2 + cnts[4] * 4 < need) {
      return false;
    }

    if (cnts[2] * 2 >= need) {
      cnts[2] -= need / 2;
    } else {
      if ((need - cnts[2] * 2) % 4 == 0) {
        cnts[4] -= (need - cnts[2] * 2) / 4;
        cnts[2] = 0;
      } else {
        cnts[4] -= (need - cnts[2] * 2) / 4 + 1;
        cnts[2] = 1;
      }
    }

    return isYes(h - 2, w - 2, cnts);
  } else if (h >= 2 && w == 1) {
    if (cnts[2] <= 0 && cnts[4] <= 0) {
      return false;
    }

    if (cnts[2] == 0) {
      cnts[4]--;
      cnts[2]++;
    } else {
      cnts[2]--;
    }

    return isYes(h - 2, w, cnts);
  } else if (h == 1 && w >= 2) {
    if (cnts[2] <= 0 && cnts[4] <= 0) {
      return false;
    }

    if (cnts[2] == 0) {
      cnts[4]--;
      cnts[2]++;
    } else {
      cnts[2]--;
    }

    return isYes(h, w - 2, cnts);
  }
  return true;
}

int main() {
  ll H, W;
  cin >> H;
  cin >> W;

  map<char, ll> charCnts;
  rep(i, 0, H) {
    string str;
    cin >> str;
    rep(j, 0, W) { charCnts[str[j]]++; }
  }

  vl cnts(5);
  for (auto iter = charCnts.begin(); iter != charCnts.end(); iter++) {
    ll tmp = iter->second;
    cnts[4] += tmp / 4;
    tmp %= 4;

    cnts[2] += tmp / 2;
    tmp %= 2;

    cnts[1] += tmp;
  }

  if (isYes(H, W, cnts)) {
    print(YES);
  } else {
    print(NO);
  }
  return 0;
}

