int H,W;
int alp[26];

void input() {
	cin>>H>>W;
	for(int i=0; i<H; i++)for(int j=0; j<W; j++) {
		char ch; cin>>ch;
		alp[ch-'a']++;
	}
}

void solve() {
	int c4=H/2*(W/2), c2=H%2*W/2+W%2*H/2, c1=H%2*W%2;
	for(int i=0; i<26; i++) {
		if(alp[i]%2) {
			if(c1) {
				alp[i]--;
				c1--;
			}
			else {
				cout<<"No"<<endl;
				return;
			}
		}

		int a4=alp[i]/4;
		alp[i]-=min(a4,c4)*4;
		c4=max(c4-a4,0);

		int a2=alp[i]/2;
		alp[i]-=min(a2,c2)*2;
		c2=max(c2-a2,0);

		if(alp[i]) {
			cout<<"No"<<endl;
			return;
		}
	}

	cout<<"Yes"<<endl;
}

int main() {
	while(1) {
		input();
		solve();
		break;
	}
}

