  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      ++mp[a[i][j] - 'a'];
    }
  }

  if (h == 1 || w == 1) {
    int odd = 0;
    for (auto x : mp) {
      if (x.second & 1) {
