  // 他は 4 の倍数
  //
  // 96369
  // 85258
  // 74147
  // 85258
  // 96369
  //
  // どっちも偶数
  // 全部 4 の倍数
  //
  // 943349
  // 852258
  // 761167
  // 761167
  // 852258
  // 943349
  //
  //
  // 偶数と奇数
  // 全部 4 の倍数か、4 の倍数 + 2 が 偶数 / 2 個までとあとは 4 の倍数
  //
