    return 0;
  } else if (h & 1 && w & 1) {
    int cnt_odd = 0;
    int odd;
    for (auto x : mp) {
      if (x.second & 1) {
        odd = x.second;
        ++cnt_odd;
      } 
    }
    if (cnt_odd != 1) {
      cout << "No" << endl;
      return 0;
    }
    int lim = h % 2 + w % 2;
    int num = 0;
    for (auto x : mp) {
      if (x.second == odd) {
        --odd;
        if (odd % 4 == 2) {
          ++num;
        }
      }
      if (x.second % 4 == 2) {
        ++num;
      } else if (x.second % 4 != 0) {
        cout << "No" << endl;
        return 0;
      }
    }
    if (num <= lim) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  } else {
    int lim;
    if (h % 2 == 0) lim = h / 2;
    else lim = w / 2;
    int num = 0;
    for (auto x : mp) {
      if (x.second % 4 == 2) {
        ++num;
      } else if (x.second % 4 != 0) {
        cout << "No" << endl;
        return 0;
      }
    }
    if (num <= lim) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }


  return 0;
}

