            }
        }
        ll c = 0;
        rep(i, 26){
            if(cnt[i] % 4){
                c++;
            }
        }
        if(c <= w/2 && (w/2 - c) % 2 == 0){
            Pr(1);
        }
        Pr(0);
    }else if(w&1){
