bool setKaiBun(string &s)
{
	map<char,int> aMap;
	int i,j;
	map<char,int>::iterator mit;
	for (i=0;i<s.size();i++){
		mit = aMap.find(s[i]);
		if (mit==aMap.end()){
			aMap[s[i]]=1;
		}else{
			(*mit).second++;
		}
	}
	int odd=0;
	int even=0;
	int oddIndex=0;
	i=0;
	for (mit=aMap.begin();mit!=aMap.end();mit++){
		if ((*mit).second%2==0){
			even++;
		}else{
			odd++;
			oddIndex=i;
		}
		i++;
	}
	if (odd>1){
		return false;
	}
	map<char,int>::reverse_iterator rmit;
	s.clear();
	string oddS;
	if (odd==1){
		i=0;
		for (mit=aMap.begin();mit!=aMap.end();mit++){
			if (i==oddIndex){
				for (j=0;j<(*mit).second;j++){
					oddS+=(*mit).first;
				}
				aMap.erase(mit);
				break;
			}
			i++;
		}

	}
	for (mit=aMap.begin();mit!=aMap.end();mit++){
		for (i=0;i<(*mit).second/2;i++){
			s+=(*mit).first;
		}
	}
	if (odd==1){
		s+=oddS;
	}
	for (rmit=aMap.rbegin();rmit!=aMap.rend();rmit++){
		for (i=0;i<(*rmit).second/2;i++){
			s+=(*rmit).first;
		}
	} 
	return true;
}
