						field[i][W - 1 - j] = c;
						field[H - 1 - i][W - 1 - j] = c;
						break;
					}
				}
				if (!ok)
				{
					out << "No" << std::endl;
					return 0;
				}
			}
		}
	}

	out << "Yes" << std::endl;
	return 0;
}

