            twos -= c ; 
            cnt[i] -= c * 2;
        }
        if ( four != 0 || twos != 0 ){
            return cout << "No" << endl , 0 ; 
        }
    }
    else {
        int four = n * (m - 1) / 4;
        int twos = n / 2 ;
        for(int i = 0; i < 26; i++){
            int c = min(four, cnt[i] / 4);
            four -= c ; 
            cnt[i] -= c * 4 ;
            c = min(twos, cnt[i] / 2);
            twos -= c ; 
            cnt[i] -= c * 2;
        }
        if ( four != 0 || twos != 0 ){
            return cout << "No" << endl , 0 ; 
        }
    }
    cout << "Yes" << endl;
    return 0 ;
}

