    FO (i,0,H) {
        if (i*2 > H-1) continue;
        FO (j,0,W) {
            if (j*2 > W-1) continue;
            int syms = 1;
            if (i*2 != H-1) syms *= 2;
            if (j*2 != W-1) syms *= 2;
            amsyms[syms]++;
        }
