    FO (i,0,26) {
        for (int m = 4; m >= 1; m--) {
            while (am[i] >= m && amsyms[m]) {
                amsyms[m]--;
                am[i] -= m;
            }
        }
    }
    FO (i,1,5) {
        if (amsyms[i]) {
            printf ("No\n");
            return 0;
        }
    }
    printf ("Yes\n");
    return 0;
}

