using vs = vector<string>;
using vi = vector<int>;

int main()
{
    ios_base::sync_with_stdio(0);

    int h, w; cin >> h >> w;

    vs q(h);

    for(int i = 0; i < h; i++) cin >> q[i];

    vi v(26);

    for(int i = 0; i < h; i++)
    for(int j = 0; j < w; j++)
    {
        char c = q[i][j] - 'a';

        v[c]++;
    }

    vi y;

    for(int i = 0; i < h; i++)
    for(int j = 0; j < w; j++)
    {
        int ri = h - 1 - i;
        int rj = w - 1 - j;

        if(ri < i || rj < j) continue;

        int x = 1;

        if(i != ri) x *= 2;
        if(j != rj) x *= 2;

        y.push_back(x);
    }

    sort(begin(y), end(y));

    int ny = y.size();

    for(int i = ny - 1; i >= 0; i--)
    {
        int fl = 0;
        for(int x = y[i]; !fl && x; x /= 2)
        for(int j = 0; !fl && j < 26; j++) if(v[j] % x == 0 && v[j] >= y[i])
        {
            v[j] -= y[i];
            fl = 1;
        }

        if(!fl)
        {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;
    return 0;
}

