  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      vs[uf.find(i * W + j)].emplace_back(i, j);
    }
  }
  vector< pair< int, int > > vq;
  for(int i = 0; i < 10000; i++) {
    if(vs[i].empty()) continue;
    vq.emplace_back(vs[i].size(), i);
  }

  sort(vq.rbegin(), vq.rend());

  for(auto &p : vq) {
