const int maxn = 110;
int vis[maxn][maxn];
int H,W;

bool solve(priority_queue<int>& Q, const int size)
{
    FOR(i,0,H) FOR(j,0,W) if (!vis[i][j]) {
        set<PII> S;
        const int I = H-1-i;
        const int J = W-1-j;
        S.insert(PII(i,j)); S.insert(PII(i,J));
        S.insert(PII(I,j)); S.insert(PII(I,J));
        if (S.size() == size) {
            const int c = Q.top(); Q.pop();
            if (c < size)
                return false;
            const int sz = c-size;
            if (sz)
                Q.push(c-size);
            vis[i][j] = vis[i][J] = vis[I][j] = vis[I][J] = true;
        }
    }
    return true;
}

