typedef long long ll;
const int N = 101;
int R, C;
char g[N][N + 1];
int main()
{
	int f[26] = {};
	scanf("%d%d", &R, &C);
	for (int i = 0; i < R; ++i)
		for (int j = 0; j < C; ++j) {
			scanf(" %c", &g[i][j]);
			++f[g[i][j]-'a'];
		}
	int need[5] = {};
	for (int i = 0; i <= (R-1) / 2; ++i)
		for (int j = 0; j <= (C-1) / 2; ++j) {
			if (R - i - 1 == i) {
				if (C - j - 1 == j)
					++need[1];
				else
					++need[2];
			}
			else {
				if (C - j - 1 == j)
					++need[2];
				else
					++need[4];
			}
		}
	priority_queue<int> q;
	for (int i = 0; i < 26; ++i)
		if (f[i])
			q.push(f[i]);
	while (!q.empty()) {
		int x = q.top();
		q.pop();
		bool ok = false;
		for (int i = 4; i > 0; --i) {
			if (!need[i])
				continue;
			if (need[i] && x < i) {
				puts("No");
				return 0;
			}
			--need[i];
			x -= i;
			if (x)
				q.push(x);
			ok = true;
			break;
		}
		if (!ok) {
			puts("No");
			return 0;
		}
	}
	puts("Yes");
	return 0;
}

