bool solve(int n, int m, vector<int>& cnt) {
	if (n > m) swap(n, m);
	if (n == 1) {
		int idx = m;
		while (idx > 1) {
			int i = max_element(ALL(cnt)) - cnt.begin();
			if (cnt[i] >= 2) cnt[i] -= 2, idx -= 2;
			else return false;
		}
		return true;
	}
	else {
		int idx = n;
		while (idx > 1) {
			int i = max_element(ALL(cnt)) - cnt.begin();
			if (cnt[i] >= 4) cnt[i] -= 4, idx -= 2;
			else return false;
		}
		idx = m - 2;
		while (idx > 1) {
			int i = max_element(ALL(cnt)) - cnt.begin();
			if (cnt[i] >= 4) cnt[i] -= 4, idx -= 2;
			else return false;
		}
		if (n & 1) {
			sort(ALL(cnt));
			bool ok(false);
			REPU(i, 0, 26) if (cnt[i] >= 2) {
				cnt[i] -= 2;
				ok = true; break;
			}
			if (!ok) return false;
		}
		if (m & 1) {
			sort(ALL(cnt));
			bool ok(false);
			REPU(i, 0, 26) if (cnt[i] >= 2) {
				cnt[i] -= 2;
				ok = true; break;
			}
			if (!ok) return false;
		}
		return solve(n - 2, m - 2, cnt);
	}
}

