bool solve(priority_queue<int>& que, int h, int w){
    if ((h==0||w==0)||(h*w)==1) return true;
    else{
        if ((h==1 || w==1)){
            h = max(h,w);
            w = 1;
            int tmp=que.top();
            if (tmp >= 2){
                tmp-=2;
                que.pop();
                que.push(tmp);
                solve(que,h-2,w);
            }else return false;
        }else{
            int tmp = que.top();
            if (tmp >= 4){
                tmp-=4;
                que.pop();
                que.push(tmp);
            }else return false;
            for (int i=0;i<(h-2)/2;++i){
                int tmp = que.top();
                if (tmp >= 4){
                    tmp-=4;
                    que.pop();
                    que.push(tmp);
                }else return false;
            }
            for (int i=0;i<(w-2)/2;++i){
                int tmp = que.top();
                if (tmp >= 4){
                    tmp-=4;
                    que.pop();
                    que.push(tmp);
                }else return false;
            }
            if (h%2 == 1){
                int tmp = que.top();
                if (tmp >= 2){
                    tmp-=2;
                    que.pop();
                    que.push(tmp);
                }else return false;
            }
            if (w%2 == 1){
                int tmp = que.top();
                if (tmp >= 2){
                    tmp-=2;
                    que.pop();
                    que.push(tmp);
                }else return false;
            }
            return solve(que,h-2,w-2);
        }
    }

}

