void solve(void)
{
  int H,W;
  cin>>H>>W;
  map<char,int> mp;
  int COUNT = H*W;
  for (int i = 0; i < H*W; i++)
  {
    char c ;cin>>c;
    mp[c]++;
  }

  int G1 = 1;
  int G2 = H/2 + W/2;
  int G3 = (H/2)*(W/2);
  for (int i = 0; i < G1; i++)
  {
    for (auto &x : mp)
    {
      if((x.second%4)%2 == 1)
      {
        x.second--;
        COUNT --;
        break;
      }
    }

  }

  for (int i = 0; i < G2; i++)
  {
    for (auto &x : mp)
    {
      if((x.second%4) == 2 && x.second > 1)
      {
        x.second -= 2;
        COUNT-=2;
        break;
      }
    }

  }
    for (int i = 0; i < G3; i++)
  {
    for (auto &x : mp)
    {
      if((x.second%4) == 0 && x.second > 3)
      {
        x.second -= 4;
        COUNT -=4;
        break;
      }
    }

  }
  int varify = 1;
  for (auto x : mp)
  {
    if(x.second != 0)varify = 0;
    // DEBUG(x.first,x.second,"\n");
  }
  if(varify)
  {
    cout<<"Yes"<<endl;
  }
  else
  {
    cout<<"No"<<endl;
  }






  return;
}

