            if(snum[i] % 4 == 0) continue;
            else if(snum[i] % 4 == 2) center++;
            else if(snum[i] % 4 == 1) odd++;
            else if(snum[i] % 4 == 3){
                odd++;
                center++;
            }
            if(odd > 1) ok = false;
            if(center > h/2 + w/2 +1) ok = false;
        }
    }
    if(h % 2 == 0 && w % 2 == 0){
        for(int i=0;i<3000;i++){
            if(snum[i] % 4 == 0) continue;
            else if(snum[i] % 4 == 2) center++;
            else ok = false;
            if(center > 1) ok = false;
        }
    }

    //cout<<svar<<endl;
    //for(int i=0;i<10;i++) cout<<snum[i]<<endl;

    if(ok) cout<<"Yes"<<endl;
    else cout<<"No"<<endl;
}

