#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) for (int i = (0); i < (n); ++i)
#define ALL(obj) (obj).begin(), (obj).end()
#define DEBUG(val) cout << #val << " : " << val << endl
#define MOD 1000000007

int main() {
  int h, w;
  map<char, int> mp;
  cin >> h >> w;
  REP(i, h) {
    string s;
    cin >> s;
    for (auto c : s) {
      mp[c]++;
    }
  }
  int g1 = 1;
  int g2 = (h / 2) + (w / 2);
  int g4 = (h / 2) * (w / 2);
  REP(i, g1) {
    for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
      if (itr->second % 4 == 1 || itr->second % 4 == 3) {
        itr->second--;
        break;
      }
    }
  }
  REP(i, g2) {
    for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
      if (itr->second % 4 == 2) {
        itr->second -= 2;
        break;
      }
    }
  }
  priority_queue<pair<int, char>> q;
  for (auto itr : mp) {
    q.push(make_pair(itr.second, itr.first));
  }

  REP(i, g4) {
    pair<int, char> p = q.top();
    q.pop();
    if (p.first % 4 == 0) {
      q.push(make_pair(p.first - 4, p.second));
    } else {
      q.push(p);
    }
  }

  string ans = "Yes";
  while (!q.empty()) {
    pair<int, char> p = q.top();
    q.pop();
    if (p.first != 0) ans = "No";
  }
  cout << ans << endl;
}

