int H, W;
string A[101];

string solve() {
    map<char, int> cnt;
    rep(y, 0, H) rep(x, 0, W) cnt[A[y][x]]++;

    if (H % 2 == 0 && W % 2 == 0) {
        fore(p, cnt) if (p.second % 4) return NO;
        return YES;
    }

    if (H % 2 && W % 2) {
        map<int, int> c;
        fore(p, cnt) c[p.second % 4]++;
        if (c[3]) return NO;
        if (c[1] != 1) return NO;
        if (c[2] > (H - 1) / 2 + (W - 1) / 2) return NO;
        return YES;
    }

    if (W % 2) swap(H, W);

    map<int, int> c;
    fore(p, cnt) c[p.second % 4]++;
    if (c[1] || c[3]) return NO;
    if (c[2] > W / 2) return NO;
    return YES;
}

int main() {
    cin >> H >> W;
    rep(y, 0, H) cin >> A[y];
    cout << solve() << endl;
}

