			if (z < 0) {
				cout << "No";
				return 0;
			}
			que.push(z);
		}
	}
	if (x * y == 1) {
		int z = que.top();
		que.pop();
		z -= 1;
		if (z < 0) {
			cout << "No";
			return 0;
		}
		que.push(z);

	}
	cout << "Yes";
	return 0;
}

