int main(){
    int H,W,sum,four,two,one;
    cin >> H >> W;
    sum = H*W;
    if(H%2==0 && W%2==0){
        four = sum;
        two=0;
        one=0;
    }else if(H%2==1 && W%2==1){
        four = (H-1)*(W-1);
        two = sum-four-1;
        one = 1;
    }else if(H%2==1){
        four = (H-1)*W;
        two = sum-four;
        one = 0;
    }else{
        four = H*(W-1);
        two = sum-four;
        one = 0;
    }

    vector<string> a(H);
    map<char,int> mp;
    for(int i=0;i<H;i++){
        cin >> a[i];
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            mp[a[i][j]]++;
        }
    }

    for(int i=0;i<26 && 0<one;i++){
        if(mp[alphas[i]]%2==1){
            sum -= 1;
            mp[alphas[i]]--;
            one--;
        }
    }

    for(int i=0;i<26 && 0<two;i++){
        if(mp[alphas[i]]%4==2){
            sum -= 2;
            mp[alphas[i]]-=2;
            two-=2;
        }
    }

    for(int i=0;i<26 && 0<four;i++){
        if(mp[alphas[i]]%4==0 && mp[alphas[i]]!=0){
