vector<int> demand;

int main(void)
{
	cin >> H >> W;
	char c;

	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			cin >> c;
			cnt[c - 'a']++;
		}
	}

	for(int i = 0; i < H/2; i++){
		for(int j = 0; j < W/2; j++){
			demand.push_back(4);
		}
	}
	if(H % 2){
		for(int i = 0; i < W/2; i++) demand.push_back(2);
	}
	if(W % 2){
		for(int i = 0; i < H/2; i++) demand.push_back(2);
	}
	if(H * W % 2){
		demand.push_back(1);
	}

	bool flag;
	bool ans;

	for(int i = 0; i < (int)demand.size(); i++){
		flag = false;
		for(int j = 0; j < 26; j++){
			if(cnt[j] <= 0) continue;
			if(cnt[j] >= demand[i]){
				cnt[j] -= demand[i];
				flag = true;
				break;
			}
		}
		if(!flag){
			ans = false;
			goto end;
		}
	}
	ans = true;

	end:
	if(ans) cout << "Yes" << endl;
	else cout << "No" << endl;

	return 0;
}

