int r, c, cnt[30];
char arr[1002][1002];
int sz[10002], par[10002];

int root(int v){
	if(par[v] == v)	return v;
	return par[v] = root(par[v]);
}

void unite(int a, int b){
	a = root(a), b = root(b);
	if(a == b)	return;
	if(sz[a] < sz[b])	swap(a, b);
	sz[a] += sz[b];
	par[b] = a;
}


int get_index(int i, int j){
	return i*c+j;
}

int main(){

