			scanf("%c",&space);
			zf[space-'a']++;
			if(zf[space-'a']>=4)
			{
				zf[space-'a']-=4;
				pp[4]++;
			}
		}
		scanf("%c",&space);
	}
	for(int i=0;i<26;i++)
	{
		if(zf[i]%2==1)
		{
			zf[i]--;
			pp[1]++;
		}
		if(zf[i]==2)
			pp[2]++;
	}
