	{
		if(pp[4]>=n/2*m/2)
			printf("Yes");
		else
			printf("No");
	}
	if(flag==1)
	{
		if(pp[4]>=(n/2)*(m/2)&&pp[1]==0)
			printf("Yes"); 
		else
			printf("No");
	}
	if(flag==2)
	{
		if(pp[1]==1 && pp[4]>=(n/2)*(m/2))
			printf("Yes");
		else
			printf("No");
	}
	printf("\n");
	return 0;
}

