int c[300];
int n, m;
int one, two;
int done2;
int main()
{
	scanf("%d%d", &n, &m);
	if (n % 2 && m % 2) one++;
	if (n%2) two+=m-one;
	if (m%2) two+=n-one;
	two/=2;
//	printf("%d %d\n", one, two);
	for (int i = 0; i < n; i++)
	{
		for (int j = 0; j < m; j++)
		{
			char a;
			scanf(" %c", &a);
			c[a]++;
		}
	}
	for (int i = 0; i < two; i++)
	{
		bool done = false;
		for (int j = 'a'; j <= 'z'; j++)
		{
			if (c[j] % 4 == 2)
			{
				c[j]-=2;
				done = true;
				break;
			}
		}
		if (done) done2++;
	}
	if (one)
	{
		for (int j = 'a'; j <= 'z'; j++)
		{
			if (c[j]%4 == 1) c[j]--;
		}
	}
	for (int j = 'a'; j <= 'z'; j++)
		{
			if (c[j]%4 != 0)
			{
				printf("No\n");
				return 0;
			}
		}
	if ((two-done2) % 2 != 0)
		{
			printf("No\n");
				return 0;
		}
	printf("Yes\n");
}

