bool palin(string str){
  int k = str.size()/2;
  for(int i=0;i<k;i++) if(str[i] != str[str.size()-1-i]) return 0;
  return 1;
}

void Swap(int i,int j){for(int k=0;k<h;k++) swap(mp[k][i],mp[k][j]);}


bool ok(int n,int a=0){
  for(int i=0;i<n;i++) 
    for(int j=0;j<=a;j++) if(mp[i][j] != mp[i][w-j-1]) return 0;
  //for(int i=0;i<n;i++) if(!palin(mp[i])) return 0;
  return 1;  
}

bool check(){

  map<string,int> cnt;
  for(int i=0;i<h;i++){
    string str;
    for(int j=0;j<w;j++)str += mp[i][j];
    cnt[str]++;
  }
  int  c = 0;
  for(pair<string,int> p:cnt) c+=p.second%2;
  if(h%2 == 0) return c == 0;
  return c <=1;

  int mid = w / 2;
  for(int j=0;j<mid;j++){
    for(int k=0;k<w;k++){
      for(int l=0;l<w;l++){
        Swap(j,k);
        Swap(w-1-j,l);
        if(ok(h,j)) {k=w,l=w;break;}
        Swap(j,k);
        Swap(w-1-j,l);
      }
    }
  }

  for(int i=0;i<h;i++) if(!palin(mp[i])) return 0;
  return 1;
  return ok(h);
}


