    four -= k;
  }

  for (auto &i : mp) {
    int k = min(two, i.second / 2);
    i.second -= k * 2;
    two -= k;
  }

  for (auto &i : mp) {
    int k = min(one, i.second);
    i.second -= k;
    one -= k;
  }

  cout << (four == 0 && two == 0 && one == 0 ? "Yes" : "No") << endl;

  return 0;
}

