const int kN = 100 + 5;
int a[kN][kN];
int cnt[26];

bool solve(int w2, int w4)
{
    std::vector<int> x(cnt, cnt + 26);
    for (int i = 0; i < 26; ++ i) {
        int tmp = std::min(x[i] / 4, w4);
        w4 -= tmp;
        x[i] -= tmp * 4;
    }
    for (int i = 0; i < 26; ++ i) {
        int tmp = std::min(x[i] / 2, w2);
        w2 -= tmp;
        x[i] -= tmp * 2;
    }
    return !w2 && !w4;
}

int main()
{
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; ++ i) {
        char s[100 + 5];
        scanf("%s", s);
        for (int j  = 0; j < m; ++ j)
            cnt[s[j] - 'a'] ++;
    }
    for (int i = 1; i <= n; ++ i) {
        for (int j = 1; j <= m; ++ j) {
            a[std::min(i, n - i + 1)][std::min(j, m - j + 1)] ++;
        }
    }
    int w[5] = {};
    for (int i = 1; i <= n; ++ i) {
        for (int j = 1; j <= m; ++ j)
            if (a[i][j])
                w[a[i][j]] ++;
    }
    if (w[1]) {
        for (int i = 0; i < 26; ++ i) if (cnt[i]) {
            -- cnt[i];
            if (solve(w[2], w[4]))
                return puts("Yes"), 0;
            ++ cnt[i];
        }
    } else {
        if (solve(w[2], w[4]))
            return puts("Yes"), 0;
    }
    puts("No");
}

