ll ri(){ll l;cin>>l;return l;} string rs(){string s;cin>>s;return s;}

bool solve() {
	int h = ri();
	int w = ri();

	vi C(26);

	rep(i, h) {
		string s = rs();
		rep(j, w) C[s[j] - 'a']++;
	}

	map<int, int> D;
	vi nc;
	rep(c, 26) {
		D[C[c]]++;
		if (C[c] % 2) {
			nc.emplace_back(c);
		}
	}

	if (sz(nc) >= 2) return 0;

	out(C);
	out(D);

	if (h*w % 2 == 0) {
		rep(i, 26) if (C[i] % 2) return 0;
	}

	auto judge = [&](int need4, int need2) -> bool {
		out(need4, need2);
		out(C);
		priority_queue<int> Q;
		rep(c, 26) if(C[c]) Q.emplace(C[c]);
		while (sz(Q)) {
			int t = Q.top(); Q.pop();
			if (t == 0) break;
			if (need4) {
				if (t < 4) return 0;
				need4--;
				Q.emplace(t - 4);
			}
			else if (need2) {
				if (t < 2) return 0;
				need2--;
				Q.emplace(t - 2);
			}
		}
		return (need4 == 0 && need2 == 0);
	};

	if (h % 2 && w % 2) {
		out("OO");
		out(nc);
		if (sz(nc) != 1) return 0;
		int odd = nc[0];
		C[odd]--;
		int need4 = (h-1)*(w-1)/4;
		int need2 = (h-1)/2 + (w-1)/2;
		return judge(need4, need2);
	}
	else if (h % 2) {
		out("OE");
		if (sz(nc)) return 0;
		int need2 = (w - 2) / 2;
		int need4 = (w - 2) * (h - 1) / 4;
		return judge(need4, need2);
	}
	else if (w % 2) {
		out("EO");
		if (sz(nc)) return 0;
		int need2 = (h - 2) / 2;
		int need4 = (h - 2) * (w - 1) / 4;
		return judge(need4, need2);
	}
	else {
		out("EE");
		if (sz(nc)) return 0;
		int need2 = 0;
		int need4 = h*w/4;
		return judge(need4, need2);
	}
	assert(false);
}

