bool solve(int H, int W, vs& a) {
    vi cnt(26,0);
    rep(i,H) rep(j,W) {
        cnt[ a[i][j] -'a' ]++;
    }
    if (H % 2 == 0) {
        if (W % 2 == 0) {
            rep(i,26) {
                if (cnt[i] % 4) return false;
            }
            return true;
        } else {
            int four=0, two=0;
            rep(i,26) {
                if (cnt[i] % 4 == 0) { ++four; continue; }
                if (cnt[i] % 2 == 0) { ++two; continue; }
                return false;
            }
            if (two <= H/2) return true;
            return false;
        }
    } else {
        if (W % 2 == 0) {
            int four=0, two=0;
            rep(i,26) {
                if (cnt[i] % 4 == 0) { ++four; continue; }
                if (cnt[i] % 2 == 0) { ++two; continue; }
                return false;
            }
            if (two <= W/2) return true;
            return false;
        } else {
            int four=0, two=0, one=0;
            rep(i,26) {
                if (cnt[i] % 2) {
                    ++one;
                    if (one == 2) return false;
                    cnt[i]--;
                }
                if (cnt[i] % 4 == 0) { ++four; continue; }
                if (cnt[i] % 2 == 0) { ++two; continue; }
                return false;
            }
            if (two <= W/2+H/2) return true;
            return false;
        }
    }

    return false;
}

int main() {
    int H, W; cin >> H >> W;
    vs a(H); rep(i,H) cin >> a[i];
    cout << (solve(H,W,a) ? "Yes":"No") << endl;
    return 0;
}

