bool ee(int mod[]) {
  return mod[1] == 0 && mod[2] == 0 && mod[3] == 0;
}

bool eo(int mod[], int e) {
  return mod[1] == 0 && mod[3] == 0 && mod[2] <= e;
}

bool oo(int mod[], int x, int y) {
  if(mod[1] > 1) {
    return false;
  }
  if(mod[1] == 0) {
    if(mod[3] == 1) {
      mod[2]++;
    } else {
      return false;
    }
  }
  return mod[2] <= x + y - 2;
}

