  }
  bool ans;
  if(H % 2 == 0 && W % 2 == 0) {
    ans = ee(mod);
  } else if(H % 2 == 1 && W % 2 == 1) {
    ans = oo(mod, H, W);
  } else if(H % 2 == 1) {
    ans = eo(mod, W);
  } else {
    ans = eo(mod, H);
  }
  cout << (ans ? "Yes" : "No") << endl;
  return 0;
}

