  for (int i = 0; i < h; ++i) {
    string s;
    cin >> s;
    for (int j = 0; j < w; ++j) {
      ch[s[j]]++;
    }
  }
  int k = 0, g = 0;
  int max_ch = 0;
  for (int i = 0; i < 256; ++i) {
    if (ch[i] != 0) {
      if (ch[i] % 2 == 0) {
        g++;
      }
      else {
        ++k;
      }
      max_ch = max(max_ch, ch[i]);
    }
  }
  if (h == 2 && w == 2 && g != 0) {
    cout << "No" << endl;
  }
  else if (k <= 1 && max_ch <= min(h, w) * 2) {
    cout << "Yes" << endl;
  }
  else {
    cout << "No" << endl;
  }
  return 0;
}

