int h,w;
map<char, int> m;

string yes = "Yes";
string no = "No";

void solve_oo()
{
    int count = 0;
    vector<int> ss;
    for(auto e : m)
    {
        if(e.second % 2 == 1)
        {
            ss.push_back(e.second-1);
            count++;
        }
        else
        {
            ss.push_back(e.second);
        }
    }
    if(count != 1)
    {
        cout << no << endl;
        return;
    }
    int f = 0;
    int s = 0;
    for(int i = 0;i < ss.size();i++)
    {
        f += ss[i] / 4;
        ss[i] -= (ss[i] / 4) * 4;
        s += ss[i] / 2;
        ss[i] -= (ss[i] / 2) * 2;
        if(ss[i] != 0)
        {
            cout << no << endl;
            return;
        }
    }
    auto fc = (h * w - h - w + 1) / 4;
    if(fc > f)
    {
        cout << no << endl;
        return;
    }
    cout << yes << endl;
}

void solve_oe()
{
    int f = 0;
    int s = 0;
    for(auto e : m)
    {
        auto c = e.second;
        f += c / 4;
        c -= (c / 4) * 4;
        s += c / 2;
        c -= (c / 2) * 2;
        if(c != 0)
        {
            cout << no << endl;
            return;
        }
    }
    auto fc = (h * w - h) / 4;
    if(fc > f)
    {
        cout << no << endl;
        return;
    }
    cout << yes << endl;
}

void solve_ee()
{
    for(auto e : m)
    {
        if(e.second % 4 != 0)
        {
            cout << no << endl;
            return;
        }
    }
    cout << yes << endl;
}

int main() {
    cin >> h >> w;
    for(int y = 0;y < h;y++)
    {
        string s;
        cin >> s;
        for(int x = 0;x < w;x++)
        {
            m[s[x]]++;
        }
    }
    if(h % 2 == 1)
    {
        swap(w,h);
    }
    if(h % 2 == 0 && w % 2 == 0)
    {
        solve_ee();
        return 0;
    }
    if(h % 2 == 1 && w % 2 == 1)
    {
        solve_oo();
        return 0;
    }
    solve_oe();
    return 0;
}

