	if (H % 2 == 1 && W % 2 == 0) {
		if (two > W/2 || one >= 1)flag = false;
	}
	if (H % 2 == 1 && W % 2 == 1) {
		if (two > (H+W)/2-1 || one >= 2)flag = false;
	}

