int H, W;
int cnt[26];

void init()
{
	cin >> H >> W;
	rep(i, H*W) {
		char c;
		cin >> c;
		cnt[c-'a']++;
	}
}

void solve()
{
	int f = 0;
	int t = 0;
	int A = H * W;
	int nt, nf;
	rep(i, 26) {
		f += cnt[i] / 4;
		cnt[i] -= (cnt[i] / 4) * 4;
		t += cnt[i] / 2;
	}
	if (W % 2 && H % 2) {
		nf = (W / 2) * (H / 2);
		nt = (A - nf * 4 - 1) / 2;
	} else if (W % 2 || H % 2) {
		if (W % 2) {
			nf = (W - 1) * H / 4;
			nt = A - nf * 4;
			nt /= 2;
		} else {
			nf = W * (H - 1) / 4;
			nt = A - nf * 4;
			nt /= 2;
		}
	} else {
		nf = A / 4;
		nt = 0;
	}
	if (f < nf) {
		PRINT(0);
		return;
	}
	t += (f - nf) * 2;
	PRINT(t >= nt);
}

