  rep(i, H) {
    cin >> mat[i];
    rep(j, W) {
      c[mat[i].at(j) - 'a']++;
    }
  }

  int numodd = 0;
  int sumrem = 0;
  rep(i, 26) {
    int rem = c[i]%4;
    sumrem += rem;
    if (rem%2 == 1) {
      numodd++;
    }
