    tolerant += W;
  }
  if (W%2 == 1) {
    tolerant += H;
  }
  if (H%2 == 1 && W%2 == 1) {
    tolerant--;
  }
  if (sumrem > tolerant) {
    cout << "No" << endl;
    return 0;
  }
  cout << "Yes" << endl;
