int main(){
    int h, w;
    cin >> h >> w;

    char c;
    int cnt[26] = {};

    for(int i = 0; i < h*w; i++){
        cin >> c;
        cnt[c-'a']++;
    }

    if(h == 1 || w == 1){
        if(h == 1)  swap(h, w);
        if(h == 1){
            cout << "Yes" << endl;
        }else{
            int odd = h%2;
            for(int i = 0; i < 26; i++) odd -= (cnt[i]%2);
            if(odd == 0)    cout << "Yes" << endl;
            else            cout << "No" << endl;
        }
        return 0;
    }

    bool judge = true;
    if(h%2 + w%2 == 0){
        for(int x : cnt)    judge &= (x%4==0);
    }else if(h%2 + w%2 == 2){
        int want = (h-1)/2*(w-1)*2;
        for(int i = 0; i < 26 && want > 0; i++){
            while(cnt[i] >= 4 && want > 0)  cnt[i] -= 4, want--;
        }
        judge &= (want == 0);
        want = (h-1)/2 + (w-1)/2;
        for(int i = 0; i < 26 && want > 0; i++){
            while(cnt[i] >= 2 && want > 0)  cnt[i] -= 2, want--;
        }
        judge &= (want == 0);
        // 本当は1があるかどうかチェックしなければいけないが、自明なので省略
    }else{
        if(w%2) swap(h,w);
        int want = (h-1)/2*w/2;
        for(int i = 0; i < 26 && want > 0; i++){
            while(cnt[i] >= 4 && want > 0)  cnt[i] -= 4, want--;
        }
        judge &= (want == 0);
        want = w/2;
        for(int i = 0; i < 26 && want > 0; i++){
            while(cnt[i] >= 2 && want > 0)  cnt[i] -= 2, want--;
        }
        judge &= (want == 0);
    }

    cout << (judge ? "Yes" : "No") << endl;

    return 0;
}

