int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    vector<int> v(26, 0);
    REP(i, h) {
        cin >> s[i];
        for (auto &x : s[i])
            v[x - 'a']++;
    }

    bool flag = true;
    int mod1 = 0, mod2 = 0, mod4 = 0;
    REP(i, 26) {
        int t = v[i];
        mod1 += t % 2;
        t -= mod1;
        mod2 += t % 4;
    }
    mod4 = h * w - mod1 - mod2;
    // 縦横が全て偶数なら、文字の個数は4で割り切れる
    if (h % 2 == 0 && w % 2 == 0) {
        if (mod1 > 0 || mod2 > 0)
            flag = false;
    }
    // 縦横が奇数なら、中心の文字の1個は任意
    // (h - 1) + (w - 1)は2で割り切れる
    // 他は4で割り切れる
    else if (h % 2 == 1 && w % 2 == 1) {
        if (mod1 > 1 || mod2 > (h - 1) + (w - 1)) {
            flag = false;
        }
    }
    // 縦が奇数、横が偶数
    else if (h % 2 == 1) {
        if (mod1 > 0 || mod2 > w) {
            flag = false;
        }
    }
    // 縦が偶数、横が奇数
    else {
        if (mod1 > 0 || mod2 > h) {
            flag = false;
        }
    }
    if (flag) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

    return 0;
}

