	bool flag = true;

	if (H % 2 == 0 && W % 2 == 0) { // 両方偶数
		for (int i = 0; i < 26; i++) {
			if (alpha[i] % 4 != 0) flag = false;
		}
	}
	else if (H % 2 == 0) { // Hが偶数、Wが奇数
		// 4の倍数がH*(W-1)/4個必要
		int cnt = H * (W - 1) / 4;
		for (int i= 0; i < 26; i++) {
			while (cnt > 0 && alpha[i] >= 4) {
				cnt--;
				alpha[i] -= 4;
			}
		}
		if (cnt > 0) flag = false;
		// 残りがすべて偶数なら良い
		for (int i = 0; i < 26; i++) if (alpha[i] % 2 != 0) flag = false;
	}
	else if (W % 2 == 0) {
		// 4の倍数がW*(H-1)/4個必要
		int cnt = W * (H - 1) / 4;
		for (int i= 0; i < 26; i++) {
			while (cnt > 0 && alpha[i] >= 4) {
				cnt--;
				alpha[i] -= 4;
			}
		}
		if (cnt > 0) flag = false;
		// 残りがすべて偶数なら良い
		for (int i = 0; i < 26; i++) if (alpha[i] % 2 != 0) flag = false;
	}
	else { //両方奇数
		//一つだけ4の倍数+1になってて、
		// (H-1)*(W-1)/4個の４の倍数
		int cnt1 = (H - 1)*(W - 1) / 4; // 4の塊の個数
		int cnt2 = (H + W - 2) / 2; // 2の塊の個数

		for (int i = 0; i < 26; i++) {
			while (cnt1 > 0 && alpha[i] >= 4) {
				cnt1--;
				alpha[i] -= 4;
			}
		}

		for (int i = 0; i < 26; i++) {
			while (cnt2 > 0 && alpha[i] >= 2) {
				cnt2--;
				alpha[i] -= 2;
			}
		}
		if (cnt1 != 0) flag = false;
		if (cnt2 != 0) flag = false;
	}
	if (flag) cout << "Yes" << endl;
	else cout << "No" << endl;

	return 0;
}

