bool possible(int H, int W, array<int, 26> counts)
{
    array<int, 5> needed{};
    needed[4] = (H/2) * (W/2);
    needed[2] = (H/2)*(W%2) + (W/2)*(H%2);
    needed[1] = (H%2) * (W%2);

    array<int, 5> available{};
    for (const int x : {4, 2, 1})
    {
        for (int& c : counts)
        {
            available[x] += c/x;
            c %= x;
        }
    }

    for (const int x : {4, 2, 1})
    {
        if (available[x] < needed[x])
            return false;

        available[x] -= needed[x];
        available[x/2] += 2*available[x];
    }
    return true;
}

