void pre_calcu(void) {
	V1.clear();	V2.clear(); V4.clear();
	int g4 = (H / 2) * (W / 2);
	for (int i = 0; i < 26; ++i) {
		if (C[i] == 0)
			continue;
		int cnt = C[i];
		while (cnt > 0) {
			if (cnt >= 4) {
				cnt -= 4;
				if ((int)V4.size() >= g4) {
					V2.push_back((char)(i + 'a'));
					V2.push_back((char)(i + 'a'));
				}
				else
					V4.push_back((char)(i + 'a'));
			}
			else if (cnt >= 2) {
				cnt -= 2;
				V2.push_back((char)(i + 'a'));
			}
			else if (cnt == 1) {
				--cnt;
				V1.push_back((char)(i + 'a'));
			}
		}
	}
}

bool solve(void) {
	bool ret = false;
	int g4 = (H / 2) * (W / 2);
	if (H % 2 == 0 && W % 2 == 0) {
		if (g4 == V4.size())
			ret = true;
	}
	else if (H % 2 == 1 && W % 2 == 1) {
		if (V1.size() != 1)
			return ret;
		int g2 = (H / 2) + (W / 2);
		if (g2 == V2.size() && g4 == V4.size())
			ret = true;
	}
	else {
		int g2 = (H % 2 == 0) ? H / 2 : W / 2;
		if (g2 == V2.size() && g4 == V4.size())
			ret = true;
	}
	return ret;
}

