int main() {
    int H, W;
    cin >> H >> W;
    map<char, int> cnt;
    set<char> se;
    vector<string> S(H);
    for (int i = 0; i < H; i++) {
        cin >> S[i];
        for (int j = 0; j < W; j++) {
            se.insert(S[i][j]);
            if (cnt.count(S[i][j])) cnt[S[i][j]]++;
            else cnt[S[i][j]] = 1;
        }
    }

    bool ans = true;
    int g = (H/2)+(W/2), h = (H/2)*(W/2);
    for (auto c : se) {
        if (cnt[c] % 4 == 1 || cnt[c] % 4 == 3) {
            cnt[c]--;
            break;
        }
    }

    int cg = 0;
    while (cg < g) {
        bool a = true;
        for (auto c : se) {
            if (cnt[c] % 4 == 2) {
                cnt[c] -= 2;
                cg++;
                a = false;
                break;
            }
        }
        if(a)break;
    }

    cg = 0;
    while (cg < h) {
       bool a = true;
       for (auto c : se) {
           if (cnt[c] == 0) continue;
           if (cnt[c] % 4 == 0) {
               cnt[c] -= 4;
               cg++;
               a = false;
               break;
           }
       }
       if(a)break;
    }
    if (cg < h) ans = false;

    for (auto c : se) {
        if (cnt[c] != 0) ans = false;
    }

    cout << ((ans) ? "Yes" : "No") << endl;
    //for (auto c : se) cout << c << " : " << cnt[c] << endl;
    return 0;
}

