using ll = long long;

bool Check(auto cnt, const int h, const int w) {
    const int n1 = floor(h / 2.0) * floor(w / 2.0);
    const int n2 = floor((h * w - n1 * 4) / 2.0);

    for (auto &it : cnt)
        if (it.second % 2 == 1) {
            --it.second;
            break;
        }
    for (auto &it : cnt)
        if (it.second % 2 == 1) return false;

    int x2 = 0;
    for (auto &it : cnt) {
        if (it.second == 2) {
            ++x2;
            it.second = 0;
        }
    }
    if (n2 < x2) return false;

    for (auto &it : cnt) {
        if (0 < it.second && it.second % 4 != 0) {
            ++x2;
            it.second -= 2;
        }
    }
    if (n2 < x2) return false;

    // すべて4の倍数
    int x1 = 0;
    for (auto &it : cnt) {
        if (0 < it.second && it.second % 4 == 0) {
            x1 += it.second / 4;
            it.second = 0;
        }
    }
    if (2 * (n2 - x2) + 4 * n1 != 4 * x1) return false;

    return true;
}

