#include <stdio.h>
#include <stdlib.h>

int main()
{
	int i, H, W;
	char a[101][101];
	scanf("%d %d", &H, &W);
	for (i = 1; i <= H; i++) scanf("%s", &(a[i][1]));

	int j, count[26] = {};
	for (i = 1; i <= H; i++) {
		for (j = 1; j <= W; j++) count[a[i][j] - 'a']++;
	}

	int flag = 1;
	if (H % 2 == 0 && W % 2 == 0) {
		for (i = 0; i < 26; i++) if (count[i] % 4 != 0) break;
		if (i < 26) flag = 0;
	} else if (H % 2 == 0) {
		for (i = 0, j = 0; i < 26; i++) {
			if (count[i] % 2 != 0) break;
			else if (count[i] % 4 != 0) j++;
		}
		if (i < 26 || j > H) flag = 0;
	} else if (W % 2 == 0) {
		for (i = 0, j = 0; i < 26; i++) {
			if (count[i] % 2 != 0) break;
			else if (count[i] % 4 != 0) j++;
		}
		if (i < 26 || j > W) flag = 0;
	} else {
		for (i = 0, j = 0; i < 26; i++) {
			if (count[i] % 2 == 1) {
				if (flag == -1) break;
				flag = -1;
				if (count[i] % 4 == 3) j++;
			} else if (count[i] % 4 != 0) j++;
		}
		if (i < 26 || j > H + W - 1) flag = 0;
	}

	if (flag != 0) printf("Yes\n");
	else printf("No\n");
	fflush(stdout);
	return 0;
}

#include <stdio.h>

int main(void)
{
  int i, j;
  int h, w;
  char a[101];

  int ans;

  int count[26];
  int div4, div2, div1;

  scanf("%d", &h);
  scanf("%d", &w);

  for (i = 0; i < 26; i++)count[i] = 0;
  for (i = 0; i < h; i++) {
    scanf("%s", &a);
    for (j = 0; j < w; j++) {
      count[a[j] - 'a']++;
    }
  }

  div4 = div2 = div1 = 0;
  for (i = 0; i < 26; i++) {
    if (count[i] > 0) {
      if (count[i] % 4 == 0)div4++;
      else if (count[i] % 2 == 0)div2++;
      else {
        div1++;
        if ((count[i] - 1) % 4 == 0)div4++;
        else if ((count[i] - 1) % 2 == 0)div2++;
      }
    }
  }

  if ((h % 2 == 0) && (w % 2 == 0)) {
    ans = ((div2 == 0) && (div1 == 0));
  } else if ((h % 2 == 1) && (w % 2 == 0)) {
    ans = ((div2 <= w) && (div1 == 0));
  } else if ((h % 2 == 0) && (w % 2 == 1)) {
    ans = ((div2 <= h) && (div1 == 0));
  } else {
    ans = ((div2 <= h + w - 2) && (div1 == 1));
  }

  printf(ans ? "Yes\n" : "No\n");

  return(0);
}

