//n個の回文(長さsize)が作れるかどうかチェック 1:作れる 0:作れない
int make_palindrome(int *array, const int size, const int n){
    int i, j;

    //列数が奇数の場合
    if(size%2 == 1){
        for(i=0; i<size/2; i++){
            for(j=0; j<CHARACTERS; j++){
                if(array[j] >= 2*n){
                    array[j] -= 2*n;
                    break;
                }else if(j == CHARACTERS-1){
                    return 0;
                }
            }
        }
        for(i=0; i<CHARACTERS; i++){
                if(array[i] >= 1*n){
                    array[i] -= 1*n;
                    break;
                }else if(i == CHARACTERS-1){
                    return 0;
                }
        }
        return 1;
    }

    //列数が偶数の場合
    if(size%2 == 0){
        for(i=0; i<size/2; i++){
            for(j=0; j<CHARACTERS; j++){
                if(array[j] >= 2*n){
                    array[j] -= 2*n;
                    break;
                }else if(j == CHARACTERS-1){
                    return 0;
                }
            }
        }
        return 1;
    }

    return 1;
}

