    ll ans=0;
    rep(i,0,n-1){
        ll c=0;
        rep(j,i+1,n) if(a[i]>a[j]) c++;
        ans+=c*factorial(n-i-1);
    }
    return ans;
}
ll permutation2(ll n, ll a[n], ll p){
    rrep(i,n-1,1){
        if(p/factorial(i)==0) continue;
        swap( &a[n-i-1] , &a[ (n-i-1) + p/factorial(i) ]);
        p%=factorial(i);
        ll b[i];
        rep(j,0,i) b[j] =  a[n-i+j];
        sortup(b,i);
        rep(j,0,i) a[n-i+j] = b[j];
    }
    ll ans=0;
    rep(i,0,n) ans+=a[i]*POW(10,n-1-i);
    return ans;
}


