#define POS(i,j) ((i)*w+(j))

int calc(char *s,int h,int w){
  int cnt[26]={0};
  int i,j;
  for(i=0;i<h;i++){
    for(j=0;j<w;j++){
      cnt[s[POS(i,j)]-'a']++;
    }
  }
  int c2=0;
  int c1=0;
  for(i=0;i<26;i++){
    c2+=cnt[i]%4;
    c1+=cnt[i]%2;
  }
  if(h%2==0 && w%2==0) return c2==0 && c1==0;
  if(h%2==1 && w%2==1) return c1==1 && c2-c1<=h-1+w-1;
  if(h%2==1) return c1==0 && c2<=w;
  return c1==0 && c2<=h;
}

void run(void){
  int h,w;
  scanf("%d%d",&h,&w);
  char *s=(char *)malloc(sizeof(char)+(h*w+1));
  int i;
  for(i=0;i<h;i++) scanf("%s",s+POS(i,0));
  printf("%s\n",calc(s,h,w)?"Yes":"No");
}

int main(void){
  run();
  return 0;
}

