fun solve() {
    val (H, W) = rd.readListInt()
    val A = (0 until H).map { rd.readString() }

    val mp = mutableMapOf<Char, Int>()
    A.forEach{ it.forEach{ mp[it] = (mp[it] ?: 0) + 1 }}

    if (H==1 && W==1) {
        println("Yes")
        return
    } else if (W==1) {
        if (H%2==0) {
            for (pr in mp) {
                if (pr.value%2==1) {
                    println("No")
                    return
                }
            }
            println("Yes")
            return
        } else {
            var odd = 0
            for (pr in mp) {
                if (pr.value%2==1) {
                    odd++
                }
            }
            val ans = if (odd==1) "Yes" else "No"
            println(ans)
            return
        }
    } else if (H==1) {
        if (W%2==0) {
            for (pr in mp) {
                if (pr.value%2==1) {
                    println("No")
                    return
                }
            }
            println("Yes")
            return
        } else {
            var odd = 0
            for (pr in mp) {
                if (pr.value%2==1) {
                    odd++
                }
            }
            val ans = if (odd==1) "Yes" else "No"
            println(ans)
            return
        }
    }

    val mp1 = mutableMapOf<Char, Int>()
    var ch = 'A'
    for (i in 0 until (H+1)/2) {
        if (H%2==1 && i == (H+1)/2-1) {
            for (j in 0 until (W+1)/2) {
                if (W%2==1 && j == (W+1)/2-1) mp1[ch++] = 1
                else mp1[ch++] = 2
            }
        } else {
            for (j in 0 until (W+1)/2) {
                if (W%2==1 && j == (W+1)/2-1) mp1[ch++] = 2
                else mp1[ch++] = 4
            }
        }
    }

    for (pr1 in mp1) {
        var ok = false
        for ((k, v) in mp) {
            if (v >= pr1.value) {
                mp[k] = mp[k]!! - pr1.value
                ok = true
                break
            }
        }
        if (!ok) {
            println("No")
            return
        }
    }

    println("Yes")
}


