  val oneCount = if (h % 2 == 1 && w % 2 == 1) 1 else 0
  val twoCount = (if (h % 2 == 1) w / 2 else 0) + (if (w % 2 == 1) h / 2 else 0)
  val fourCount = h / 2 * w / 2

  val charCounts = IntArray(26)
  for (row in board) {
    for (c in row) {
      charCounts[c - 'a']++
    }
  }

  val oddCount = charCounts.filter { it % 2 == 1 }.size
  if (oddCount > oneCount) {
    println("No")
    return
  }

  val oddIndex = charCounts.indexOfFirst { it % 2 == 1 }
  if (oddIndex >= 0) {
