            int n = sc.nextInt();
            String[] t = IntStream.range(0, n).mapToObj(i -> sc.next()).toArray(String[]::new);
            StringBuilder builder = new StringBuilder();
            for (String baseItem : s) {
                boolean isMatch = false;
                for (String item : t) {
                    if (baseItem.length() != item.length())
                        continue;
                    int cnt = 0;
                    for (int i = 0; i < item.length(); i++) {
                        if (item.charAt(i) == '*' || item.charAt(i) == baseItem.charAt(i)) {
                            cnt++;
                        }
                    }
                    if (cnt == baseItem.length()) {
                        isMatch = true;
                        break;
                    }
                }
                if (isMatch)
                    builder.append(IntStream.range(0, baseItem.length()).mapToObj(i -> "*").collect(Collectors.joining()) + " ");
                else
                    builder.append(baseItem + " ");
            }
            System.out.println(builder.toString().trim());
