        /*
        a b c b a
        e f g f e
        a b c b a
        a b -> 4
        c f e -> 2(h/2+w/2以下)
        g -> 1

        a b c c b a
        e f g g f e
        e f g g f e
        a b c c b a
        a b c e f g -> 4

        a b c c b a
        e f g g f e
        a b c c b a
        a b c-> 4
        e f g -> 2(w/2以下)
         */
        Map<Character, Integer> memo = new HashMap<Character, Integer>();
        for (char[] item : a) {
            for (char inner : item) {
