				if (dp[row][col]==0) {
					if (dp[row][col]==0) {
						dp[row][col]=cur;
						ltrs[cur]++;
					}
					if (dp[row][C-col-1]==0) {
						ltrs[cur]++;
						dp[row][C-col-1]=cur;
					} 
					if (dp[R-row-1][col]==0) {
						dp[R-row-1][col]=cur;
						ltrs[cur]++;
					}
					if (dp[R-row-1][C-col-1]==0) {
						dp[R-row-1][C-col-1]=cur;
						ltrs[cur]++;
					} //Squares that absolutely need the same letter
