    private void solveD() {
        int h = nextInt();
        int w = nextInt();
        char[][] a = IntStream.range(0, h).mapToObj(i -> next().toCharArray()).toArray(char[][]::new);
        /*
        a b c b a
        e f g f e
        a b c b a
        a b -> 4
        c f e -> 2(h/2+w/2以下)
        g -> 1

        a b c c b a
        e f g g f e
        e f g g f e
        a b c c b a
        a b c e f g -> 4

        a b c c b a
        e f g g f e
        a b c c b a
        a b c-> 4
        e f g -> 2(w/2以下)
         */
        Map<Character, Integer> memo = new HashMap<Character, Integer>();
        for (char[] item : a) {
            for (char inner : item) {
                memo.put(inner, memo.getOrDefault(inner, 0) + 1);
            }
        }
        Map<Integer, List<Character>> tmp = new HashMap<Integer, List<Character>>();
        for (Map.Entry<Character, Integer> e : memo.entrySet()) {
            int key = e.getValue() % 4;
            tmp.put(key, tmp.getOrDefault(key, new ArrayList<Character>()));
            tmp.get(key).add(e.getKey());
        }
        if (h % 2 == 0 && w % 2 == 0) {
            for (Map.Entry<Integer, List<Character>> e : tmp.entrySet()) {
                if (e.getKey() % 4 != 0) {
                    out.println("No");
                    return;
                }
            }
            out.println("Yes");
        } else if (h % 2 == 1 && w % 2 == 1) {
            if (tmp.getOrDefault(1, new ArrayList<Character>()).size() > 1L
                    || tmp.getOrDefault(2, new ArrayList<Character>()).size() > ((h - 1) / 2 + (w - 1) / 2)
                    || tmp.getOrDefault(3, new ArrayList<Character>()).size() > 1L) {
                out.println("No");
            } else {
                out.println("Yes");
            }
        } else {
            int baseNum = (h % 2 == 0) ? h : w;
            if (tmp.containsKey(1)
                    || tmp.getOrDefault(2, new ArrayList<Character>()).size() > (baseNum / 2)
                    || tmp.containsKey(3)) {
                out.println("No");
            } else {
                out.println("Yes");
            }
        }
    }

