        int p = 0;
        if ((s1 % 2) == 1 && (s2 % 2 == 1)) {
            p = s1 + s2 - 2;

            for (int i = 0; i < 26; i++) {
                if (ct[i] % 2 == 1) {
                    ct[i]--;
                }
            }
        } else {
