	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int h = in.nextInt(), w = in.nextInt();
			boolean is_h_even = h % 2 == 0 ? true : false;
			boolean is_w_even = w % 2 == 0 ? true : false;

			int count = 0;
			if (is_w_even) {
				count = w / 2;
			} else {
				count = h / 2;
			}

			int[] s = new int[26];
			for (int i = 0; i < h; i++) {
				char[] t = in.nextString().toCharArray();
				for (int j = 0; j < w; j++) {
					s[t[j]-'a']++;
				}
			}

			boolean ans = true;

			if (h == 1 && w == 1) {
				out.println("Yes");
				return;
			} else if (h == 1 || w == 1) {
				if ((is_w_even && !is_h_even) || (!is_w_even && is_h_even)) {
					for (int i = 0; i < 26; i++) {
						if (s[i] % 2 == 1) {
							ans = false;
							break;
						}
					}
				} else {
					int oddCount = 0;
					for (int i = 0; i < 26; i++) {
						if (s[i] % 2 == 1) {
							oddCount++;
						}
					}
					if (oddCount > 1) {
						ans = false;
					}
				}

				if (ans) {
					out.println("Yes");
				} else {
					out.println("No");
				}
				return;
			}

			if (is_w_even && is_h_even) {
				for (int i = 0; i < 26; i++) {
					if (s[i] % 4 == 0) {
						continue;
					} else {
						ans = false;
						break;
					}
				}
			} else if  ((is_w_even && !is_h_even) || (!is_w_even && is_h_even)) {
				int oddCount = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 0) {
						s[i] = s[i] / 2;
						if (s[i] % 2 == 1) {
							oddCount++;
						}
						continue;
					} else {
						ans = false;
						break;
					}
				}
				if (oddCount != count) {
					ans = false;
				}
			} else if (!is_w_even && !is_h_even) {
				int oddCount = 0;
				int oddCharNum = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 1) {
						oddCount++;
						oddCharNum = i;
					}
				}
				if (oddCount >= 2) {
					ans = false;
				} else {
					s[oddCharNum]--;
				}
				oddCount = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 0) {
						s[i] = s[i] / 2;
						if (s[i] % 2 == 1) oddCount++;
					} else {
						ans = false;
						break;
					}
				}
				if (oddCount > (w/2+h/2)) {
					ans = false;
				}
			}

			if (ans) {
