public class Main {
  private static boolean solve(int h, int w, char[][] cm) {
    int[] counts = new int[26];
    for (char[] cs : cm) {
      for (char c : cs) {
        counts[c - 'a']++;
      }
    }
    int num1 = 0;
    int num2 = 0;
    for (int count : counts) {
      if (count % 2 == 1) {
        num1++;
      } else if (count % 4 == 2) {
        num2++;
      }
    }
    if (num1 != (h * w) % 2) {
      return false;
    }
    int maxNum2 = 0;
    if (h % 2 == 1) {
      maxNum2 += (w / 2) * 2;
    }
    if (w % 2 == 1) {
      maxNum2 += (h / 2) * 2;
    }
    return num2 <= maxNum2;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int h = reader.nextInt();
    int w = reader.nextInt();
    char[][] cm = reader.nextCharArray(h);
    out.println(solve(h, w, cm) ? "Yes" : "No");
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
