		for(int a:alp){
			if(a%4==1){
				o++;
			}else if(a%4==2){
				d++;
			}else if(a%4==3){
				d++;
				o++;
			}
		}

		boolean ans = false;
		if(W%2==0 && H%2==0){
			ans = d==0 && o==0;
		}else if(W%2==0){
			ans = d<=W/2 && o==0;
		}else if(H%2==0){
			ans = d<=H/2 && o==0;
		}else{
			ans = o<=1 && d<=(H-1)/2+(W-1)/2;
		}

		System.out.println(ans ? "Yes" : "No");

	}

}

