        for(int i = 0; i < H; i++){
            for(int j = 0; j < W; j++){
                a[map[i][j]-'a']++;
            }
        }

        int g1 = (H%2) * (W%2);
        int g2 = (H/2) * (W%2) + (W/2) * (H%2);
        int g4 = H/2 * W/2;

        for(int i = 0; i < 26; i++){
            while(g4 > 0 && a[i] >= 4){
                a[i] -= 4;
                g4 --;
            }
        }
        for(int i = 0; i < 26; i++){
            while(g2 > 0 && a[i] >= 2){
                a[i] -= 2;
                g2 --;
            }
        }
        for(int i = 0; i < 26; i++){
            while(g1 > 0 && a[i] >= 1){
                a[i] --;
                g1 --;
            }
        }
