					if (s[i] % 4 == 0) {
						continue;
					} else {
						ans = false;
						break;
					}
				}
			} else if  ((is_w_even && !is_h_even) || (!is_w_even && is_h_even)) {
				int oddCount = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 0) {
						s[i] = s[i] / 2;
						if (s[i] % 2 == 1) {
							oddCount++;
						}
						continue;
					} else {
						ans = false;
						break;
					}
				}
				if (oddCount != count) {
					ans = false;
				}
			} else if (!is_w_even && !is_h_even) {
				int oddCount = 0;
				int oddCharNum = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 1) {
						oddCount++;
						oddCharNum = i;
					}
				}
				if (oddCount >= 2) {
					ans = false;
				} else {
					s[oddCharNum]--;
				}
				oddCount = 0;
				for (int i = 0; i < 26; i++) {
					if (s[i] % 2 == 0) {
						s[i] = s[i] / 2;
						if (s[i] % 2 == 1) oddCount++;
					} else {
						ans = false;
						break;
					}
				}
				if (oddCount > (w/2+h/2)) {
					ans = false;
				}
			}

			if (ans) {
