  private static boolean check(char[][] a) {
    int h = a.length;
    int w = a[0].length;
    boolean[] flg = new boolean[w];
    Arrays.fill(flg, true);

    for (int i = 0; i < h; i ++) {
      boolean[] v = search(a[i]);
      if (v == null) {
