        for (boolean x : flg) {
          if (x) {
            ok = true;
            break;
          }
        }

        if (!ok) {
          return false;
        }
      }
    }
    return true;
  }

  private static boolean[] search(char[] v) {
    int[] count = new int[26];
    for (char c : v) {
      count[c - 'a'] ++;
    }
    int odd = 0;
    char oddC = 0;
    for (int i = 0; i < 26; i ++) {
      if (count[i] % 2 == 1) {
        odd ++;
        if (odd >= 2) {
          return null;
        }
        oddC = (char)(i + 'a');
      }
    }

    boolean[] ret = new boolean[v.length];
    if (oddC == 0) {
      Arrays.fill(ret, true);
      return ret;
    }
    for (int i = 0; i < v.length; i ++) {
      if (v[i] == oddC) {
        ret[i] = true;
      }
    }
    return ret;
