            for (int v : map.values()) {
                if (v % 2 == 1) {
                    NO();
                }
                b += v % 4 / 2;
            }
            int c = W % 2 == 0 ? W / 2 : H / 2;
            if (b > c) NO();
        }
        else {
            int a = 0;
            int b = 0;
            for (int v : map.values()) {
                if (v % 2 == 1) {
                    a++;
                    b += (a - 1) % 4;
                }
                else {
                    b += a % 4 / 2;
                }
            }
            if (a != 1 && b > (W  - 1) / 2 + (H - 1) / 2) {
                NO();
            }
        }
        YES();
    }

    static void YES() {
        System.out.println("Yes");
        System.exit(0);
    }

    static void NO() {
        System.out.println("No");
        System.exit(0);
    }
}

