            g1 = 1;
            g2 = h / 2 + w / 2;
        }
        for (int i = 0; i < alpha.length; i++) {
            if (g1 == 0) {
                break;
            }
            if (alpha[i] % 4 == 1 || alpha[i] % 4 == 3) {
                alpha[i]--;
                g1--;
                i = -1;
            }
        }
        for (int i = 0; i < alpha.length; i++) {
