        char[][] a = IntStream.range(0, h).mapToObj(i -> next().toCharArray()).toArray(char[][]::new);
        /*
        a b c b a
        e f g f e
        a b c b a
        a b -> 4
        c f e -> 2(h/2+w/2以下)
        g -> 1

        a b c c b a
        e f g g f e
        e f g g f e
        a b c c b a
        a b c e f g -> 4

        a b c c b a
        e f g g f e
        a b c c b a
        a b c-> 4
        e f g -> 2(w/2以下)
         */
        Map<Character, Integer> memo = new HashMap<Character, Integer>();
        for (char[] item : a) {
            for (char inner : item) {
                memo.put(inner, memo.getOrDefault(inner, 0) + 1);
            }
        }
        Map<Integer, List<Character>> tmp = new HashMap<Integer, List<Character>>();
        for (Map.Entry<Character, Integer> e : memo.entrySet()) {
            int key = e.getValue() % 4;
            tmp.put(key, tmp.getOrDefault(key, new ArrayList<Character>()));
            tmp.get(key).add(e.getKey());
        }
        if (h % 2 == 0 && w % 2 == 0) {
