                out.println("Yes");
            }
        } else {
            int baseNum = (h % 2 == 0) ? h : w;
            if (tmp.containsKey(1) || tmp.containsKey(3)
                    || tmp.getOrDefault(2, new ArrayList<Character>()).size() > (baseNum / 2)) {
                out.println("No");
            } else {
                out.println("Yes");
            }
        }
    }

