		int one = 0;
		if (h % 2 == 1) {
			two += w;
			four -= w;
		}
		if (w % 2 == 1) {
			two += h;
			four -= h;
		}
		if (h % 2 == 1 && w % 2 == 1) {
			two--;
			one++;
			four++;
		}
		four /= 4;
		two /= 2;
		//System.out.println(four + "," + two + "," + one);
		char[][] m = io.nextCharMap(h, w);

		int[] count = new int[256];
		for(int i=0;i<h;i++) {
