				count[m[i][j]]++;
			}
		}
		for(int i=0;i<256;i++) {
			while(count[i] >= 4 && four > 0) {
				count[i]-=4;
				four--;
			}
		}
		two += four * 2;
		for(int i=0;i<256;i++) {
			while(count[i] >= 2 && two > 0) {
				count[i]-=2;
