        long t = System.currentTimeMillis();


        solve();
        out.flush();
    }

    private static void solve() {
        int s1 = sc.nextInt();
        int s2 = sc.nextInt();
        int[] ct = new int[26];
        for (int i = 0; i < s1; i++) {
            String k = sc.next();
            for (char x : k.toCharArray()) {
                ct[x - 'a']++;
                if (ct[x - 'a'] == 4) {
                    ct[x - 'a'] = 0;
                }
            }
        }

        if ((s1 % 2) == 0 && (s2 % 2 == 0)) {
            for (int i : ct) {
                if (i != 0) {
                    out.println("No");
                    return;
                }
            }
            out.println("Yes");
            return;
        }
        int p = s1 + s2 - 1;
        if ((s1 % 2) == 1 && (s2 % 2 == 1)) {
            p--;
            int o = -1;
            for (int i = 0; i < 26; i++) {
                if (ct[i] % 2 == 1) {
                    if (o == -1) {
                        o = i;
                    }
                    if (o != i) {
                        out.println("No");
                        return;
                    }
                    ct[i]--;
                }
            }
        } else {
            for (int c : ct) {
                if (c % 2 == 1) {
                    out.println("No");
                    return;
                }
            }
        }
        p /= 2;
        int r = 0;
        for (int i : ct) {
            if (i == 2) {
                r++;
            }
        }
        out.println(r > p ? "No" : "Yes");
    }


