public class Main {
	private static FastScanner sc = new FastScanner();

	public static void main(String[] args) {
		int H = sc.nextInt();
		int W = sc.nextInt();

		int[] alp = new int[26];
		for(int i=0; i<H; i++) {
			char[] c = sc.next().toCharArray();
			for(int j=0; j<W; j++) {
				alp[c[j] - 'a']++;
			}
		}

		int set4 = 0;
		int set2 = 0;
		int set1 = 0;
		if(H%2 == 0 && W%2 == 0) {
			set4 = H * W / 4;
		} else if(H%2 == 0) {
			set2 = H / 2;
			set4 = (W-1) * H / 4;
		} else if(W%2 == 0){
			set2 = W / 2;
			set4 = (H-1) * W / 4;
 		} else {
			set1 = 1;
			set2 = (H-1) / 2 + (W-1) / 2;
			set4 = (H-1) * (W-1) / 4;
		}

//		System.out.println(set4 + " " + set2 + " " + set1);

		int pos = 0;
		while(pos < 26) {
			if(alp[pos] == 0) {
				pos++;
				continue;
			}

			if(alp[pos]%4 == 0) {
				if(set4 > 0) {
					set4--;
					alp[pos] -= 4;
				} else if(set2 >= 2){
					set2 -= 2;
					alp[pos] -= 4;
				} else {
					System.out.println("No");
