            return false;
        }

        long center = h % 2 * h + w % 2 * w - (h % 2 * w % 2);
        long cnt2 = Arrays.stream(cnt).filter(n -> n % 4 >= 2).count();
        if (center % 2 == cnt2 % 2) {
            return false;
        }

        return true;
    }

