@SuppressWarnings("unused")
public class Main {
	String fileName = "input.txt";
	final boolean isDebug = false;
	//final boolean isDebug = true;
	FastScanner in = new FastScanner(System.in);
	PrintWriter out = new PrintWriter(System.out);
	final int MOD = (int)1e9+7;
	final long INF = Long.MAX_VALUE / 2;
	//final int INF = Integer.MAX_VALUE / 2;

	//System.out.println();はつかわない！！
	void solve() throws Exception{
		int H = in.nextInt(), W = in.nextInt(), sum = H * W;
		int[] alp = new int[26];
		for(int i = 0; i < H; i++) for(int j = 0; j < W; j++) alp[in.nextChar()-'a']++;
		PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
		for(int i = 0; i < 26; i++) if(alp[i] != 0) pq.add(alp[i]);

		ArrayList<Integer> num = new ArrayList<>();
		if(H % 2 == 0 && W % 2 == 0){
			for(int i = 0; i < sum / 4; i++) num.add(4);
		}else if(H % 2 == 1 && W % 2 == 0){
			for(int i = 0; i < W / 2; i++) num.add(2);
			for(int i = 0; i < (sum - W) / 4; i++) num.add(4);
		}else if(H % 2 == 0 && W % 2 == 1){
			for(int i = 0; i < H / 2; i++) num.add(2);
			for(int i = 0; i < (sum - H) / 4; i++) num.add(4);
		}else{
			num.add(1);
			for(int i = 0; i < (W - 1) / 2; i++) num.add(2);
			for(int i = 0; i < (H - 1) / 2; i++) num.add(2);
			for(int i = 0; i < (sum - H - W + 1) / 4; i++) num.add(4);
		}

		for(int i = num.size()-1; i >= 0; i--){
			if(pq.isEmpty()){
				out.println("No");
				return;
			}

			int m = pq.remove();
			m -= num.get(i);
			if(m < 0){
				out.println("No");
				return;
			}else if(m != 0){
				pq.add(m);
			}
		}
		out.println("Yes");
	}

