public class Main {
    static ContestScanner in;
    static Writer out;
    public static void main(String[] args) {
        Main main = new Main();
        try {
            in = new ContestScanner();
            out = new Writer();
            main.solve();
            out.close();
            in.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    void solve() throws IOException {
        int h = in.nextInt();
        int w = in.nextInt();
        char[][] map = new char[h][];
        int[] alp = new int[26];
        for (int i = 0; i < h; i++) {
            map[i] = in.nextToken().toCharArray();
            for (int j = 0; j < w; j++) {
                alp[map[i][j] - 'a']++;
            }
        }
        int four = (h/2) * (w/2);
        int one = h % 2 == 1 && w % 2 == 1 ? 1 : 0;
        int two = (h % 2) * (w / 2) + (w % 2) * (h / 2);
        for (int i = 0; i < 26; i++) {
            int minus = Math.min(alp[i] / 4, four);
            four -= minus;
            alp[i] -= minus * 4;
        }

        for (int i = 0; i < 26; i++) {
            int minus = Math.min(alp[i] / 2, two);
            two -= minus;
            alp[i] -= minus * 2;
        }

        for (int i = 0; i < 26; i++) {
            int minus = Math.min(alp[i], one);
            one -= minus;
            alp[i] -= minus * 1;
        }

        if(four == 0 && two == 0 && one == 0) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

}

