		int[] cnt = new int[26];
		for (int i = 0; i < h; i++) {
			a[i] = sc.next().toCharArray();
			for (char c : a[i]) {
				cnt[c - 'a']++;
			}
		}

		int cnt4 = (h / 2 * 2) * (w / 2 * 2);

		int cnt2;
		int odd;
		if (h % 2 == 0 && w % 2 == 0) {
			cnt2 = 0;
			odd = 0;
		} else if (h % 2 == 1 && w % 2 == 1) {
			cnt2 = (h / 2 * 2) + (w / 2 * 2);
			odd = 1;
		} else if (h % 2 == 1) {
			cnt2 = w;
			odd = 0;
		} else {
			cnt2 = h;
			odd = 0;
		}

		for (int i = 0; i < 26; i++) {
			int tmp = Math.min(cnt4, cnt[i] / 4 * 4);;
			cnt[i] -= tmp;
			cnt4 -= tmp;
		}

		for (int i = 0; i < 26; i++) {
			int tmp = Math.min(cnt2, cnt[i] / 2 * 2);;
			cnt[i] -= tmp;
			cnt2 -= tmp;
		}

		int sum = 0;
		for (int i = 0; i < 26; i++) {
			sum += cnt[i];
		}

		if (sum == odd) {
			pr.println("Yes");
		} else {
			pr.println("No");
		}
	}

