		if(h%2==1 && w%2==1){
			one = 1;
		}
		else if(h%2==1){
			two = w;
		}
		else if(w%2==1){
			two = h;
		}
		if(Math.min(h,w)==1){
			two = Math.max(h,w)/2;
		}
		int four = h*w-2*two-one;
		//System.out.println(four+" "+two+" "+one);
		for(int i=0;i<26;i++){
			if(counter[i]>=4){
				counter[i] -= 4;
				i--;
