		STRS(h).flatMapToInt(String::chars)
				.map(i->i-'a')
				.forEach(i->++c[i]);
		int one=(h%2)*(w%2);

		int two=(w%2==1?h/2*2:0)+(h%2==1?w/2*2:0);
		int four=h*w-one-two;

