public class Hello
{
    public static void Main()
    {
        var d = new Dictionary<char, int>();
        string[] line = Console.ReadLine().Trim().Split(' ');
        var h = int.Parse(line[0]);
        var w = int.Parse(line[1]);
        for (int i = 0; i < h; i++)
        {
            var s = Console.ReadLine().Trim();
            for (int j = 0; j < w; j++)
                if (d.ContainsKey(s[j])) d[s[j]]++;
                else d[s[j]] = 1;
        }
        var a = new int[d.Count()];
        var p = 0;
        foreach (var x in d) a[p++] = x.Value;
        var kg = 0;
        if (h % 2 == 0) kg++;
        if (w % 2 == 0) kg++;
        bool ret;
        if (kg == 2) ret = checkGG(a);
        else if (kg == 1) ret = checkKG(h, w, a);
        else ret = checkKK(h, w, a);
        Console.WriteLine(ret ? "Yes" : "No");
    }
    public static bool checkKK(int h, int w, int[] a)
    {
        if (h == 1 && w == 1) return true;
        var c4 = 0;
        for (int i = 0; i < a.Length; i++)
            while (true)
            {
                if (a[i] - 4 >= 0) { a[i] -= 4; c4++; }
                else break;
            }
        var c2 = 0;
        for (int i = 0; i < a.Length; i++)
            while (true)
            {
                if (a[i] - 2 >= 0) { a[i] -= 2; c2++; }
                else break;
            }
        if (h == 1 | w == 1)
        {
            c2 += 2 * c4;
            return c2 == h / 2 + w / 2;
        }
        else
        {
            var ww = h / 2 + w / 2 - 1;
            if (c4 >= ww) c2 += (c4 - ww) * 2;
            else return false;
            return c2 == h / 2 + w / 2;
        }
    }
    public static bool checkKG(int h, int w, int[] a)
    {
        var c4 = 0;
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] % 2 == 1) return false;
            while (true)
            {
                if (a[i] - 4 >= 0) { a[i] -= 4; c4++; }
                else break;
            }
        }
        var zc4 = h / 2 + w / 2 - 1;
        return c4 >= zc4;
    }
    public static bool checkGG(int[] a)
    {
        for (int i = 0; i < a.Length; i++)
            if (a[i] % 4 != 0) return false;
        return true;
    }
}

