namespace AtCoder
{
    class Program
    {
        static bool Count(int[] values, int num, int step)
        {
            for (int i = 0; i < 26 && num > 0; ++i)
            {
                while (values[i] >= step && num > 0)
                {
                    values[i] -= step;
                    --num;
                }
            }
            return num == 0;
        }
        static bool Solve(int H, int W, string[] A)
        {
            var values = new int[26];
            foreach (string a in A)
            {
                foreach (char c in a)
                {
                    ++values[c - 'a'];
                }
            }
            if (!Count(values, (H / 2) * (W / 2), 4)) { return false; }
            if (!Count(values, (H / 2) * (W % 2), 2)) { return false; }
            if (!Count(values, (H % 2) * (W / 2), 2)) { return false; }
            if (!Count(values, (H % 2) * (W % 2), 1)) { return false; }
            return values.Sum() == 0;
        }
        static void Main(string[] args)
        {
            int[] V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
            int H = V[0];
            int W = V[1];
            var A = new string[H];
            for (int i = 0; i < H; ++i) { A[i] = Console.ReadLine(); }
            Console.WriteLine(Solve(H, W, A) ? "Yes" : "No");
        }
    }
}

