public class C
{
	public static void Main()
	{
		int H = GetInt();
		int W = GetInt();
		int[] num = new int[26];
		for(int i = 0; i < H; i++)
		{
			string a = GetString();
			for(int j = 0; j < W; j++)
				num[(int)(a[j] - 'a')]++;
		}

		int g1 = ((H % 2 == 1) && (W % 2 == 1)) ? 1 : 0;
		int g2 = ((H % 2 == 1) ? W / 2 : 0) + ((W % 2 == 1) ? H / 2 : 0);
		int g4 = (H * W - g1 - 2 * g2) / 4;

		if(g1 == 1)
		{
			int c = Array.FindIndex(num, x => x % 2 == 1);
			if(c != -1)
				num[c]--;
		}

		while(g2 > 0)
		{
			int c = Array.FindIndex(num, x => x % 4 == 2);
			if(c == -1)
			{
				g4 += g2 / 2;
				break;
			}
			else
			{
				num[c] -= 2;
				g2--;
			}
		}

		while(g4 > 0)
		{
			int c = Array.FindIndex(num, x => x > 0);
			if(c == -1)
			{
				break;
			}
			else
			{
				num[c] -= 4;
				g4--;
			}
		}

		Console.WriteLine(num.Any(x => x > 0) ? "No" : "Yes");
	}
}


