static class Extentions
{
    public static int DivCeil(int l, int r) => l / r + (l % r == 0 ? 0 : 1);
}

#endregion

static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var h = io.I;
        var w = io.I;
        var a = new char[h][];
        var c = new int['z' - 'a' + 1];

        for (var i = 0; i < h; i++) a[i] = io.S.ToCharArray();

        for (var i = 0; i < h; i++)
            for (var j = 0; j < w; j++) c[a[i][j] - 'a']++;

        var k = c.Count(x => x > 0);

        if (k > DivCeil(h, 2) * DivCeil(w, 2))
        {
            io.Write("No");
            return;
        }

        var t0 = 0;
        if (h % 2 != 0) t0++;
        if (w % 2 != 0) t0++;

        var t1 = DivCeil(h, 2) * DivCeil(w, 2);
        var t2 = DivCeil(t1, 2);

        var q = c.Where(x => x > 0 && x % 4 == 0);
        var even = c.Where(x => x > 0 && x % 4 != 0 && x % 2 == 0);
        var odd = c.Where(x => x > 0 && x % 2 != 0);

        if (t0 == 0)
        {
            if (q.Sum() == h * w && q.Count() <= t1 && even.Count() == 0 && odd.Count() == 0) io.Write("Yes");
            else io.Write("No");
        }
        if (t0 == 1)
        {
            if (q.Sum() + even.Sum() == h * w && q.Count() <= t2 && even.Count() <= t2 && odd.Count() == 0) io.Write("Yes");
            else io.Write("No");
        }
        if (t0 == 2)
        {
            if (q.Count() <= t2 && even.Count() <= t2 && odd.Count() == 1) io.Write("Yes");
            else io.Write("No");
        }
    }
}

