public class Prog
{
    private const int INF = 1000000007;
    public struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {
        int H = NextInt();
        int W = NextInt();
        Dictionary<char, int> d = new Dictionary<char, int>();
        for (int i = 0; i < H; i++)
        {
            foreach (var c in NextString())
            {
                if (!d.ContainsKey(c)) d[c] = 0;
                d[c]++;
            }
        }
        if (H % 2 == 0 && W % 2 == 0)
        {
            //必ず上下左右の回文に使われるので4つないといけない
            Console.WriteLine(d.All(v => v.Value % 4 == 0) ? "Yes" : "No");
        }
        else if (H % 2 == 1 && W % 2 == 1)
        {
            //中心が1つ、中心を通る文字は2個あってもよい
            //(H-1)/2個+(W-1)/2個までok
            if (d.Count(v => v.Value % 2 == 1) > 1)
            {
                Console.WriteLine("No");
                return;
            }
            int two_c = 0;
            foreach (var e in d)
                if (e.Value % 4 != 0 && e.Value % 2 == 0) two_c++;
            Console.WriteLine(two_c <= (H + W) / 2 - 1 ? "Yes" : "No");
        }
        else
        {
            //奇数列の中央は横回文1度しか使わないため2個でもよい
            //2個が許されるのは偶数/2個まで
            if (d.Count(v => v.Value % 2 == 1) > 1)
            {
                Console.WriteLine("No");
                return;
            }
            int two_c = 0;
            foreach (var e in d)
                if (e.Value % 4 != 0 && e.Value % 2 == 0) two_c++;
            if (H % 2 == 0)
            {
                int tmp = H;
                H = W;
                W = tmp;
            }
            Console.WriteLine(two_c <= (W / 2) ? "Yes" : "No");
        }
    }
    public static void Main()
    {
        var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
}

