class Program
{
    static void Main(string[] args)
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var count = new int[26];
        for (int i = 0; i < H; i++)
        {
            var S = sc.ReadStr();
            foreach (var c in S)
            {
                count[c - 'a']++;
            }
        }
        var c4 = (H / 2) * (W / 2);
        var c2 = 0;
        if (H % 2 == 1) c2 += W / 2;
        if (W % 2 == 1) c2 += H / 2;

        for (int i = 0; i < c4; i++)
        {
            var ok = false;
            for (int j = 0; j < count.Length; j++)
            {
                if (count[j] >= 4)
                {
                    count[j] -= 4;
                    ok = true;
                    break;
                }
            }
            if (ok == false)
            {
                Console.WriteLine("No");
                return;
            }
        }
        for (int i = 0; i < c2; i++)
        {
            var ok = false;
            for (int j = 0; j < count.Length; j++)
            {
                if (count[j] >= 2)
                {
                    count[j] -= 2;
                    ok = true;
                    break;
                }
            }
            if (ok == false)
            {
                Console.WriteLine("No");
                return;
            }
        }
        Console.WriteLine("Yes");
    }
    static Scanner sc = new Scanner();
}

