			var k = 1;
			Comparison<int> comp = (i, j) =>
			{
				if (r[i] != r[j]) return r[i] - r[j];
				var a = i + k <= N ? r[i + k] : -1;
				var b = j + k <= N ? r[j + k] : -1;
				return a - b;
			};
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
