using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static void Main()
    {
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int h = vals[0];
        int w = vals[1];

        var countsDict = new Dictionary<char, int>();
        for (int i = 0; i < h; i++)
        {
            foreach (var c in Console.ReadLine())
            {
                if (!countsDict.ContainsKey(c))
                {
                    countsDict[c] = 1;
                }
                else
                {
                    countsDict[c]++;
                }
            }
        }

        int fourSets = (w / 2) * (h / 2);
        int twoSets = (w % 2) * (h / 2) + (h % 2) * (w / 2);
        int oneSets = h * w - (fourSets * 4 + twoSets * 2);

        var counts = countsDict.Select(kv => kv.Value).OrderByDescending(v => v).ToList();
        foreach (var i in counts)
        {
            var v = i;
            if (v >= 4 && fourSets > 0)
            {
                var f = Math.Min(v / 4, fourSets);
                fourSets -= f;
                v -= f * 4;
            }
            if (v >= 2 && twoSets > 0)
            {
                var t = Math.Min(v / 2, twoSets);
                twoSets -= t;
                v -= t * 2;
            }
            if (v >= 1 && oneSets > 0)
            {
                oneSets--;
                v--;
            }
            if (v > 0)
            {
                Console.WriteLine("No");
                return;
            }
        }


        Console.WriteLine("Yes");
    }
}

