    public static bool checkKK(int h, int w, int[] a)
    {
        if (h == 1 && w == 1) return true;
        var c4 = 0;
        var c2 = 0;
        for (int i = 0; i < a.Length; i++)
        {
            c4 += a[i] / 4;
            a[i] %= 4;
            c2 += a[i] / 2;
            a[i] %= 2;
        }
        if (h == 1 | w == 1)
        {
            c2 += 2 * c4;
            return c2 == h / 2 + w / 2;
        }
        else
        {
            var ww = (h * w - (h + w - 1)) / 4;
            if (c4 >= ww) c2 += (c4 - ww) * 2;
            else return false;
            var ww2 = (h + w - 1) / 2;
            return c2 == ww2;
        }
    }
    public static bool checkKG(int h, int w, int[] a)
    {
        var c4 = 0;
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] % 2 == 1) return false;
            c4 += a[i] / 4;
            a[i] %= 4;
        }
        int zc4;
        if (h % 2 == 0) zc4 = (h * w - h) / 4;
        else zc4 = (h * w - w) / 4;
        return c4 >= zc4;
    }
    public static bool checkGG(int[] a)
    {
        for (int i = 0; i < a.Length; i++)
            if (a[i] % 4 != 0) return false;
        return true;
    }
}

