class Program
{
    static void Main(string[] args)
    {
        //Solve();
        WriteLine(Solve());
    }
    static string Solve()
    {
        var hw = Input.ar;
        var gred = Input.gred(hw[0]);
        var dic = new Dictionary<char, int>();
        for (var i = 0; i < Input.Alfa.Length; i++)
            dic[Input.Alfa[i]] = 0;
        for (var i = 0; i < hw[0]; i++)
            for (var j = 0; j < hw[1]; j++)
                dic[gred[i][j]]++;
        var ct = new[] { 0, 0, 0 };//4,2,1
        if (hw[0] % 2 == 0 && hw[1] % 2 == 0)
            ct[0] = hw[0] * hw[1] / 4;
        else if (hw[0] % 2 == 1 && hw[1] % 2 == 1)
        {
            ct[0] = (hw[0] / 2) * (hw[1] / 2);
            ct[1] = hw[0] / 2 + hw[1] / 2;
            ct[2] = 1;
        }
        else
        {
            ct[0] = (hw[0] / 2) * (hw[1] / 2);
            if (hw[0] % 2 == 0)
                ct[1] = hw[0] / 2;
            else ct[1] = hw[1] / 2;
        }
        var ar = new[] { 4, 2, 1 };
        foreach (var val in dic.Values)
        {
            var n = val;
            for (var j = 0; j < 3; j++)
                if (n / ar[j] > ct[j])
                {
                    n -= ct[j] * ar[j];
                    ct[j] = 0;
                }
                else
                {
                    ct[j] -= n / ar[j];
                    n %= ar[j];
                }
            if (n != 0) return "No";
        }
        return "Yes";
    }
}

