using System;
using System.Collections.Generic;
class Program{
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		var hs=new Dictionary<char,int>();
		string ans="No";
		for(int i=0;i<s[0];i++){
			string q=Console.ReadLine();
			for(int j=0;j<s[1];j++){
				if(hs.ContainsKey(q[j])){hs[q[j]]++;}
				else{hs.Add(q[j],1);}
			}
		}
		int a=0,b=0;
		foreach(KeyValuePair<char,int> e in hs){
			if(e.Value%2==1){
				a++;
				if((e.Value-1)%4!=0){b++;}
			}
			else if(e.Value%4!=0){b++;}
		}
		if(s[0]%2==0&&s[1]%2==0){
			if(a==0&&b==0){ans="Yes";}
		}
		else if(s[0]%2==1&&s[1]%2==1){
			if(a>=1&&b<=s[0]/2+s[1]/2){ans="Yes";}
		}
		else if(a==0){
			if(s[0]%2==1&&b<=s[1]/2+1){ans="Yes";}
			else if(s[1]%2==1&&b<=s[0]/2+1){ans="Yes";}
		}
		Console.WriteLine("{0}",ans);
	}
}

