public class Program
{

	public void Proc()
	{
        int[] inpt = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        this.RowCount = inpt[0];
        this.ColCount = inpt[1];

        Dictionary<char, int> cnt = new Dictionary<char, int>();
        for (int i = 0; i < RowCount; i++) {
            string tmp = Reader.ReadLine();
            for (int j = 0; j < tmp.Length; j++) {
                if(cnt.ContainsKey(tmp[j])) {
                    cnt[tmp[j]]++;
                } else {
                    cnt[tmp[j]] = 1;
                }
            }
        }

        bool ans = Judge(cnt, new char[this.RowCount, this.ColCount]);
        string ansText = ans ? "Yes" : "No";
        Console.WriteLine(ansText);

    }

    private int RowCount;
    private int ColCount;
    private bool Judge(Dictionary<char, int> charList, char[,] map) {

        if(charList.Max(a=>a.Value) == 0) {
            return true;
        }

        int currentRow = -1;
        int currentCol = -1;
        for (int i = 0; i < RowCount; i++) {
            for (int j = 0; j < ColCount; j++) {
                if(map[i,j] == 0) {
                    currentRow = i;
                    currentCol = j;
                    break;
                }
            }
            if(currentRow >= 0) {
                break;
            }

        }

        int subRow = RowCount - currentRow - 1;
        int subCol = ColCount - currentCol - 1;
        char[] keys = charList.Where(a => a.Value > 0).Select(a => a.Key).ToArray();
        foreach(char next in keys) {
            if(subRow != currentRow && subCol != currentCol) {
                if(charList[next] < 4) {
                    continue;
                }
                map[currentRow, currentCol] = next;
                map[currentRow, subCol] = next;
                map[subRow, currentCol] = next;
                map[subRow, subCol] = next;
                charList[next] -= 4;
                if(Judge(charList, map)) {
                    return true;
                }
				map[currentRow, currentCol] = (char)0;
				map[currentRow, subCol] = (char)0;
				map[subRow, currentCol] = (char)0;
				map[subRow, subCol] = (char)0;
				charList[next] += 4;
			} else if(subRow != currentRow) {
                if(charList[next] < 2) {
                    continue;
                }
				map[currentRow, currentCol] = next;
				map[subRow, currentCol] = next;
				charList[next] -= 2;
				if (Judge(charList, map))
				{
					return true;
				}
				map[currentRow, currentCol] = (char)0;
				map[subRow, currentCol] = (char)0;
				charList[next] += 2;
			} else if(subCol != currentCol) {
                if(charList[next] <2 ) {
                    continue;
                }
				map[currentRow, currentCol] = next;
				map[currentRow, subCol] = next;
				charList[next] -= 2;
				if (Judge(charList, map))
				{
					return true;
				}
				map[currentRow, currentCol] = (char)0;
				map[currentRow, subCol] = (char)0;
				charList[next] += 2;
			} else {
				map[currentRow, currentCol] = next;
				charList[next] -= 1;
				if (Judge(charList, map))
				{
					return true;
				}
				map[currentRow, currentCol] = (char)0;
				charList[next] += 1;
			}
        }

        return false;

    }


