public sealed partial class Program
{
    int h, w;
    int[] ks = new int[26];

    bool Solve()
    {
        var he = h % 2 == 0;
        var we = w % 2 == 0;
        var ls = ks.Where(k => k % 4 != 0).ToArray();

        if (he && we)
        {
            // h, w: 偶数
            return !ls.Any();

        }
        else if (he || we)
        {
            // h, w: 片方が偶数、他方が奇数
            var c = (he ? h : w) / 2;
            return ls.All(k => k % 2 == 0) && ls.Length <= c;
        }
        else
        {
            // h, w: 両方奇数
            var b = (h - 1 + w - 1) / 2;
            return
                ls.Count(k => k % 2 != 0) == 1
                && ls.Count(k => k % 4 == 2 || k % 4 == 3) <= b;
        }
    }

    void Read()
    {
        var a = scanner;

        h = a.N();
        w = a.N();

        for (var i = 0; i < h; i++)
        {
            var line = input.ReadLine();
            foreach (var c in line)
            {
                ks[c - 'a']++;
            }
        }
    }

    public void EntryPoint()
    {
        Read();
        WriteLine(Solve() ? "Yes" : "No");
    }
}

