        }
        static void Solve()
        {
             h = Input.NextInt();
             w = Input.NextInt();
            var a = new string[h];
            for(int i=0;i<h;++i)
            {
                a[i] = Input.Next();
            }

            var dicGroup = new Dictionary<int, int>();
            dicGroup.Add(1, 0);
            dicGroup.Add(2, 0);
            dicGroup.Add(4, 0);
            if( h % 2 == 1 && w % 2 == 1) {
                dicGroup[1] = 1;
                dicGroup[2] = (int)Math.Floor((double)h / 2) + (int)Math.Floor((double)w / 2);
                dicGroup[4] = (int)Math.Floor((double)h / 2) * (int)Math.Floor((double)w / 2);

            }else if( h % 2 == 0 && w % 2 == 0)
            {
                dicGroup[4] = (h / 2) * (w / 2);
            }
            else
            {
                if( w % 2 == 0) { Swap(ref h, ref w); }
                // h が偶数
                dicGroup[2] = (int)Math.Floor((double)h / 2);
                dicGroup[4] = (int)Math.Floor((double)h / 2) * (int)Math.Floor((double)w / 2);
            }

            var dicC = new Dictionary<char, int>();
            foreach(var s in a)
            {
                for(int i=0;i<s.Length;++i)
                {
                    if (!dicC.ContainsKey(s[i]))
                    {
                        dicC.Add(s[i], 0);
                    }
                    dicC[s[i]]++;
                }
            }
            for(int i=0;i<dicGroup[1];++i)
            {
                foreach(var kv in dicC)
                {
                    if(kv.Value % 4 == 1 || kv.Value % 4 == 3)
                    {
                        dicC[kv.Key]--;
                        break;
                    }
                }
            }
            for(int i=0;i<dicGroup[2];++i)
            {
                foreach(var kv in dicC)
                {
                    if( kv.Value % 4 == 2)
                    {
                        dicC[kv.Key] -= 2;
                        break;
                    }
                }
            }
            for(int i=0;i<dicGroup[4];++i)
            {
                foreach(var kv in dicC)
                {
                    if(kv.Value != 0 && kv.Value % 4 == 0)
                    {
                        dicC[kv.Key] -= 4;
                        break;
                    }
                }
            }
            bool valid = true;
            foreach(var kv in dicC)
            {
                if( kv.Value >= 1)
                {
                    valid = false;
                    break;
                }
            }
            var ans = valid ? "Yes" : "No";
