        long two = (H % 2 == 0 ? 0 : W) + (W % 2 == 0 ? 0 : H) - 2 * one;
        long four = (H * W - one - two) / 4;
        two /= 2;

        var Sorted = dic.OrderBy((x) => x.Value);
        var ans = true;

        var a = 0L;
        var b = 0L;
        var c = 0L;

        foreach (var item in Sorted)
        {
            var res = item.Value;
            a += res / 4;
            b += (res % 4) / 2;
            c += ((res % 4) % 2);
        }

        if (four <= a)
        {
            a -= four;
            b += a / 2;
        }
        else
        {
            ans = false;
        }

        if (two <= b)
        {
            b -= two;
            c += b / 2;
        }
        else
        {
            ans = false;
        }

        if (c != one)
        {
            ans = false;
        }
        Console.WriteLine(ans ? "Yes" : "No");
    }



}

