    for(int i = 0; i < characters.Count()-1; i++)
    {
      if(characters[i] == characters[i+1])
      {
      count++;
        if(i == characters.Count()-2) numbers.Add(count);
      }
      else
      {
        numbers.Add(count);
        if(i == characters.Count()-2) numbers.Add(1);
        count = 1;
      }
    }
    numbers = numbers.Sort();



    int oddNum = 0;//奇数の個数
    for(int i = 0; i < numbers.Count(); i++)
    {
      if(numbers[i] % 2 == 1) oddNum++;
      numbers[i] = numbers[i]-1;
    }

    int secondNum = 0;//2(mod4)の個数
    for(int i = 0; i < numbers.Count(); i++)
    {
      if(numbers[i] % 4 == 2) secondNum++;
      numbers[i] = numbers[i]-2;
    }

