    {
        if(oddNum >= 1) answer = false;
    }

    else if((h == 1 && w % 2 == 1)||(w == 1 && h % 2 == 1))
    {
      if(oddNum >= 2) answer = false;
    }

    else if(h % 2 == 0 && w % 2 == 0)
    {
      if(oddNum >= 1 || secondNum >= 1) answer = false;
    }

    else if(h % 2 == 0 && w % 2 == 1)
    {
      if(oddNum >= 1 || secondNum > h) answer = false;
    }

    else if(h % 2 == 1 && w % 2 == 0)
    {
      if(oddNum >= 1 || secondNum > w) answer = false;
    }

    else if(h % 2 == 1 && w % 2 == 1)
    {
      if(oddNum >= 2 || secondNum > h/2+w/2) answer = false;
    }

    Console.WriteLine(answer ? "Yes" : "No");

	}
}

