			c4 = H * W;
			c2 = c1 = 0;
		}
		else if(H % 2 == 1 && W % 2 == 0)
		{
			c2 = W;
			c4 = H * W - W;
			c1 = 0;
		}
		else if(H % 2 == 0 && W % 2 == 1)
		{
			c2 = H;
			c4 = H * W - H;
			c1 = 0;
		}
		else
		{
			c2 = H + W - 2;
			c4 = H * W - (H + W - 1);
			c1 = 1;
		}

		for(int i=0; i<26; i++)
		{
			while(count[i] >= 4 && c4 >= 4)
			{
				count[i] -= 4;
				c4 -= 4;
			}
		}
		if(c4 != 0)
