            io.ini(out A, H);
            var aa = new AssociativeArray<char>();
            for (int i = 0; i < H; ++i) {
                for (int j = 0; j < W; ++j) {
                    aa.Add(A[i][j]);
                }
            }

            var a2 = aa.dic.ToDictionary(kp => kp.Key, kp => kp.Value % 4);

            if (!H.Odd() && W.Odd()) {
                if (a2.Where(kp => kp.Value.Odd()).Count() > 0 || a2.Where(kp => kp.Value == 2).Count() > H / 2) {
                    io.o("No");
                    return;
                } else {
                    io.o("Yes");
                    return;
                }
            }
            if (H.Odd() && !W.Odd()) {
                if (a2.Where(kp => kp.Value.Odd()).Count() > 0 || a2.Where(kp => kp.Value == 2).Count() > W / 2) {
                    io.o("No");
                    return;
                } else {
                    io.o("Yes");
                    return;
                }
            }
            if (H.Odd() && W.Odd()) {
                if (a2.Where(kp => kp.Value.Odd()).Count() > 1||a2.Where(kp=>kp.Value==2).Count()>(H+W-2)/2) {
                    io.o("No");
                    return;
                } else {
                    io.o("Yes");
                    return;
                }
            }
            if (!a2.All(kp=>kp.Value==0)) {
                io.o("No");
                return;
            } else {
                io.o("Yes");
                return;
            }

        }

