            {
                fNum += d.Value / 4;
                tNum += (d.Value % 4) / 2;
                oNum += d.Value % 2;
            }
            var fNeed = (H / 2) * (W / 2);
            var tNeed = (H % 2) * (W / 2) + (W % 2) * (H / 2);
