class Program
{
	static void Main()
	{
	string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
	int h = int.Parse(input[0]);
	int w = int.Parse(input[1]);
	string s = Console.ReadLine();

    List<char> characters = new List<char>();
    List<int> numbers = new List<int>();//文字の数一覧
    for(int i = 0; i < h; i++)
    {
    char[] nums = char.Parse(Console.ReadLine().Split(''));
      for(int j = 0; j < nums.Length; j++) characters.Add(nums[j]);
    }
    characters = characters.OrderBy();//並び替え

    int count = 1;//文字数を数える
    for(int i = 0; i < characters.Count()-1; i++)
    {
      if(characters[i] == characters[i+1])
      {
      count++;
        if(i == characters.Count()-2) numbers.Add(count);
      }
      else
      {
        numbers.Add(count);
        if(i == characters.Count()-2) numbers.Add(1);
        count = 1;
      }
    }
    numbers = numbers.OrderBy();



    int oddNum = 0;//奇数の個数
    for(int i = 0; i < numbers.Count(); i++)
    {
      if(numbers[i] % 2 == 1) oddNum++;
      numbers[i] = numbers[i]-1;
    }

    int secondNum = 0;//2(mod4)の個数
    for(int i = 0; i < numbers.Count(); i++)
    {
      if(numbers[i] % 4 == 2) secondNum++;
      numbers[i] = numbers[i]-2;
    }

    bool answer = true;

    if((h == 1 && w % 2 == 0)||(w == 1 && h % 2 == 0))
    {
        if(oddNum >= 1) answer = false;
    }

    else if((h == 1 && w % 2 == 1)||(w == 1 && h % 2 == 1))
    {
      if(oddNum >= 2) answer = false;
    }

    else if(h % 2 == 0 && w % 2 == 0)
    {
      if(oddNum >= 1 || secondNum >= 1) answer = false;
    }

    else if(h % 2 == 0 && w % 2 == 1)
    {
      if(oddNum >= 1 || secondNum > h) answer = false;
    }

    else if(h % 2 == 1 && w % 2 == 0)
    {
      if(oddNum >= 1 || secondNum > w) answer = false;
    }

    else if(h % 2 == 1 && w % 2 == 1)
    {
      if(oddNum >= 2 || secondNum > h/2+w/2) answer = false;
    }

    Console.WriteLine(answer ? "Yes" : "No");

	}
}

