namespace CodeFestival2017qualAC
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] ints = Console.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
            int H = ints[0];
            int W = ints[1];

            string[] matrix = new string[H];
            for (int i = 0; i < H; i++)
            {
                matrix[i] = Console.ReadLine();
            }

            int wildCard = 0;
            int pairs = 0;
            if (H % 2 == 1 & W % 2 == 1)
            {
                wildCard = 1;
                pairs = W / 2 + H / 2;
            } else if (H % 2 == 1)
            {
                pairs = W / 2;
            } else if (W % 2 == 1)
            {
                pairs = H / 2;
            }

            int[] counts = new int[26];
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    counts[matrix[i][j] - 'a']++;
                }
            }

            for (int i = 0; i < 26; i++)
            {
                counts[i] %= 4;
                if (counts[i] == 0)
                {
                    continue;
                }

                if (counts[i] == 2)
                {
                    pairs--;
                }

                if (counts[i] % 2 == 1)
                {
                    wildCard--;
                }
            }

            if (pairs < 0 | wildCard < 0)
            {
                Console.WriteLine("No");
                return;
            }
            Console.WriteLine("Yes");
        }
    }
}

