        // 使用する変数をここに書く
        // string S;
        // int a;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            int h = sc.nextInt();
            int w = sc.nextInt();
            string[] a = sc.next(h);
            int[] cnt = new int[26];
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    cnt[a[i][j] - 'a']++;
                }
            }
            int cnt1 = 0;
            int cnt2 = 0;
            int oddcnt = 0;

            if (h % 2 == 1 && w % 2 == 1) cnt1 = 1;
            if (h % 2 == 1) cnt2 += w - 2;
            if (w % 2 == 1) cnt2 += h - 2;


            if (h > 1 && w > 1)
            {
                for (int i = 0; i < 26; i++)
                {
                    if (cnt[i] % 2 == 1)
                    {
                        cnt1--;
                        cnt[i]--;
                    }
                    if (cnt[i] % 4 == 2)
                    {
                        cnt2--;
                        cnt[i] -= 2;
                    }
                }
                for (int i = 0; i < 26; i++)
                {
                    if (cnt2 <= 0) break;
                    int div = cnt[i] / 4;
                    div = Math.Min(cnt2, div);
                    cnt[i] -= 4 * div;
                    cnt2 -= div;
                }
                if (cnt1 == 0 && cnt2 == 0) Console.WriteLine("Yes");
                else Console.WriteLine("No");
            }
            else if(h==1&&w==1)
            {
                Console.WriteLine("Yes");
            }
            else
            {
                for (int i = 0; i < 26; i++)
                {
                    if (cnt[i] % 2 == 1)
                    {
                        cnt1--;
                        cnt[i]--;
                    }
                }
                if (cnt1 == 0) Console.WriteLine("Yes");
                else Console.WriteLine("No");
            }
        }
    }
