public class CompetitiveProgramming
{

  public void Solve()
  {
    var o = Ints;
    var H = o[0];
    var W = o[1];
    var a = new char[H][];
    for (int i = 0; i < H; ++i)
    {
      a[i] = Chars;
    }
    var cnt = new int[26];
    for (int i = 0; i < H; ++i)
    {
      for (int j = 0; j < W; ++j)
      {
        ++cnt[a[i][j] - 'a'];
      }
    }
    if (H % 2 == 0 && W % 2 == 1) Swap(ref H, ref W);
    if (H % 2 == 0 && W % 2 == 0)
    {
      for (int i = 0; i < 26; ++i)
      {
        if (cnt[i] % 4 != 0)
        {
          Write("No");
          return;
        }
      }
      Write("Yes");
    }
    else if (H % 2 == 1 && W % 2 == 0)
    {
      if (cnt.Where(x => x % 4 == 2).Count() > W / 2 || cnt.Where(x => x % 4 == 1).Count() > 0 || cnt.Where(x => x % 4 == 3).Count() > 0)
      {
        Write("No");
        return;
      }
      Write("Yes");
    }
    else
    {
      if (cnt.Where(x => x % 4 == 1).Count() == 1)
      {
        if (cnt.Where(x => x % 4 == 3).Count() > 0)
        {
          Write("No");
          return;
        }
        if (cnt.Where(x => x % 4 == 2).Count() <= (H + W - 1) / 2)
        {
          Write("Yes");
          return;
        }
      }
      else if (cnt.Where(x => x % 4 == 3).Count() == 1)
      {
        if (cnt.Where(x => x % 4 == 1).Count() > 0)
        {
          Write("No");
          return;
        }
        if (cnt.Where(x => x % 4 == 2).Count() <= (H + W - 1) / 2 - 1)
        {
          Write("Yes");
          return;
        }
      }
      Write("No");
    }

  }

}



public static class Math2
{
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power(long a, long b, long MOD = 1000000007)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2(long a, long b)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD(long a, long b)
  {
    while (b > 0)
    {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM(long a, long b) => (b / GCD(a, b)) * a;
  public static long Comb(long n, long r, int MOD = 1000000007)
  {
    long ret = 1;
    long x = 1;
    for (long i = n; i >= n - r + 1; --i)
    {
      ret = ret / x * i;
      ret %= MOD;
      x++;
    }
    return ret;
  }
  public static long Comb2(long n, long r)
  {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i)
    {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
}
