    for(int i = 0; i < characters.Count()-1; i++)
    {
      if(characters[i] == characters[i+1])
      {
      count++;
        if(i == characters.Count()-2) numbers.Add(count);
      }
      else
      {
        numbers.Add(count);
        if(i == characters.Count()-2) numbers.Add(1);
        count = 1;
      }
    }



    int oddNum = 0;//奇数の個数
    for(int i = 0; i < numbers.Count(); i++)
    {
