using System.Linq;
using System.Text;

class Program
{
    private int H,W;
    private int[] Count=new int[200];
    public void Solve()
    {
        var l=Console.ReadLine().Split(' ');
        H=int.Parse(l[0]);
        W=int.Parse(l[1]);
        for(int i=0;i<H;i++)
        {
            foreach(char c in Console.ReadLine())
            {
                Count[c]++;
            }
        }

        int two=0,one=0;
        foreach(int i in Count)
        {
            if(i%2==1)
            {
                one++;
            }
            if(i%4==2||i%4==3)
            {
                two++;
            }
        }
        if(H%2==1&&W%2==1)
        {
            if(one!=1)
            {
                Console.WriteLine("No");
                return;
            }
        }
        else
        {
            if(one!=0)
            {
                Console.WriteLine("No");
                return;
            }
        }
        int tt=0;
        if(H%2==1)
        {
            tt+=W/2;
        }
        if(W%2==1)
        {
            tt+=H/2;
        }
        if(two>tt)
        {
            Console.WriteLine("No");
            return;
        }
        if((tt-two)%2==1)
        {
            Console.WriteLine("No");
            return;
        }
        Console.WriteLine("Yes");
    } 

    static void Main()
    {
        new Program().Solve();
    }
}

