        var map = new String[H];
        for (int i = 0; i < H; i++)
        {
            map[i] = Console.ReadLine();
        }

        var dic = new Dictionary<char, long>();
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (dic.ContainsKey(map[i][j]))
                {
                    dic[map[i][j]]++;
                }
                else
                {
                    dic.Add(map[i][j], 1);
                }
            }
        }

        long one = (H * W) % 2 == 0 ? 0 : 1;

        long two = (H % 2 == 0 ? 0 : W) + (W % 2 == 0 ? 0 : H) - 2 * one;
        long four = (H * W - one - two) / 4;
        two /= 2;

        var Sorted = dic.OrderBy((x) => x.Value);
        var ans = true;

        var a = 0L;
        var b = 0L;
        var c = 0L;

        foreach (var item in Sorted)
        {
            var res = item.Value;
            a += res / 4;
            b += (res % 4) / 2;
            c += ((res % 4) % 2);
        }

        if (four <= a)
        {
            a -= four;
            b += a / 2;
        }
        else
        {
            ans = false;
        }

        if (!(two == b && one == c))
        {
            ans = false;
        }

        if (two <= b)
        {
            b -= two;
            c += b / 2;
        }
        else
        {
            ans = false;
        }

        if (c != one)
        {
            ans = false;
        }
        Console.WriteLine(ans ? "Yes" : "No");
    }



