            if (H % 2 == 0 && W % 2 == 0)
            {
                for (int i = 0; i < cCount.Length; i++)
                {
                    if (cCount[i] % 4 != 0) { Console.WriteLine("No"); return; }
                }
                Console.WriteLine("Yes"); return;
            }

            //両方が奇数
            if (H % 2 != 0 && W % 2 != 0)
            {
                for (int i = 0; i < cCount.Length; i++)
                {
                    cCount[i] %= 4;
                }

                int ecount = 0;
                int ocount = 0;
                for (int i = 0; i < cCount.Length; i++)
                {
                    if (cCount[i] != 0 && cCount[i] % 2 == 0) ecount++;
                    else if (cCount[i] % 2 != 0) ocount++;
