                for (int i = 0; i < cCount.Length; i++)
                {
                    cCount[i] %= 4;
                }

                int count = 0;
                for (int i = 0; i < cCount.Length; i++)
                {
                    if (cCount[i] != 0 && cCount[i] % 2 == 0) count++;
                    else if (cCount[i] % 2 != 0) { Console.WriteLine("No"); return; }
                }

                if (H % 2 == 0 && count <= H / 2)
                {
                    Console.WriteLine("Yes"); return;
                }
                else if (W % 2 == 0 && count <= W / 2)
                {
                    Console.WriteLine("Yes"); return;
                }
                else
                {
                    Console.WriteLine("No"); return;
                }
            }
        }
    }
