var h, w int
var A [][]rune
var counter, needs [5]int
var memo map[rune]int

func main() {
	h, w = ReadInt(), ReadInt()
	for i := 0; i < h; i++ {
		row := ReadRuneSlice()
		A = append(A, row)
	}

	memo = make(map[rune]int)
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			memo[A[i][j]]++
		}
	}

	needs[4] = (h / 2) * (w / 2)
	if h%2 == 1 {
		needs[2] += w / 2
	}
	if w%2 == 1 {
		needs[2] += h / 2
	}
	if h%2 == 1 && w%2 == 1 {
		needs[1] = 1
	}

	for _, c := range memo {
		counter[4] += c / 4

		if c%4 == 1 {
			counter[1]++
		} else if c%4 == 2 {
			counter[2]++
		} else if c%4 == 3 {
			counter[1]++
			counter[2]++
		}
	}

	// 余分な4は2に転化させる
	if counter[4] > needs[4] {
		num := counter[4] - needs[4]
		counter[2] += 2 * num
		counter[4] = needs[4]
	}

	if needs[1] == counter[1] && needs[2] == counter[2] && needs[4] == counter[4] {
