package main

import "fmt"

func main() {
	var h, w int
	fmt.Scan(&h, &w)

	counts := make(map[string]int)
	var a string
	for i := 0; i < h; i++ {
		fmt.Scan(&a)
		for _, c := range a {
			counts[string(c)]++
		}
	}

	var g1, g2 int
	if h%2 == 0 && w%2 == 0 {
		g1 = 0
		g2 = 0
	} else {
		g1 = 1
		g2 = h/2 + w/2
	}

	// g1
	for i := 0; i < g1; i++ {
		for k, v := range counts {
			if v%4 == 1 || v%4 == 3 {
				counts[k]--
				break
			}
		}
	}

	// g2
	for i := 0; i < g2; i++ {
		for k, v := range counts {
			if v > 0 && v%4 == 2 {
				counts[k] -= 2
				break
			}
		}
	}

	// g4
	for k, v := range counts {
		if v > 0 && v%4 == 0 {
			counts[k] = 0
		}
	}

	ans := "Yes"
	for _, v := range counts {
		if v != 0 {
			ans = "No"
			break
		}
	}

	fmt.Println(ans)
}

