  W2 := (H / 2) * (W % 2) + (H % 2) * (W / 2)
  W4 := (H / 2) * (W / 2)
  for i := 0; i < 26; i++ {
    k4 := C[i] / 4
    if W4 < k4 { k4 = W4 }
    W4 -= k4
    C[i] -= 4 * k4
    k2 := C[i] / 2
    if W2 < k2 { k2 = W2 }
    W2 -= k2
    C[i] -= 2 * k2
    k1 := C[i]
    if W1 < k1 { k1 = W1 }
    W1 -= k1
    C[i] -= k1
  }
  ans := "Yes"
  if W4 > 0 || W2 > 0 || W1 > 0 { ans = "No" }
  Write(ans)
  Output()
}

