func solve() {
	h, w := ri(), ri()
	a := ""
	for i := 0; i < h; i++ {
		a += rs()
	}
	alphas := strCountAlphabets(a)

	ct4, ct2, ct1 := 0, 0, 0
	for _, x := range alphas {
		ct4 += x / 4
		x %= 4
		ct2 += x / 2
		x %= 2
		ct1 += x
	}

	check := func() bool {
		if isOdd(h) && isOdd(w) {
			if h == 1 {
				return ct1 <= 1 && ct2*2 <= w-1
			} else if w == 1 {
				return ct1 <= 1 && ct2*2 <= h-1
			}
			return ct1 <= 1 && ct2*2 <= w+h-1
		} else if isOdd(h) {
			return ct1 == 0 && ct2*2 <= w
		} else if isOdd(w) {
			return ct1 == 0 && ct2*2 <= h
		} else {
			return ct4*4 == w*h
		}
	}
	pln(YesOrNo(check()))
}

