func main() {
	defer Flush()

	H := readi()
	W := readi()
	a := make([][]byte, H)
	count := make([]int, 26)
	for i := range a {
		a[i] = readb()
		for j := range a[i] {
			count[int(a[i][j]-'a')]++
		}
	}

	var n4, n2, n1 int

	if H%2 == 1 && W%2 == 1 {
		h, w := H-1, W-1
		n1 = 1
		n2 = h/2 + w/2
		n4 = h / 2 * w / 2
	} else if H%2 == 1 {
		h, w := H-1, W
		n2 = w / 2
		n4 = h / 2 * w / 2
	} else if W%2 == 1 {
		h, w := H, W-1
		n2 = h / 2
		n4 = h / 2 * w / 2
	} else {
		n4 = H / 2 * W / 2
	}

	if n4*4+n2*2+n1 != H*W {
		eprintln(H, W)
		eprintln(n4)
		eprintln(n2)
		eprintln(n1)
		panic("NG")
	}

	sort.Sort(sort.Reverse(sort.IntSlice(count)))

	if 0 < calc(count, n4, 4) {
		println("No")
		return
	}
	if 0 < calc(count, n2, 2) {
		println("No")
		return
	}
	if 0 < calc(count, n1, 1) {
		println("No")
		return
	}
	println("Yes")
}

func calc(count []int, n, d int) int {
	for i := range count {
		v := min(n, count[i]/d)
		n -= v
		count[i] -= d * v
	}
	return n
}

