	"bufio"
	"fmt"
	"os"
)

func main() {
	H, W := ReadInt(), ReadInt()
	m := make(map[int]int)

	for i := 0; i < H; i++ {
		line := ReadString()
		for j := 0; j < W; j++ {
			m[int(line[j])]++
		}
	}

	g1, g2, g4 := 0, 0, 0
	for _, v := range m {
		if v%2 == 1 {
			g1++
		} else if v%4 == 2 {
			g2++
		} else {
			g4++
		}
	}

	if H%2 == 1 && W%2 == 1 {
		g1--
	}
	if g1 > 0 {
		fmt.Println("No")
		return
	}

	if H%2 == 1 {
		g2 -= W / 2
	}
	if W%2 == 1 {
		g2 -= H / 2
	}
	if g2 > 0 {
		fmt.Println("No")
		return
	}

	fmt.Println("Yes")
}

var reader = bufio.NewReader(os.Stdin)

func Scan(a ...interface{}) {
	if _, err := fmt.Fscan(reader, a...); err != nil {
		panic(err)
	}
}
func ReadInt() (i int)       { Scan(&i); return }
func ReadString() (s string) { Scan(&s); return }
func ReadInts(n int) []int {
	v := make([]int, n)
	for i := 0; i < n; i++ {
		Scan(&v[i])
	}
	return v
}

package main

import (
	"bufio"
	"fmt"
