	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

func scanInt() int {
	iv, _ := strconv.Atoi(scanString())
	return iv
}

func scanString() string {
	sc.Scan()
	return sc.Text()
}

func init() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, 100001), 100001*100)
}

func main() {
	h, w := scanInt(), scanInt()
	xm := make(map[rune]int)
	for i := 0; i < h; i++ {
		a := scanString()
		for _, v := range a {
			xm[v]++
		}
	}

	var g1, g2, g4 int
	if h%2 == 1 && w%2 == 1 {
		g1 = 1
	}
	if h%2 == 1 {
		g2 += w / 2
	}
	if w%2 == 1 {
		g2 += h / 2
	}
	g4 = (h / 2) * (w / 2)

	for i := 0; i < g4; i++ {
		for j := range xm {
			if xm[j]%4 == 0 {
				xm[j] -= 4
				break
			}
		}
	}
	for i := 0; i < g2; i++ {
		for j := range xm {
			if xm[j]%4 == 2 {
				xm[j] -= 2
				break
			}
		}
	}
	for i := 0; i < g1; i++ {
		for j := range xm {
			if v := xm[j] % 4; v == 1 || v == 3 {
				xm[j]--
				break
			}
		}
	}

	for _, v := range xm {
		if v != 0 {
			fmt.Println("No")
			return
		}
	}
	fmt.Println("Yes")
}

package main

import "fmt"

func main() {
	var h, w int
	fmt.Scan(&h, &w)

	counts := make(map[string]int)
	var a string
	for i := 0; i < h; i++ {
		fmt.Scan(&a)
		for _, c := range a {
			counts[string(c)]++
		}
	}

	var g1, g2, g4 int
	if h%2 == 0 && w%2 == 0 {
		g4 = h / 2 * w / 2
	} else {
		g1 = 1
		g2 = h/2 + w/2
		g4 = h / 2 * w / 2
	}

	gs := make([]int, 0)
	for i := 0; i < g4; i++ {
		gs = append(gs, 4)
	}
	for i := 0; i < g2; i++ {
		gs = append(gs, 2)
	}
	for i := 0; i < g1; i++ {
		gs = append(gs, 1)
	}

	for _, v := range gs {
		for k, c := range counts {
			if c-v >= 0 {
				counts[k] -= v
			}
		}
	}

	ans := "Yes"
	for _, c := range counts {
		if c > 0 {
			ans = "No"
			break
		}
	}

	fmt.Println(ans)
}

