func scanInt() int {
	sc.Scan()
	a,_ := strconv.Atoi(sc.Text())
	return a
}

func scanInt64() int64 {
	sc.Scan()
	a,_ := strconv.ParseInt(sc.Text(),10,64)
	return a
}

func scanInts(n int) []int {
	res := make([]int, n)
	for i := 0; i < n; i++ { res[i] = scanInt() }
	return res
}

func scanText() string {
	sc.Scan()
	return sc.Text()
}

func printInts(a ...int) {
	for i, e := range a {
		fmt.Fprint(wr, e)
		if i != len(a)-1 { fmt.Fprint(wr, " ") }
	}
	fmt.Fprintln(wr)
	wr.Flush()
}

//=====main=====

func main() {
	sc.Split(bufio.ScanWords)

	h := scanInt()
	w := scanInt()

	a := make([]string, h)
	cnt := make(map[string]int, 0)

	for i := 0; i < h; i++ {
		a[i] = scanText()
		for j := 0; j < w; j++ {
			cnt[string(a[i][j])]++
		}
	}

	chk2 := 0
	chk1 := 0

	if h%2==1 {
		chk2+=w/2
	}

	if w%2==1 {
		chk2+=h/2
	}

	if h%2==1&&w%2==1 {
		chk1=1
	}

	for _, e := range cnt {
		if e%4 != 0 {
			if e%2==0 {
				chk2--
			} else {
				chk1--
			}
		}
	}

	if chk2<0||chk1<0 {
		fmt.Println("No")
	} else {
		fmt.Println("Yes")
	}
}

