	}

	for i := 0; i < g2; i++ {
		for k, v := range counts {
			if v > 0 && v%2 == 0 {
				counts[k] -= 2
				break
			}
		}
	}

	ans := "Yes"
	for _, v := range counts {
		if v != 0 {
			ans = "No"
			break
		}
	}

	fmt.Println(ans)
}

