        auto lhs = this;

        static if (op == "+") {
            lhs.x += rhs.x;
            if (lhs.x >= mod) lhs.x -= mod;
            return lhs;
        }
        static if (op == "-") {
            lhs.x -= rhs.x;
            if (lhs.x < 0) lhs.x += mod;
            return lhs;
        }
        static if (op == "*") {
            (lhs.x *= rhs.x) %= mod;
            return lhs;
