def solve():
    h, w = map(int, input().split())
    al = [input() for _ in range(h)]
    word_dict = Counter(list("".join(al)))

    g1, g2, g4 = 1, int(h/2) + int(w/2), int(h/2) * int(w/2)
    for _ in range(g1):
        key = 0
        for k, v in word_dict.most_common():
            if v % 4 == 1 or v % 4 == 3:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 1

    for _ in range(g2):
        key = 0
        for k, v in word_dict.most_common():
            if v % 4 == 2:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 2

    for _ in range(g4):
        key = 0
        for k, v in word_dict.most_common():
            if v % 4 == 0:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 4

    print("Yes" if len([k for k, v in word_dict.most_common() if v != 0]) == 0 else "No")


