    elif h % 2 == 1 and w % 2 == 0:
        d[1] = 0
        d[2] = w // 2
    elif h % 2 == 0 and w % 2 == 1:
        d[1] = 0
        d[2] = h // 2
    d[4] = (h * w - d[1] - d[2]) // 4

    keys = c.keys()

    if d[1] == 1:
        for key in keys:
            if c[key] % 2 == 1:
                c[key] -= 1
                d[1] -= 1

    if d[2] > 0:
        for key in keys:
            if c[key] % 4 == 2:
