    if H & 1 and W & 1:
        for c in string.ascii_lowercase:
            if counts[c] & 1:
                counts[c] -= 1
                break
        for c in string.ascii_lowercase:
            if counts[c] & 1:
                return False

        cnt = (H + W - 2) // 2
        for c in string.ascii_lowercase:
            if counts[c] % 4:
                counts[c] -= 2
                cnt -= 1
            if cnt < 0:
