            H, W = W, H
        assert H & 1 == 1

        cnt = W // 2
        for c in string.ascii_lowercase:
            if counts[c] % 4:
                counts[c] -= 2
                cnt -= 1
            if cnt < 0:
                return False

    for c in string.ascii_lowercase:
        if counts[c] % 4:
            return False
    return True


