    c.update(s)

def solve(H, W, c):
    ok = True
    if H == W == 1:
        pass
    elif H == 1 or W == 1:
        HW = H * W
        odd_num = sum(1 for x in c.values() if x % 2)
        even_num = HW - odd_num
        # print("odd, even = ", odd_num, even_num)
        if HW % 2 == 1 and odd_num != 1: ok = False
        elif HW % 2 == 0 and odd_num != 0: ok = False
    elif H % 2 == W % 2 == 0:
        # all 4
        for v in c.values():
            if v % 4 != 0:
                ok = False
                break
    elif H % 2 == W % 2 == 1:
        two_num = H + W - 2
        one_num = 1
        four_num = H * W - two_num - one_num
        if not valid(two_num, four_num, one_num, c):
            ok = False
    else:
        if W % 2 == 0:
            two_num = W
        else:
            two_num = H
        four_num = H * W - two_num
        if not valid(two_num, four_num, 0, c):
            ok = False

    return ok

if solve(H, W, c):
    print("Yes")
else:
    print("No")

