def meme(d, rem, val):
    remc = []
    d2 = {}
    for k,v in d.items():
        count = v % val
        remc += [k]*count
        rem -= count
        d2[k] = v - count
    if rem > 0:
        for k,v in d2.items():
           while v >= val and rem > 0:
               v -= val
               rem -= val
               remc += [k]*val
    return (rem, ''.join(remc))

