from heapq import heappop, heappush, heapify


def main():
    h, w = [int(i) for i in input().strip().split()]
    s = ""
    for _ in range(h):
        s += input().strip()
    counts = Counter(s).most_common()
    cands = [-int(i) for v, i in counts]

    def pop(): return -heappop(cands)
    def push(x): return heappush(cands, -x)

    el = []
    while h > 0 and w > 0:
        if h == 1 and w == 1:
            el.append(1)
            h -= 1
            w -= 1
            continue
        elif h == 1 and w > 1:
            el.append(2)
            w -= 2
            continue
        elif w == 1 and h > 1:
            el.append(2)
            h -= 2
            continue

        elif h > 1 and h > 1:
            p = ((h + w) * 2) - 4
            for _ in range(p // 4):
                el.append(4)
            if p % 4 == 2:
                el.append(2)
            h -= 2
            w -= 2

    el = sorted(el)[::-1]
    flag = True
    for e in el:
        c = pop()
        if c < e:
            flag = False
            break
        push(c - e)

    if flag:
        print("Yes")
    else:
        print("No")


