def valid(two_num, four_num, c):
    t = 0
    f = 0
    for k, v in c.items():
        while v > 0:
            if v >= 4:
                f += 1
                v -= 4
            if v >= 2:
                t += 1
                v -= 2
            if v == 1:
                return False
    return f * 4 >= four_num


