from collections import Counter
from math import floor

def solve():
    h, w = map(int, input().split())
    word_dict = dict(Counter(list("".join([input() for _ in range(h)]))))

    g1 = (w % 2) & (h % 2)
    g2 = floor((w % 2) * h/2) + floor((h % 2) * w/2)
    g4 = floor(h/2) * floor(w/2)

    for k, v in word_dict.items():
        if v % 4 == 1 or v % 4 == 3:
            g1 -= 1
            word_dict[k] -= 1
            v -= 1
        if g1 == 0:
            break

    for k, v in word_dict.items():
        while v > 0 and v % 4 == 0:
            g4 -= 1
            word_dict[k] -= 4
            v -= 4
        if g4 == 0:
            break

    for k, v in word_dict.items():
        while v > 0 and v % 4 == 2:
            g2 -= 1
            word_dict[k] -= 2
            v -= 2
        if g2 == 0:
            break

    print("No" if [1 for v in word_dict.values() if v != 0] else "Yes")

if __name__=="__main__":
