    t = 0
    f = 0
    o = 0
    for v in c.values():
        while v > 0:
            if v >= 4:
                f += 1
                v -= 4
            if v >= 2:
                t += 1
                v -= 2
            if v == 1:
                o += 1
                v -= 1
