def main():
    H, W, *A = open(0).read().split()
    H, W, C = int(H), int(W), Counter("".join(A)).values()
    if H % 2 and W % 2:
        g1, g2, g4 = 1, H // 2 + W // 2, H * W // 4
    elif H % 2 or W % 2:
        g1, g2, g4 = 0, H // 2 + W // 2 - 1, H * W // 4
    else:
        g1, g2, g4 = 0, 0, H * W // 4
    for i in C:
        if i % 2 and g1:
            i -= 1
            g1 -= 1
        if i % 2 == 0 and g4:
            x = min(i // 4, g4)
            i -= x * 4
            g4 -= x
            y = min(i // 2, g2)
            i -= y * 2
            g2 -= y
        if i:
            print("No")
            return
    print("Yes")


