    B = []
    for S in A:
        C = [0] * 26
        for c in S:
            C[ord(c)-ord('a')] += 1
        B.append(C)

    if w % 2 == 0:
        if all(all(x % 2 == 0 for x in b) for b in B):
            C = []
        else:
            return 'No'
    else:
        C = [[i for i, x in enumerate(b) if x % 2 != 0] for b in B]
        if all(len(c) == 1 for c in C):
