            gg.update(Counter(g))

        if H % 2 == 0 and W % 2 == 0:
            for i in gg.values():
                if i % 4 != 0:
                    return 'No'
            return 'Yes'
        elif H % 2 == 0 and W % 2 == 1:
            cnt = 0
            for i in gg.values():
                if i % 4 == 2:
                    cnt += 1
                elif i % 4 == 1 or i % 4 == 3:
                    return 'No'

            if cnt <= H and cnt % 2 == 0:
                return 'Yes'
