    sys.setrecursionlimit(10**6)
    input = sys.stdin.readline
    D = defaultdict(int)
    H, W = [int(x) for x in input().strip().split()]
    four_pair = (H // 2) * (W // 2)
    two_pair = H % 2 * W // 2 + W % 2 * H // 2
