def valid(two_num, four_num, one_num, c):
    t = 0
    f = 0
    o = 0
    for v in c.values():
        while v > 0:
            if v >= 4:
                f += 1
                v -= 4
            if v >= 2:
                t += 1
                v -= 2
            if v == 1:
                o += 1
                v -= 1
    if one_num == 1:
        return o == 1 and f * 4 >= four_num
    else:
        return o == 0 and f * 4 >= four_num


