def main():
    h, w = [int(i) for i in input().strip().split()]
    s = ""
    for _ in range(h):
        s += input().strip()
    counts = Counter(s).most_common()
    cands = [int(i) for v, i in counts]
    el = []
    while h > 0 and w > 0:
        if h == 1 and w == 1:
            el.append(1)
            h -= 1
            w -= 1
            continue
        if h == 1 and w > 1:
            el.append(2)
            w -= 2
            continue
        if w == 1 and h > 1:
            el.append(2)
            h -= 2
            continue
        p = ((h + w) * 2) - 4
        for _ in range(p // 4):
            el.append(4)
        if p % 4 == 2:
            el.append(2)
        if h > 1:
            h = h - 2
        else:
            h = h - 1
        if w > 1:
            w -= 2
        else:
            w -= 1

    el = sorted(el)[::-1]
    for e in el:
        for i in range(len(cands)):
            if cands[i] >= e:
                cands[i] -= e
                break
    for c in cands:
        if c > 0:
            print("No")
            return
    print("Yes")
    return


