from collections import Counter
from math import floor

def solve():
    h, w = map(int, input().split())
    al = [input() for _ in range(h)]
    word_dict = Counter(list("".join(al)))

    g1 = 1 if w % 2 == 1 and h % 2 == 1 else 0
    g2 = floor((w % 2) * h/2) + floor((h % 2) * w/2)
    g4 = floor(h/2) * floor(w/2)

    for _ in range(g1):
        key = 0
        for k, v in word_dict.most_common():
            if v % 4 == 1 or v % 4 == 3:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 1

    for _ in range(g2):
        key = 0
        for k, v in word_dict.most_common():
            if v % 4 == 2:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 2

    for _ in range(g4):
        key = 0
        for k, v in word_dict.most_common():
            if v > 0 and v % 4 == 0:
                key = k
                break
        if key is not 0:
            word_dict[key] -= 4

    print("Yes" if len([k for k, v in word_dict.most_common() if v != 0]) == 0 else "No")


if __name__=="__main__":
    solve()

