    g2 = floor((w % 2) * h/2) + floor((h % 2) * w/2)
    g4 = floor(h/2) * floor(w/2)

    for _ in range(g1):
        key = 0
        for k, v in word_dict.items():
            if v % 4 == 1 or v % 4 == 3:
                key = k
                break
        if key != 0:
            word_dict[key] -= 1

    for _ in range(g2):
