        for k, v in word_dict.items():
            if v > 0 and v % 4 == 2:
                key = k
                break
        if key != 0:
            word_dict[key] -= 2

    for _ in range(g4):
        key = 0
        for k, v in word_dict.items():
            if v > 0 and v % 4 == 0:
                key = k
                break
        if key != 0:
            word_dict[key] -= 4

