def alphabetCount(input_lines):
	alphabet = "abcdefghijklmnopqrstuvwxyz"
	counter = [0, 0, 0]
	for i in range(26):
		count = input_lines.count(alphabet[i])
		counter[0] += count // 4
		counter[1] += (count % 4) // 2
		counter[2] += count % 2
	return counter

