def main():
    h, w = map(int, input().split())
    alpha = [0 for _ in range(26)]

    # 各アルファベットの個数を数える
    for i in range(h):
        ai = list(input())

        for aii in ai:
            # アルファベットを数値に変換
            index = ord(aii) - ord('a')
            alpha[index] += 1

    # 回文となる条件
    # 1. hとwがともに偶数：
    # アルファベットの個数が全て4の倍数のとき，Yes
    # 2. hとwのどちらかが偶数：
    # アルファベットの個数が全て2の倍数のとき，Yes
    # 3. hとwがともに奇数：
    # (h - 1) * (w - 1)マス分，アルファベットの個数が4の倍数であり，
    # かつ，1種類を除いて，2の倍数のとき，Yes
    if h % 2 == 0 and w % 2 == 0:
        for a in alpha:
            if a % 4 != 0:
                print('No')
                exit()

        print('Yes')
    elif h % 2 == 0 or w % 2 == 0:
        for a in alpha:
            if a % 2 != 0:
                print('No')
                exit()

        print('Yes')
    else:
        need = (h - 1) * (w - 1)

        for index, a in enumerate(alpha):
            p, q = divmod(a, 4)
            alpha[index] -= min(p * 4, need)
            need -= min(p * 4, need)

            if need == 0:
                break

        count = 0

        for a in alpha:
            if a % 2 == 1:
                count += 1

        if count == 1:
            print('Yes')
        else:
            print('No')


if __name__ == '__main__':
    main()

