fn read_as_vec<T>() -> Vec<T>
where
    T: FromStr,
    <T as FromStr>::Err: Debug,
{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim()
        .split_whitespace()
        .map(|c| T::from_str(c).unwrap())
        .collect()
}

#[allow(dead_code)]
fn read_as_string() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_string()
}

fn main() {
    let line = read_as_vec::<usize>();
    let (h, w) = (line[0], line[1]);
    let mut hash: HashMap<char, usize> = HashMap::new();

    for _ in 0..h {
        let row = read_as_string();
        for c in row.chars() {
            *hash.entry(c).or_insert(0) += 1;
        }
    }

    if h % 2 == 0 && w % 2 == 0 {
        if hash.iter().map(|x| x.1).all(|count| *count % 4 == 0) {
            println!("Yes");
        } else {
            println!("No");
        }
    } else if h % 2 == 1 && w % 2 == 1 {
        if (hash.iter().map(|x| x.1).filter(|x| **x % 4 == 0).count() >= (w / 2) * (h / 2))
            && (hash.iter().map(|x| x.1).filter(|x| **x % 2 != 0).count() == 1)
        {
            println!("Yes");
        } else {
            println!("No");
        }
    } else {
        let rest_row = if w % 2 == 1 { h } else { w };

        if (hash.iter().map(|x| x.1).filter(|x| **x % 4 != 0).count() >= (h * w - rest_row) / 4)
            && (hash.iter().map(|x| x.1).all(|x| *x % 2 == 0))
        {
            println!("Yes");
        } else {
            println!("No");
        }
    }
}

