        }
        // 1xE or Ex1
        while let Some((v, k)) = q.pop() {
            if v < 2 {
                println!("No");
                return;
            }
            if v - 2 > 0 {
                q.push((v - 2, k));
            }
        }
        println!("Yes");
    } else {
        // OxO
        if h == 1 && w == 1 {
            println!("Yes");
        } else if (h == 1 && w != 1) || (h != 1 && w == 1) {
            for _ in 0..std::cmp::max(h, w) / 2 {
                if let Some((v, k)) = q.pop() {
                    if v < 2 {
                        println!("No");
                        return;
                    }
                    if v - 2 > 0 {
                        q.push((v - 2, k));
                    }
                }
            }
            println!("Yes");
        } else {
