fn solve() -> bool {
    let v = read_vec::<usize>();
    let (h, w) = (v[0], v[1]);
    let mut s = Vec::new();
    for _ in 0..h {
        s.push(read::<String>().chars().collect::<Vec<_>>());
    }
    let mut count = vec![0; 26];
    for i in 0..h {
        for &ch in s[i].iter() {
            count[ch.to_digit(36).unwrap() as usize - 10] += 1;
        }
    }
    let mut odd_count = 0;
    let mut even_count = 0;
    for i in 0..26 {
        if count[i] % 2 == 1 {
            odd_count += 1;
        }
        if count[i] % 4 != 0 {
            even_count += 1;
        }
    }
    debug!(odd_count, even_count);
    if h == 1 && w == 1 {
        return true;
    } else if h == 1 || w == 1 {
        return odd_count <= 1;
    }

    if h % 2 == 0 && w % 2 == 0 {
        return odd_count == 0 && even_count == 0;
    } else if h % 2 == 1 && w % 2 == 1 {
        return odd_count == 1 && (even_count <= (h - 1) / 2 + (w - 1) / 2);
    } else if h % 2 == 0 {
        return odd_count == 0 && even_count <= h / 2;
    } else {
        assert!(w % 2 == 0);
        return odd_count == 0 && even_count <= w / 2;
    }
}

