                }
                v.push(c);
            }
        }
        if v.len() <= h as usize {
            println!("Yes");
        } else {
            println!("No");
        }
    } else {
        let mut two = Vec::new();
        let mut one = Vec::new();
        for c in count {
            if c % 4 != 0 {
                if c % 2 == 1 {
                    one.push(c);
                } else {
                    two.push(c);
                }
            }
        }
        if one.len() > 1 || two.len() > h + w - 2 {
