fn main() {
    input! {
        h: usize, w: usize,
        a: [Chars; h]
    }

    let mut c = vec![0usize; 26];
    let ascii_a = 'a' as u8;

    for i in a {
        for j in i {
            c[(j as u8 - ascii_a) as usize] += 1;
        }
    }

    let f = c
        .iter()
        .enumerate()
        .filter(|x| *x.1 == 0)
        .map(|x| c[x.0])
        .count();

    for i in c.iter_mut() {
        *i %= 4;
    }

    if h.is_even() && w.is_even() {
        if f == 26 {
            vis!("Yes");
        } else {
            vis!("No");
        }
    } else if h.is_odd() && w.is_odd() {
        let s = (h - 1) * (w - 1);
        if f >= s && c.iter().map(|x| *x % 2).sum::<usize>() == 1 {
            vis!("Yes");
        } else {
            vis!("No");
        }
    } else {
        let s = (h / 2 * 2) * (w / 2 * 2);
        if f >= s && c.iter().map(|x| *x % 2).all(|x| x == 0) {
            vis!("Yes");
        } else {
            vis!("No");
        }
    }
}

