        (H % 2 == 0 && W % 2 == 1 && dp[1] == 0 && dp[3] == 0 && dp[2] <= H / 2) ||
        (H % 2 == 1 && W % 2 == 0 && dp[1] == 0 && dp[3] == 0 && dp[2] <= W / 2) ||
        (H % 2 == 1 && W % 2 == 1 && dp[1] + dp[3] <= 1 && dp[2] + dp[3] <= H / 2 + W / 2) { "Yes" }
        else { "No" };

    println!("{}", ans);
}

