    }
    required[4] = (h * w - required[2] * 2 - required[1]) / 4;

    let mut merged_count = vec![0; 5];
    for i in 0..26 {
        let mut c = count[i];
        if c % 2 == 1 {
            c -= 1;
            merged_count[1] += 1;
        }
        if c % 4 == 2 {
