fn solve(h: usize, w: usize, a: Vec<String>) -> bool {
    let counter = {
        let mut counter = [0; 26];
        for s in a.into_iter() {
            for &c in s.as_bytes() {
                counter[c as usize - 'a' as usize] += 1;
            }
        }
        counter
    };

    if h % 2 == 0 && w % 2 == 0 {
        return counter.into_iter().all(|n| n % 4 == 0);
    }
    let num_odds = counter.iter().filter(|&n| n % 2 == 1).count();
    let num_mod2s = counter.iter().filter(|&n| n % 2 == 0 && n % 4 > 0).count();
    if h % 2 == 0 {
        num_odds == 0 && 2 * num_mod2s <= h
    } else if w % 2 == 0 {
        num_odds == 0 && 2 * num_mod2s <= w
    } else {
        num_odds == 1 && 2 * num_mod2s <= h + w - 2
    }
}


