    assert_eq!(solve("2 2\naa\nbb\n"), "No\n");
    assert_eq!(solve("5 1\nt\nw\ne\ne\nt\n"), "Yes\n");
    assert_eq!(solve("2 5\nabxba\nabyba\n"), "No\n");
    assert_eq!(solve("1 1\nz\n"), "Yes\n");
