fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let crd = |c: char| c as usize - 'a' as usize;
    let mut cnt = vec![0; crd('z') + 1];
    for _ in 0..h {
        let s = sc.get().chars();
        for c in s {
            cnt[crd(c)] += 1;
        }
    }
    let mut c1 = 0;
    let mut c2 = 0;
    for mut c in cnt {
        if c & 1 == 1 {
            c1 += 1;
        }
        c >>= 1;
        if c & 1 == 1 {
            c2 += 1;
        }
    }
    let (a1, a2) = match (h & 1, w & 1) {
        (0, 0) => (0, 0),
        (1, 1) => (1, (h + w) / 2 - 1),
        (1, 0) => (0, w / 2),
        (0, 1) => (0, h / 2),
        (_, _) => unreachable!(),
    };
    if c1 == a1 && c2 <= a2 && (a2-c2) & 1 == 0 {
        "Yes\n".to_string()
    } else {
        "No\n".to_string()
    }
}

