        }
    }

    mydbg!(w, h);
    mydbg!(e, o);
    if w % 2 == 0 && e == w / 2 * h {
        if h % 2 == 0 {
            if e == h / 2 {
                println!("{}", "Yes");
                return;
            }
        } else {
            let c = o + (e - (h / 2 * w)) * 2;
            if c == w {
                println!("{}", "Yes");
                return;
            }
        }
    }

    if w % 2 == 1 {
        let c = o + (e - (w / 2 * h)) * 2;
        mydbg!(c, h);
        if c == h {
            if h % 2 == 0 {
                if e == h / 2 {
                    println!("{}", "Yes");
                    return;
                }
            } else {
                let c = o + (e - (h / 2 * w)) * 2;
                if c == h {
