fn solve() {
    let (h, w) = get!(usize, usize);

    let grid: Vec<Vec<char>> = (0..h).map(|_| util::chars()).collect();

    let mut p4 = 0;
    let mut p2 = 0;

    match (h % 2 == 0, w % 2 == 0) {
        (true, true) => {
            p4 = h * 4 / 4;
        }
        (true, false) => {
            p4 = (h * (w - 1)) / 4;
            p2 = h / 2;
        }
        (false, true) => {
            p4 = (w * (h - 1)) / 4;
            p2 = w / 2;
        }
        (false, false) => {
            p4 = (h - 1) * (w - 1) / 4;
            p2 = (h + w - 2) / 2;
        }
    }

    let mut alpha = vec![0; 26];

    // debug!(p4, p2);

    for i in 0..h {
        for j in 0..w {
            let a = grid[i][j] as usize - 'a' as usize;
            alpha[a] += 1;
        }
    }

    for i in 0..26 {
        let d = min(alpha[i] / 4, p4);
        alpha[i] -= 4 * d;
        p4 -= d;
    }

    for i in 0..26 {
        let d = min(alpha[i] / 2, p2);
        alpha[i] -= 2 * d;
        p2 -= d;
    }

    if p4 == 0 && p2 == 0 {
        println!("Yes");
    } else {
        println!("No");
    }
}

